window.__D("text/maamarei-admur-haemtzai/c009",{"p":[[1900640304,"בבחי' גבו' עליונות דקדו' שמשם ירדו למטה כ\"כ. וזהו ענין השריפה דפרה מחוץ למחנה שכינה שע\"י שריפה זו תכלה כל חלקי ההרכבה שבה מרע דק\"נ ולא ישאר רק האפר שהוא העצם הפשוט שאיננו כלה כנ\"ל, והוא עולה בשרשו הראשון בגבו' עליוני' דב\"ן דתוהו שאינו אלא עצם פשוט בהתפעלו' עצמי' דחומר הפשוט אחר כלו' כל חלקי ההרכבה כו' כנ\"ל שהוא רק בחי' גבו' דקדוש' האלקי' en.בתכלי' התכללו' האמיתי וד\"ל.\n<b>ודוגמא</b> לדבר זה הוא כמ\"ש דוד ואני בהמות הייתי עמך פי' בהתפעלו' עצמיו' דלב בשר שבחלל השמאלי [ש] נק' בהמה שלמטה מן הדעת [כו' והוא באמת למעלה מן הדעת] רק רצון עצמי כנ\"ל, וכן א' לבי ובשרי ירננו אל אל חי לבי ובשרי ממש בוער כאש בוערת בבהמה בלא דעת כלל, שזהו אחר כליון באש שלהבת י\"ה כל חלקי ההרכבה דגבו' קשו' דרע שבלב בשר לגמרי רק לה' לבדו וד\"ל (וזהו אפ\"ר א' פ\"ר דא' זה למעלה מבחי' אדם א' דם ולכך הי' אפר פרה שרש לכל העלא' מ\"ן דכנ\"י בכל המדריגו' שבאוי\"ר ומוחי' כו' שאינן רק הרכבו' המסתעפי' מהעצמיו' כולל הכל וד\"ל).\n<b>ומעתה</b> יש להבין ענין נתינת מים [חיים] אל כלי דכתי' ונתן עליו מים חיים כו' דהנה גם לאחר ששרפו את הפרה והי' לאפר ששרשו בגבו' דקדוש' כנ\"ל אין זה המתקה גמורה עדיין אע\"פ שנמתקו הגבורו' קשו' דפרה דק\"נ בשרשן מ\"מ צריך שיומתקו במים חיים דוקא, ויש להבין תחלה ענין המים חיים דוקא דמי מקוה פסולי' למי חטא' כידוע, להיות מבואר למעלה בענין ויפח באפיו נשמת חיים דגופו של אדה\"ר הי' מעפר חומר פשוט מוכן לקבל הצורה, אע\"פ שהי' בעפר גופו בהעלם כו' מה שעתיד לבא בו בגילוי כענין הכל הי' מן העפר כנ\"ל מ\"מ הוצרך שיומשך בו נשמ' עליונה דפרחא מחי העולמי' ממש, כי אין חומר בלא צורה רק שהחומר מוכן לקבל הצורה ולפי ערך קבלתו כך יהי' ערך מעלת האור והחיות הנמשך בו כו', ולפי שנעוץ תחילתן בסופן דוקא ע\"כ בעפר חומר גופו דוקא נמשך מבחי' אור גבוה כ\"כ שהוא בחי' נשמ' חי העולמי', וידוע דשרש הנשמ' הכללי' באה מאי\"ן לי\"ש והיינו מבחי' אין האמיתי שזהו בחי' עצמו' אא\"ס"],[1900640305,"ב\"ה וכמ\"ש ויפח באפיו [נ\"ח] מאן דנפח כו' והיינו מבחי' פנימי' חכ' הקדומ' שבעצמו' שע\"ז נאמ' והחכמ' מאין תמצא פי' מאי\"ן העצמיו' תמצא [ב] בחי' יש (וע\"כ בכלל נק' גם א\"ק אדם דבריאה י\"ש מאי\"ן כו'), והיינו כאשר הנשמ' הכללי' דאדה\"ר נמצאת בבחי' יש בגופו ה\"ז מאי\"ן לי\"ש ממש וטרם בואה בגוף היתה כלולה ומתאחדת בבחי' אי\"ן העצמי' ממש, [ו] ירידתה אינו לצורך עצמה כלל כ\"א שתהי' צורה לחומר הגוף דאדה\"ר לתקנו והוא להמתיק הדינין לעשו' מי\"ש אין כידוע, ונמצא שביטול הגוף לאור הנשמ' זהו היפך מי\"ש לאי\"ן ויריד' הנשמ' בגוף להפוך מי\"ש לאי\"ן הוא בא מאי\"ן לי\"ש, ואע\"פ שלא הי' בגופו של אדה\"ר שום רע וגסו' כלל כנ\"ל מ\"מ נק' בשם יש וחומר עכ\"פ רק שהוא חומר טהור וקדוש כקדושת קרקע המשכן כו', ובדוגמא זאת יהי' [בתחה\"מ ד] לע\"ל שישכון אור האלקי דנשמו' בגופי' טהורי' ויחי' מחי' אור עולם שזהו ג\"כ בבחי' אין ויש בחומר וצורה כנ\"ל. וזהו ג\"כ ענין מים חיים באפר הפרה דהנה זה האפר הוא חומר פשוט אחר כלו' כל ההרכבה דגבו' קשו' דק\"נ לגמרי כנ\"ל, שזהו כענין תכלית טהרת הטומאה שיהי' בתח\"ה דלע\"ל וכגוף טהור דאדה\"ר שאין זה רק כ[מו] חומר טוב לקבל הצורה כך צריך שיותן מים חיים על אפר זה לאחר שיצא ממנו כל ההרכבה הרע כו', וענין המים חיים הללו היינו בחי' המשכות בחי' מים עליוני' דאור ח\"ע שמאי\"ן העצמי ממש תמצא כנ\"ל בנשמ' אדה\"ר ממש [עד] שמים [חיים] הללו הן כמו צורה פשוטה לחומר פשוט דאפר פרה ואז דוקא יש בכחו לטהר טמאי' שזהו ממש ענין תח\"ה דלע\"ל וכמשי\"ת בע\"ה).\n<b>וביאור</b> שרש ענין מים חיים דוקא הנה ידוע בענין לרוקע הארץ על המים דמי התהום הן תחת הארץ והן שירדו מלמעלה למטה כשגער בהן וא' יקוו המים כו' כמ\"ש במ\"א באריכו', והנה לכאורה אין הפרש בעצם בין מ\"ע למ\"ת מאחר שלא הובדלו רק ע\"י הרקיע לבד כמ\"ש יהי רקיע כו', וגם אם ירדו מ\"ת עוד למטה מתחת לארץ ע\"י גערה בנזיפה מ\"מ לא הורע כוחם כאשר הי' בתחלה מעל השמים מעורבי' במ\"ע, שהרי א' ביום ההוא יצאו מ\"ח מירושלים חציי' אל הים"],[1900640306,"הקדמוני וחציי' אל הים האחרון הרי חציים עכ\"פ יעלו לים הקדמוני שהן מ\"ע, וידוע דים הקדמוני הוא מ\"ע שעלו למעלה בתכלי' וים האחרון הוא אשר ירד למטה בתכלי', וזהו שא' שמים לרום וארץ לעומק שזהו ענין עומק רום ועומק תחת דים האחרון היינו התהום שעומקו לתחת בלי שיעור וים הקדמוני היינו עומק רום דשמים בלי שיעור למעלה, ואע\"פ שמ\"ע עלו מאד ומ\"ת ירדו מאד עד שזה נק' עומק רום בתכלי' וזה נק' עומק תחת [ב] תכלית, משרש א' [ממש] נמשכו בתחלה והיו לאחדי' ממש רק עפ\"י צווי ה' מים עליוני' עלו [מאד] ומ\"ת ירדו מאד ונתרחקו זה מזה בתכלית זה נק' ים הקדמוני וזה נק' ים האחרון, וראי' לזה ממה שיחוברו לע\"ל דכתי' ומלאה הארץ דעה [את ה'] כמים לים מכסים דהכונה כמים דים הקדמוני מכסי' לים האחרון, שאע\"פ שגם עתה הרי כל הנחלי' הולכי' אל הים וז\"ש ולמקוה המים קרא ימים שהוא התהום שנמשך בו מד' נהרות דג\"ע, אבל הרי א' והים איננו מלא מן הנחלים משא\"כ לע\"ל כמים לים מכסים שיתמלא ויכוסה הים ממים, ואין זה ודאי מן הנחלי' דעכשיו אלא ממ\"ע דוקא שהוא בחי' עומק רום שימלא לבחי' עומק תחת ולא [שום] דבר זולתו כנהר שיוצא מעדן והי' לד' ראשי' שאינו נק' עומק רום ע\"כ הים איננו מלא מהם וז\"ש כמים לים מכסים שזהו כמו פלא עכשיו ולא לע\"ל וד\"ל. אך מי הוא המחבר ומיחד מ\"ע במ\"ת שהוא ים הקדמוני אל הים האחרון כנ\"ל, זהו שא' ביום ההוא יצאו מ\"ח כו' ר\"ל מים חיים הללו שיצאו מירושלי' דוקא יתחלקו לשני חצאי' חציי' ילכו אל הים הקדמוני וחציים אל הים האחרון וא\"כ יהיו מ\"ח הללו כמו ממוצע שעל ידו יתחברו מ\"ע ומ\"ת והיינו בב' חצאי' דמ\"ח הללו וד\"ל. ולפ\"ז צ\"ל בהכרח שיש מעלה יתירה במ\"ח הללו יותר ממ\"ע ומ\"ת יחד עד שיש בכחו לחברם אע\"פ שזה בתכלי' הרום וזה בתכלי' העומק כו', והוא מפני שכל ממוצע גדול מב' ההפכי' דעמ\"ר ועמ\"ת הנ\"ל וע\"כ מ\"ח הללו חציים משפיע למ\"ע דים הקדמוני וחציים משפיע למ\"ת דים האחרון ומחברם יחד וד\"ל.\n<b>והנה</b> לכאורה זהו כדבר פלא ביותר מאין יש כח גדול כזה במ\"ח שיצאו מירושלים שישפיע למ\"ע ומ\"ת ויחברם יחד, הנה זהו שא' הטעם שיצאו מירושלים וביום ההוא דוקא, ועיקר הטעם [הוא] מה שנקראו מים חיים [וזהו] מב' טעמי' א' שיצאו מירושלי' וביום ההוא כו' דמשמע לפי הפשט דמ\"ע ומ\"ת דב' ימים הנ\"ל לא נקראו בשם מ\"ח כלל [רק] מים סתם אבל מים חיים אינן יוצאי' רק מירושלים כו'. והענין הוא כידוע דעיקר התהוות המ\"ח אינו אלא מן הארץ"],[1900640307,"בעומקה שמתחדשי' שם מים חדשי' נק' מ\"ח ולא מים זולתם גם לא מ\"ע ולא מ\"ת שנובע בארץ מן התהום וכ\"ש הד' נהרות דג\"ע שאינן מ\"ח כלל רק אשר יצאו [מירושלים] (שרחוק מג\"ע ט\"ו מעלו') מעומק עפר קרקע המשכן, ונמצא שאין יתרון מ\"ח הללו רק אשר יוצאי' מירושלים מעומק ארץ ויציאה זאת היינו בדרך עלי' והגבהה כמ\"ש חציים אל הים הקדמוני שזהו בהעלא' וגם ילכו מ\"ח הללו בדרך ירידה לים האחרון כניסוך המים בחג בניקבי השיתין שירד' עד התהום וכה\"ג וע\"כ המ\"ח הללו כמו ממוצע לחבר מ\"ע ומ\"ת כנ\"ל וד\"ל. וראי' לזה שיש כח גדול במ\"ח הללו שאינו אלא מצד הארץ דוקא הוא מ\"ש ארץ לא שבעה מים הרי מ\"ע דים נתמלא מהם כנ\"ל והארץ לא תשבע מהם א\"כ ודאי מזה הוראה גמורה שהארץ יש לה שרש גבוה יותר ממ\"ע שמעל לרקיע עד שלא תשבע כלל [ממ\"ע כו'] ובים נא' כמי\"ם לי\"ם מכסי' שתתמלא לפי שהארץ למעלה מים, ומ\"ש לרוקע הארץ על המים וכן מ\"ש לה' הארץ כו' על ימי' יסדה ועל נהרות כו' היינו לאחר שא' יקוו המים כו' הוא שיסד ארץ על המים אבל בשרשה ארץ למעלה מים וד\"ל.\n<b>והנה</b> להבין כל זה יש להקדים תחלה בענין הפלוגתא שבגמרא אם שמים קדמו לארץ או ארץ קדמה לשמי' כמ\"ש ביום עשות ה' אלקי' ארץ ושמים הזכיר ב' שמו' דה' אלקי' משא\"כ בשמים שקדמו לארץ א' רק בראשי' ברא אלקי' את השמים ואח\"כ הארץ. וביאור הדברים משום דנעוץ תחלתן בסופן דוקא וסוף מעשה עבמ\"ת כו' אך א\"כ לא הי' כח הסוף יותר מן התחלה וכמשל מים העולי' למעלה שלא יעלו יותר ממקור חוצבם בראשית ירידתם כמ\"ש בפרדס בענין או\"י ואו\"ח [ש] זהו ענין נעוץ סופן בתחלתן לבד כו' אבל מאין יוכל להיות שסוף מעשה תחלה למחשבה הקדומ' וכן ארץ קדמ' לשמי' כו', אלא צריך לומר שיש ב' מדריגו' א' או\"י ואו\"ח תחלה וסוף דנעוץ כו' והב' למעלה משניהם והוא ארץ שקדמ' כו', וכמ\"כ יובן במ\"ע ומים תחתוני' הנ\"ל שנק' יה\"ק ויה\"א שהוא [עמ\"ר] ועמ\"ת שהכל בבחי' א\"ס למעלה ולמטה גם בזה יש כח בממוצע שהוא במ\"ח הנ\"ל en.en.לחברם לפי שעולה על שניהם יחד ודוקא מארץ כו'."],[1900640308,"<b>וביאור</b> הדברי' בדרך קצרה וארוכה היינו כנ\"ל בענין אי\"ן וי\"ש האמיתי דהחכמ' מאין תמצא עד עומ\"ר בתכלי' למעלה עד אין קץ כו' נק' מ\"ע ויה\"ק וזהו שמים לרום, וכמו בזמן המבול שארובו' השמים ושמי השמים נפתחו כו' (וכך [ב] ת\"ר לחיי נח צד\"ע דאפתחו ארובו' דח\"ע כו' וגם מעיינו' תהום רבה שזהו עמ\"ת דח\"ת שירדו למטה להיות ביטול היש היותר אחרון לאי\"ן כו', וזהו שא' חכמו' בחוץ ח\"ע וח\"ת מ\"ע ומ\"ת הנ\"ל ועכ\"ז אינן מ\"ח כלל, דגם שבחי' או\"י ואו\"ח דח\"ע וח\"ת כשהן במקורן בבלתי שיעור למעלה ולמטה כידוע דאא\"ס למעלה [עד] כו' ולמטה עד כו' עכ\"ז אינן מגיעי' לבחי' מהו\"ע ממש שכוללם יחד והוא המחברם להיותו בעצם הרבה נעלה מהם כי הם לא נק' רק בחי' חו\"ג שבעצם כידוע. והנה מזה יובן עכ\"פ ענין בחי' הממוצע שבכחו לחבר מ\"ע ומ\"ת הללו דהיינו עמ\"ר ועמ\"ת שבעצמו' אא\"ס ממש היינו מ\"ש ביום יצאו מ\"ח מירושלי' דוקא, והענין הוא דתכלי' [עומק] בחי' האי\"ן דח\"ע למעלה ותכלי' ירידתו בבחי' האי\"ן בי\"ש הנה זהו מגיע רק באור א\"ס שנמשך מי\"ש האמיתי כמו שהוא בעצם ממש שכלול מב' מדריגו' הללו כנ\"ל, אבל בחי' עצמותו ומהותו כמו שהוא שנק' י\"ש האמיתי אין כל זה מגיע לו כלל וז\"ש בעוה\"ב להנחיל אוהבי י\"ש ממש מיש האמיתי כמ\"ש הנה אלקינו זה כמו שהוא במהו\"ע ממש כידוע, אך מ\"ח שיצאו מירושלי' דוקא הוא המגיע למהו\"ע ממש וע\"כ ב' חצאי' שבו יחבר למ\"ע ומ\"ת דיה\"ק ויה\"א כנ\"ל גם לאחר שנתרחקו מאד כנ\"ל והוא מ\"ש ארץ קדמה כו', דהנה מ\"ח הללו הוא שמתהווה ממש בבטן הארץ בחידוש גמור מי\"ש דעפר לאי\"ן שהמי\"ם שרשם מבחי' אין דמ\"ע ומתחדשי' מי\"ש דעפר היותר אחרון מוכרח מזה שזה גבוה מעמ\"ר ועמ\"ת הנ\"ל, דמה שמעומק תחת לא יגיע רק לעמ\"ר ולא יותר היינו מ\"ת דתהום אבל מ\"ח הללו שמתחדשי' ממש מיש דעפר זה לא הי' עדיין במ\"ע ומ\"ת כלל כי חידוש גמור הוא וע\"כ נק' מי\"ם חיי\"ם דוקא ומ\"ע ומ\"ת אינם מ\"ח כלל, וכ\"ז מוכרח שיש דעפר הארץ יש בו מבחי' היותר עליון על עמ\"ר ועמ\"ת הנ\"ל אשר ע\"כ מים הללו שמתחדשי' בו נק' מים חיים דוקא, והוא שעולה לי\"ש האמיתי ממש אע\"פ שאין כח זה באין דמ\"ע כלל רק במ\"ח דארץ דוקא הוא שמשפיע למ\"ע ומ\"ת יה\"ק ויה\"א ומחברם יחד כנ\"ל, וזהו דארץ לא שבעה מ\"ע ארץ דוקא ולא ים דמכסי' אותו מ\"ע כנ\"ל מטעם דארץ קדמ' בשרשה לעמ\"ר דשמי\"ם ועמ\"ת די\"ם כו' (וז\"ש על התורה לא בשמים היא בעמ\"ר ולא בי\"ם היא עמ\"ת שהן ח\"ע וח\"ת רק"],[1900640309,"באר\"ץ דוקא והוא סוף מעשה דנש\"י בגופי' שמעפר הארץ שבחי' העלא' מ\"ן שלהם בתו\"מ בפ\"מ בארץ דוקא זהו מ\"ח אשר יצאו מירושלי' [חציים] כו' כידוע, וז\"ש אל יתהלל חכם כו' כ\"א לעשו' חסד ומשפט וצדקה ג' קוין בארץ דוקא), ואין כל זה רק מפני ששרש הי\"ש דארץ נעוץ בתחלתו שהוא בחי' יש האמיתי וזהו שבעוה\"ב מקיום התו\"מ בפ\"מ דוקא א' להנחיל אוהבי י\"ש האמיתי, וז\"ש ה' אלקי' en.en.ארץ ושמים כו' שזה יותר עליון מאדה\"ר קודם החטא כמשי\"ת וד\"ל).\nואחר הקדמה הזאת"],[1900640024,"להבין מארז\"ל מפני מה ת\"ח נענשי' (בבניהם שאינם ת\"ח כו') משום דקרו לאנשי חמרי כו'. הנה יש להבין מארז\"ל שאין בן דוד בא אלא בדור שכולו זכאי או כולו חייב ולמה לא בדור שחציו זכאי או רובו זכאי כו'. אך הנה במאמר זה רמזו על ענין בירור עה\"ד טו\"ר, [להיות ידוע] שכל עיקר ענין הגלות הוא רק בחי' בירור דעה\"ד טו\"ר לברר הטוב מן הרע ולהבדיל ביניהן כמ\"ש להבדיל בין טמא לטהור כו', שזהו עיקר כל התו\"מ לפי [שבתערובות] טו\"ר יש לרע יניקה הרבה מן הטוב כו', ולזאת אמרו שא\"א שיבא בן דוד כ\"א בדור שכולו זכאי או כולו חייב שזהו המורה על תכלית ההבדלה בין טוב לרע ואין [בהם שום] תערובו' וחיבור זע\"ז כלל דהיינו או כולו זכאי בלי תערובת טוב ורע אפי' כ\"ש או להיפך, כי הנה כללו' נ\"י הן בציור קומת אדם וכמו שאיברי האדם כלולי' זה מזה בתע[רובות אור] וחיו' של זה בזה עד שגם הראש מקבל חיות מחיו' הרגל ע\"י גידי המוח שברגל ולהיפך גידי הרגל יש במוח עד שלא נמצא בבירור הבדלה בין ראש לסוף משפיע ומקבל כי [כ\"א] הוא משפיע לזולתו וגם מקבל הימנו, וכן הב' משפיע ומקבל כי כולם צריכי' זה לזה להיו' כי אחוזים וקשורים יחד ע\"י הגידי' והעורקי' כו', וזהו עיקר בחי' התיקון [דציור אדם בבחי'] ההתכללו' של כל האיברי' כו' כמ\"ש במ\"א (אשר לזה הי' מהפכת סדום באמרם שלי שלי שלך שלך כו' בחי' התוהו זת\"ז כו', ובחי' התיקון הוא שגם המשפיע יהי' בחי' מקבל וכמו הארץ ג\"כ שכל אקלים מקבל מזולתו ומשפיע לזולתו כו', וכמ\"ש ה' בחכמ' יסד ארץ בבחי'"],[1900640038,"התיקון כציור אדם ולכך נז' ציור איברי' בארץ עין הארץ טבור הארץ וכו' וכמ\"ש במ\"א באריכות), [ולזה רמזו רז\"ל] שכל ישראל ערבים זע\"ז ערבים ממש מפני שכל א' מקבל מזולתו ואין לו שלימו' החיות בלעדו, וכן הענין בענין טו\"ר שבכללו' נ\"י שערבים זה בזה ממש כי פגם [וחטא זולתו פוגם בו ממ] ש כמו בחסרון ופגם חיות הרגל יחסר ויפגם במוח שבראש כו', ולהיפך בחי' הטוב דתשובה ומע\"ט של זולתו [מוסיף אור] ותיקון בנפשו וה\"ז ממש כערבות גמורה כו', [וע\"כ גזרו אומר שא\"א שיבא בן] דוד בדור שחציו זכאי וחציו חייב מאחר שכולם ערבי' זה בזה כנ\"ל הרי אין כאן בחי' בירור בטו\"ר כלל כי בחציו הזכאי יש תערובו' הרע דחציו [הב', וכן להיפך בחציו החייב מאיר] ומלובש מבחי' הטוב דחצי הזכאי, וה\"ז ענין תערובת טו\"ר בתכלית בכללו' קומת ציור אדם דכנ\"י, [וזהו] כל [עיקר הגל] ות שטו\"ר מעורבי' מאד כו' [וב\"ד לא יבא כ\"א אחר תכלית ה] בירור וההבדלה בעה\"ד טו\"ר בכללו' נ\"י, ולזה גזרו אומר דאין בן דוד אלא בד[ור שכולו זכאי או שכולו חייב שזהו מורה על תכלית] ההבדלה בין טו\"ר [כנ\"ל וד\"ל.\n<b>אך</b> עדיין יש להבין] דבשלמא כולו זכאי יתכן שזהו שלימו' הבירור וההבדלה של הרע מן הט[וב עד שכולו נק' זכאי כו', אבל כולו חייב עדיין לא בא שום] תיקון לר[ע אלא עומד בשלימותו והרי זה כמו שהוא] בתערובת קשה עם הטוב ואיך אפשר שיבא ב\"ד בדור שכולו חיי[ב כו'. אבל הענין דכולו חייב אין הכוונה כולו חייב ממש שהרי א\"א שלא יהי' אחד צדיק בארץ או איך אפשר שלא ימצא] קצת טוב גם בפושעי ישראל שמלאים מצות [כרימון כידוע, אך עיקר הכוונה הוא דכולו זכאי או כולו חייב הוא רק ענין הבדלה בתכלית בין טוב לרע, שאין בטוב שום תערובות מן הרע וכולו זכאי ונקי מכל סיגים ולהיפוך אין ברע שום תערובות מן הטוב וכולו חייב, ולא כמו עכשיו שבטוב יש רע וברע יש טוב (וכמ\"ש בע\"ח דנוגה דבריאה רובו טוב ומיעוטו רע ונוגה דיצי' חציו טוב וחציו רע ונוגה דעשי' רובו רע כו'). וזה לא יהי' רק בזמן משיח שיושלם אז שלימות הבירור דעה\"ד טו\"ר. אך הנה תחלה י\"ל שרש ענין עה\"ד טו\"ר ולמה נק' עה\"ד"],[1900640051,"דוקא דמשמע שעיקר ענין תערובות טו\"ר תלוי בבחי' הדעת דוקא וכמ\"ש והייתם כאלקים יודעי טו\"ר כו' ובלא דעת לא ידעו טו\"ר ביחד בתערובות אלא כ\"א בפ\"ע דוקא אם יודע טוב לא ידע מן הרע כלל כנ\"ל (וכמו ולא ידעו כי ערומים הם כו'), ואם הוא ברע לא ידע מן הטוב כלל וכלל והוא הנק' בלה\"ק בשם תמים שהתמימות ענינו שהוא באותו דבר שהוא עושה או מדבר בתכלית התמימות והשלימות ובלי נטיי' כלל וכלל להיפוכו בין בבחי' החסד בין בבחי' הדין, והיינו אם הוא עושה וחפץ חסד וטוב כולו חסד וטוב בתכלית התמימות ואין בזה שום תערובות ונטיי' לדין כלל שלא ידע להעלים ולסבול דבר והיפוכו כלל, וכמו אם חפץ בדין ורע כולו כמו שהוא בבחי' הדין והרע בלי נטי' כלל וכלל לבחי' הטוב כי לא יוכל להעלים ולסבול דבר והיפוכו אלא או זה או זה, והן התחלקות הב' קוין חו\"ג שמובדל זמ\"ז בתכלית ההבדלה והריחוק עד שלא יתחברו לעולם כמו שאין מרחמים בדין כלל וכלל ואין עונשין בבחי' חסד כלל כי תכלית מדה\"ד לא יסבול לרחמים שהוא היפוכו בתכלית מן הקצה כמו שלא יסבול האש את המים, ולהיפוך בתכלית החסד לא יסבול לבחי' הדין כלל כמים שלא יסבלו האש כלל. ונמצא שיש בחי' התמימות בבחי' התחלקות הקוין להיות קו א' או כולו חסד או כולו דין] .\n<b>ומעתה</b> יש להבין מ\"ש תמים תהי' עם ה' אלקיך מה יתרון מעלה במדת התמימות דוקא אם שרשה באה מצד בחי' התחלקו' הקוין שחסר שם בחי' הדעת, וידוע שזהו ההפרש [בין] בחי' התיקון לבחי' התוהו שבתוהו התחלקו' [הקוין] חו\"ג זת\"ז כו' והתיקון ענינו בחי' ההתכללות של הקוין והוא ע\"י בחי' הדעת דוקא שהוא הקו האמצעי הסובל וכולל ב' הקוין ח[ו\"ג דבר] והיפוכו דוקא, וא\"כ לכאורה התמימות עם הדעת דבר והיפוכו, וידוע שנצטוו ישראל על בחי' הדעת דוקא כמ\"ש וידעת היום כו' דע את אלקי כו' למען דעת כו', וכה\"ג רבות בכתובים והדעת היפך התמימו' שהתמימו' עיקר שרשה בלא דעת דוקא אלא באמונה פשוטה ע\"כ הולך בתום לבבו שלא לנטות להיפוכו כלל וכלל כי לא ידע לסבול דבר והיפוכו כנ\"ל. אך הענין הוא דשניהם אמת וב' מצות הן מצות מדת התמימו' כמ\"ש תמים תהי' כו' והוא מדתו של יעקב שהי' איש תם והוא ג\"כ קו האמצעי"],[1900640063,"דוקא כידוע, ומצוה הב' הוא בחי' הדעת והכל א' ולא דבר והיפוכו כלל, ואמנם ב' מיני תמימות הן הא' שלמטה מן הדעת כתמימו' התינוק וע\"ה מצד חסרון הדעת אשר ע\"כ עושה הכל בתמימו' בבחי' קו א' לבד כנ\"ל, והב' התמימות שלאחר שלימות הדעת דוקא והוא מ\"ש תמים תהי' כו' אחרי קיום מ\"ע דוידעת כו' וכיעקב איש תם שהוא בקו האמצעי דוקא ולכך נק' ת\"ם ע\"ש השלימו' שהוא כלול מהכל כו', [ותחי] לה יש לבאר ענין התמימו' שלמטה מן הדעת, דהנה אנו רואי' בחוש בעיקר סיבת התערובת טו\"ר שאינו בא רק מצד בחי' הדעת דוקא ולכך נק' עץ הדעת דוקא כנ\"ל, שהרי אנו רואים בחוש בכל איש שהוא בר דעת יותר יותר יוכל לערב הטוב ברע ורע בטוב לחפות ולגנוז בתכלית זה בתוך זה עד שלא יוכר בין טוב לרע כלל וכלל, ע\"ד דוגמא כשיעשה מעשה טוב כמו החסד והצדקה לרבים כמו לבנות בה\"כ שמפזר הון רב ובתוכו גנוז ונעלם בחי' הרע שבו שאין כונתו לש\"ש כלל וכלל רק להתגדל ולקנות לו שם בלבד וכן בצדקה לעניים וכה\"ג, הנה אם איש תמים בלא דעת כשוטה וקטן וכה\"ג יוכר מיד הרע שבטוב הזה בהגלות לבו מיד שאין כונתו לש\"ש רק להתגדל כמו כאשר מתגאה ומתפאר ומתהלל בעצמו כו', אבל בבר דעת ידע היטב איך לחפות ולגנוז ולהעלים בתכלית לרע זה ויהי' כל דבריו ותנועותיו שעושה רק לש\"ש ולא להנאת עצמו כלל עד שיאמינו הכל שעושה לש\"ש ויחזיקוהו לצדיק כו', [וכן במצו] ת ת\"ת כשלומד של\"ש רק להתייהר ולקנטר או שיקראוהו רבי ובהנ\"ל הרי התמים שבלא דעת יוכר בו רע זה מיד כי יתגאה ויתהלל בחכמתו וחפץ מאד בגדולת רבנות שלזה עיקר כונתו [בלימודו כו'] אבל בר דעת מעלים ומחפה ביותר כל הרע הזה עד שלא יוכר כלל כי יעשה א\"ע שפל ועניו וכאילו לומד רק לשמה כו' עד שיאמינו בו הכל כו', וכך בכל הדברי' הטובי' שעושה מערב [הכל בהם בתכלית] היותר נאות עד שמתקבל כל הרע לטוב ממש, וכן להיפך יכול להיו' שלפי עין הרואה עושה דבר רע ובאמת מעורב וגנוז בזה בהעלם כונה טובה מאד שהוא טוב [גמור ומה שהוא עושה] רע הוא להעלים את הטוב ולגנזו מטעם הכמוס עמדו כמו ע\"ד דוגמא שעושה דין ועונש לרעהו באכזריו' שונות והמכוון בזה דוקא לטובתו כמו יוסף עם [אחיו שדיבר ע] מהם קשו' וכו' והי' זה לטובת נפשם להצילם מן הגיהנם כידוע, וזה לא יוכל רק הבר דעת ביותר שהוא לסבול דבר והיפוכו במוחו לערב ולכלול טוב ברע ורע בטוב כו', [וכל מי שהוא ד] עתן יותר יותר יסבול דבר והיפוכו דהיינו לעשות מטוב רע ומרע טוב וישכנו כא' עד שלא יוכר כלל בין טוב לרע כו', משא\"כ מי שאינו בר דעת כ\"כ לא ידע [איך לערב הרע] במעשה הטוב כלל אלא כשעושה טוב יעשה בתמימו' שבלא דעת כמו הקטני' וע\"ה חסירי הדעת"],[1900640075,"שיעשו הטוב בפשטות בלי שום כונה רעה כלל וכלל, ואם יעשה דבר רע לא יוכל להערים ולגנוז הרע ולחפותו בדרך מעשה הטוב אלא יוכר כמו שהוא בלי תערוב' ענין טוב כלל והוא ענין התמימו' שבלא דעת שבהם אין הטו\"ר כתערוב' כלל, אלא אדרבה כל א' מובדל לעצמו בלי נטי' להיפוכו כלל כי לא יסבול דבר והיפוכו כלל מצד קטנ' הדעת וכל שהוא בקטנו' הדעת יותר יותר לא יוכל להערים בכל דרכיו לערב טוב ברע ורע בטוב אלא או כולו טוב או כולו להיפך שהן ענין ב' קוין מחולקי' בלתי חיבור כלל כנ\"ל, ולכך נק' עץ הדעת טו\"ר לפי שעיקר ענין התערוב' דטו\"ר תלוי לפי ערך הדעת דוקא וכמ\"ש והייתם כאלקי' יודעי טו\"ר כו', והנה לכאורה מה מעלה יתירה בבחי' הדעת במה שסובל דבר והיפוכו, שלכאורה בחי' התמימו' שלמטה מן הדעת הרבה יותר אמיתי ויותר בירור בין טו\"ר כו', אך באמת נהפוך הוא שבחי' הבירור שע\"י הדעת בין טו\"ר הוא בתכלית הרבה יותר מן ההבדלה שבבחי' התמימו' שבלא דעת הנ\"ל, ואדרבה בתמימו' המעשה יוכל להיו' מצד חסרון הדעת אין מעשה הטוב באמת לאמיתו אלא מוטעה בעצם מפני שלא יצא מצד המנגדו כלל, משא\"כ ע\"י הדעת מצד התערוב' ב' הפכי' הנה מזה דוקא יבא סיבת הבירור בטו\"ר בתכלית והוא בחי' התמימו' הב' שלאחר הדעת דוקא, שהרי אם אין דעת אין הבדלה ולכך קבעו ההבדלה בחונן הדעת כידוע משום דבחכמ\"ה דוקא אתבריר\"ו כל תערוב' דעה\"ד טו\"ר שזהו עיקר כל התורה להבדיל בין טמא כו' כידוע וד\"ל.\n<b>וביאור</b> הדברי' הנה באמת יש להבין בשרש בחי' כח הדעת איך ביכולתו לסבול דבר והיפוכו בטו\"ר כנ\"ל, דלכאורה הרי טו\"ר ב' הפכי' הם כאש ומים וכן חו\"ג, ואיך יכללו זע\"ז ע\"י הדעת להיו' מטוב רע כו' עד שלא יוכר ביניהן כלל כנ\"ל. אך הענין הוא משום דשרש בחי' הדעת בקו האמצעי שמבריח לקצה העליון כו' שהוא למעלה מהתחלקו' הקוין לימין ושמאל עדיין ע\"כ הדעת כולל חו\"ג כא' להיותו למעלה משניהם, ולזה תלוי' שניהם בדעת נוטה להימין או להשמאל או לכוללם יחד כמו חוט המשקולת כידוע ומבואר במ\"א באריכו', וזהו הטעם שבכח הדעת לסבול ב' הפכי' דטו\"ר או חו\"ג ולהטו' מדבר להיפוכו או לכוללם באופני' שונים עד אשר נראה הרע לטוב והטוב לרע כנ\"ל, כי קו האמצעי בכחו לחבר ולעשו' התכללו' גמור בב' הקוין מצד שרשו שלמעלה מהתחלקו' שלהם כו' והוא בחי' יעקב איש תם שכלול מחו\"ג כו', ואמנם מה שנק' ת\"ם היפך התערובת טו\"ר דוקא כנ\"ל היינו לפי שע\"י בחי' הדעת דוקא נתברר ונבדל התערוב' דטו\"ר או en.חו\"ג כו' עד שנק' ת\"ם בבחי' השלימו' העליון שלמעלה מחו\"ג כו'."],[1900640086,"<b>וביאור</b> הדבר הנה אנו רואי' שעיקר ההבדלה בטו\"ר הוא ע\"י הדעת דוקא ולכך קבעו הבדלה בחונן הדעת שאם אין דעת אין הבדלה כלל בין טו\"ר בין אור לחושך כו' אלא בערבוביא המה כו', לפי שאנו רואי' בכל כשרון המעשה טוב שאין לה כשרון השלם בתכלית ברור ונקי מכל סיג ופסולת כמו תערובת שקר וכונה רעה וזרה כו' לגמרי מכל וכל בלי טעות כלל רק ע\"י הדעת מפני שהוא הבוחן ומבחין היטב בהבדלת הרע מן הטוב בתכלית, וכל שהוא בר דעת יותר יותר יבחין בכל תערובת רע גם דק שבדקו' שבמעשה הטוב, ולהיפך כשאינו בר דעת כ\"כ לא יבחין כ\"כ בדק שבדקו' הרע המעורב במעשה הטוב שלו, וכן במעשה הרע ע\"י הדעת יבדיל יותר כל בחי' הטוב שיתערב ברע עד הדק שבדקו' עד שיהי' רע בתכלית מובדל מן הטוב כו' דהיינו שלא יטעה א\"ע לחשוב איזה כונה טובה בדבר רעה כמו ע\"ד דוגמא אם כונתו באמת להתייהר בצדקה ות\"ת אם הוא בר דעת לא יטעה א\"ע ויודע היטב שאין דבר הטוב בזה כלל, משא\"כ מי שאינו בר דעת כ\"כ לא יבחין בזה ויהי' כשר וישר בעיניו באמת ולא ירגיש כלל ברע הגנוז בטוב שלו כי אין שוטה מרגיש ויוסיף דעת יוסיף להרגיש כו', ונמצא ע\"י הדעת יוכל להיו' ב' הפכי' א' עיקר התערובת דטו\"ר כנ\"ל ועיקר ההבדלה דטו\"ר, וכל זה מצד שרשו למעלה מהתחלקו' חו\"ג כנ\"ל ע\"כ בכחו לעשו' דבר והיפוכו תערובת והבדלה, ושניהם מכח א' באו אע\"פ שהן דבר והיפוכו כו' מאחר שהוא עצמו למעלה מחו\"ג אין זה דבר והיפוכו אצלו כלל אדרבה שניהם שוין, וזהו מפני שכח ההתכללו' והתערובו' שיש בקו האמצעי עד שנק' תם ושלם להיותו כלול מהכל ולא דבר א' לבד שאינו שלם מצד המנגדו היינו מכח זה עצמו מה שנק' תם בשלימו' העליון שלמעלה מחו\"ג שלזה הוא העושה ההבדלה וכמ\"ש אם אין דעת אין הבדלה כנ\"ל, וזהו שיעקב נק' תם מב' טעמים הללו שהן ענין א' ממש וד\"ל. ונמצא לפ\"ז ענין קריאת שם עץ הדעת שיודע את הטוב ואת הרע היינו שאינו בבחי' קו א' לבד כענין התמימו' שלמטה מן הדעת הנ\"ל בתינוקו' וחסירי הדעת אלא מבחין ויודע כל תערובו' והתכללו' טוב ברע ורע בטוב כנ\"ל, ולהיפך ג\"כ להבחין ולהבדיל בין טו\"ר בתכלית ההבדלה, וזהו עיקר הידיעה שיודע טו\"ר לברר ולהבדיל ביניהן והכל מכח א' בא מצד שרש הדעת למעלה מהתחלקו' טו\"ר כנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן ענין מצות התמימות מ\"ש תמי\"ם תהי' כו' שאין הכונה בלא דעת כלל שהרי נא' וידעת כו' אלא על בחי' התמימו' שאחר ההבדלה בתכלית שע\"י הדעת דוקא כנ\"ל, שאז הוא נק' תמים באמת בלי שום תערובת כלל מטעם"],[1900640097,"הנ\"ל, וכמ\"ש ראה נתתי לפניך החיים והטוב כו' ובחר\"ת בחיים ובחיר\"ה זו ע\"י הדעת המבדיל ובוח\"ר בטוב ומואס ברע בתכלית ואם אין דעת אין בחירה והבדלה כלל כנ\"ל, ואז נק' תמי\"ם במעשיו ע\"ש השלימו' (משא\"כ בלא דעת כבן י\"ב שנה שאין לו דעת אינו נענש על ל\"ת כלל כי מ\"ע ול\"ת הן ה\"ח וה\"ג שנק' טו\"ר, והדעת מבדיל ביניהן והוא כולל אוי\"ר אהבה שרש מ\"ע כו' ואינו בר עונשין כ\"א בגדלו' די\"ג שנה שבא לכלל דעת אע\"פ שהוא ע\"ה ואותו שהוא בן י\"ב הוא חריף כו'), וגם זה אמת דנק' תמים ע\"ש התמימו' והשלימו' להיותו כלול מהכל אוי\"ר חו\"ג ולא קו א' לבד כיעקב שנק' תם להיותו כלול מחו\"ג כנ\"ל (אך הנה באמת מ\"ש תמים תהי' וכן התהלך לפני והי' תמים הכונה על למעלה מן הדעת דוקא והוא בחי' אמונה הפשוטה בתכלית שלמעלה מן הדעת לגמרי עד שלא יתכן ענין ברירה אלא רצון עצמי ופשוט, וכידוע [בפי'] ואני בהמות [הייתי עמך בהמה שלמטה] מן הדעת ששרשו למעלה מן הדעת כו', וראי' לזה ממ\"ש תמי\"ם תהי' עיקר כונת האזהרה הוא על הנסיון שלא לנסות את [הוי' רק להאמין ולבטוח בו בבחי' התמימות שהוא] האמונה הפשוטה שלמעלה מן הדעת דוקא כדמוכח פשט הכתובי' בענין מצות התמימות [וכמ\"ש כל המפרשים, ובפרט בענין המצות להרמב\"ם והסמ\"ג בפי' מצוה זו דתמים] תהי' כו' ומ\"ש וידעת כו' מצוה בפ\"ע היא en.כי צריך להיו' [ע\"י] הדעת [וע\"י האמונה והתמימות)] .\n<b></b>[והנה ידו] ע שיש בענין התערובות כמה מיני מדרגות שונות, הא' אם התערובת בחצי עם חצי או מיעוט ברוב עד שיהי' התערובת מן הקצה לקצה דהיינו חלק א' מאלף אלפי' טוב ברע שנמצא כולו רע ורק חלק א' מאלף אלפי' טוב כלול"],[1900640108,"בו, וכן להיפך חלק א' מאלף אלפי' רע בטוב שנמצא כולו טוב רק חלק א' אלף אלפי' רע נמצא בו עד שזה נק' צדיק גמור מפני שכולו טוב רק מצד חלק א' מאלף אלפי' רע שבו נק' צדיק ורע לו ולא נק' צדיק גמו\"ר רק כשאין בו רע כל עיקר רק טוב, וזהו צדיק וטוב לו רק טוב וכן להיפך רשע גמור היינו כשכולו רע ואין בו טוב כלל וכלל, אבל כשיש בו טוב גם חלק א' מאלפי אלפי' נק' רשע וטו\"ב ל\"ו ולא נק' רשע גמור כו' כי בחי' צדיק גמור ורשע גמור אינו אלא כשנבדלי' טו\"ר בתכלית עד שאין לזה בזה גם חלק מאלף אלפי' כו', והוא לאחר שלימות הבירור דעה\"ד טו\"ר בתכלית הקצה האחרון, אבל עכשיו נא' אין צדיק בארץ שיעשה טוב ולא יחטא כי יש תערובת טו\"ר עדיין גם בצדיקי' שבארץ, וכך ממילא בהכרח שנמצא איזה תערובת טוב במקצת גם ברשעי' כו'. והנה מבואר למעלה בענין ציור קומת אדם בכנ\"י ראש ורגל כו' שערבים זה בזה בבחי' ההתכללו' כמו שהראש מקבל חיו' מן הרגל וצריך המשפיע להיות מקבל כו' שזהו עיקר בחי' התיקון כמ\"ש למעלה באריכו', ולפ\"ז גם בענין צדיקי' ורשעים שבכנ\"י בכלל ופרט הרי בהכרח שערבים זה בזה ג\"כ ע\"ד דוגמא אותן שהן מבחי' הראש ומוחי' כו' הרי יש הרבה שהן צדיקי' גדולי' ונק' ראשי אלפי כו' המלמדי' לעם תורה ודעת כו' ולנגד זה יש הרבה רשעים שהם חכמי' גדולי' להרע ולהיטב לא ידעו והמה הראשים המושלים ורודי' בעם לעשות רק רע כו' כידוע, וכה\"ג יש הרבה צדיקי' בלב טוב מבחי' המדו' אוי\"ר וכו' ולנגדם הרבה רשעי' מבחי' לב רע בכל מיני מדו' רעות, וכך בבחי' נשמו' שבעקביי' בהליכה בדרכי הטוב או בדרכי הרע כו' עד שיוכל להיו' דרך פרט ב' נשמו' דצדיק ורשע שהן ממקום אחד יצאו כמו בחי' היד או הרגל וכה\"ג והמה משרש א' רק זה כולו טוב וזה כולו רע, ואמנם קצת בחי' הטוב שברע אשר ברשע הרי הוא מתאחד עם הטוב שבצדיק וקצת הרע שבצדי[ק מתאחד עם בחי' הרע שברשע] , עד\"מ טעם המרירו' במקצת שנותן טעמו לפגם בכל הפרי הטוב ולהיפך טעם המתיקו' במקצת נותן טעם לשבח בכל הפרי הרע כו' מאחר שגוף א' הן, וכך צדי[ק ורע לו עם רשע וטוב] לו מתאחדי' וערבים זה בזה עד אשר הצדיק נענש בעבור רשעת הרשע שהוא משרשו והרשע יזכה בעבור צדקת הצדיק שהוא משרשו כו', ואע\"פ שאמרו דצדיק [ורשע לא קאמר] כי תלוי בבחירה וזה בוחר בטוב ומואס ברע וזה להיפך, עכ\"ז א' מועיל לחבירו מצד שרשם שהוא במקום א', וראי' ממה שאמרו זכה נוטל חלקו וחלק חבירו בג\"ע לא [זכה נוטל חלקו וחלק]"],[1900640119,"חבירו בגיהנם כו', וכמשל האיברי' שכל א' נק' משפיע ומקבל כי מתכללי' זע\"ז, א\"כ יש אחיזה לרשע עם הצדיק דהיינו שהצדיק מקבל חלק הטוב שברשע בג\"ע ולהיפך [הרשע נוטל חלק] הרע שבצדיק בגיהנם וניתתקן על ידי זה (וכמ\"ש במ\"א בענין מוריד שאול ויעל כו', אך מ\"ש ביחזקאל נח דניאל ואיוב המה בצדקתם ימלטו כו' הרי לכאורה אין חיבור [לצדיק ורשע היינו] ביחידים שבדור כמו נח בדורו כו', ואדרבה ראי' להיפך ממה שאמרו צדיק נתפס בעון הדור וכמ\"ש הצדיק אבד לדורו אבד כו'), וז\"ש ז\"ל כל ישראל יש להם חלק לעוה[\"ב אפי' רשע ורע לו] ע\"י שנמצא בו קצת טוב במעשה המצות, שהרי אפי' פושעי ישראל מלאי' מצות כרימון ולכך נא' ועמך כולם צדיקים כו' (ולכך א' במדרש ע\"פ אספו לי חסידי כו' אלו פושעי ישראל הנקראי' בשם חסידים, והוא מטעם הנ\"ל בענין כל ישראל ערבים זה בזה מאחר שהמה בציור קומה שהחסידי' וצדיקי' מקבלי' מן הטוב שברשעי' ואז נק' בשם חסידי' או צדיקי' וכמ\"ש ועמך כולם צדיקי'), וכתיב כולך יפה רעייתי מו\"ם אין בך והגם שע\"י מעשה הרשעי' נפגם הרבה איברי' מ\"מ ע\"י תשובה ומע\"ט נמשך רפואה ושלימו' להשלים כל פגם כו' מצד קצת חלק הטוב שברשע שמתאחד בטוב הגדול שבצדיקי', משא\"כ אם הי' כולו רע אין לו תקוה ורפואה כלל כבשר המת, כמ\"ש על רשע גמור לא אחפוץ במות המת מ\"ת מעיקרו כו', ואז אין לצדיקי' מה לקבל טוב מן הרשעים אלא רק איבודם זהו תיקונם כמשל העלוקה כו', וזה יהי' לע\"ל שיהי' תכלית הבירור בעה\"ד טו\"ר עד שלא ישאר ברע שום תערוב' טוב אפי' בחלק א' מאלפי אלפי' רבבו' כו', ולכך איתא בר\"מ דלע\"ל דאילנא דטו\"ר יתעבר מעלמא כו' לא יצטרכו ת\"ח לקבל מע\"ה כי יהיו מובדלי' זה מזה בתכלית הקצה כו', אבל עכשיו בזמן הבירור דעה\"ד טו\"ר שעדיין נמצא קצת תערובת טוב ברע ורע בטוב יש בצדיקי' ורשעי' בחי' חיבור והתכללו'"],[1900640130,"כמו התכללו' האיברי' עד שיצטרך הצדיק לקבל השפעת טוב מניצוץ חלק א' טו\"ב מן אלף אלפי' חלקי' רע שברשע, וכן נשלם ונתקן חלק א' רע שבאלפי אלפי' חלקי' טוב שבצדיק כי נתברר אותו מקצת הרע שבצדיק דוקא ע\"י אותו מקצת הטוב שברשע שמשפיע לצדיק מפני שערבים זה בזה כנ\"ל וד\"ל.\n<b>ובכל</b> זה יובן מארז\"ל מפני ת\"ח נענשי' משום דקרו לאינשי חמרי כו', דהנה ת\"ח המה הצדיקי' ראשי אלפי כו' שכל עסקיהם בתו\"מ רק טוב ולא יוכלו לסבול את הרע שברשעים עד שנמשלו כבהמות בעיניהם וקרו להו חמרי כמו אשר בשר חמורים כו' לפי שהנשמה האלקי' נק' אד\"ם כשהיא בצלם האלקי' בשלימות בתו\"מ ברמ\"ח פקודי' רמ\"ח איברי', וכשחסר מצוה א' נפגם אבר א' כו', אך זהו במיעוט מעשה הטוב או ע\"י פגם איזה ל\"ת אשר אין צדיק בארץ שלא ימצא בו קצת רע ונק' צדיק ורע לו כנ\"ל, אמנם להיפך ברשעי' הגמורים שלא נמצא בהם אפי' קצת טוב גם חלק כל שהוא מהראוי לקרותם חמר\"י ממש דהיינו שאין בנפשם צלם האלקי כלל וכלל רק כבהמו' נדמו ממש, ולא עוד אלא שנק' חמר\"י כקליפת חמור לנגד חכמי' דקדושה כמ\"ש בזוהר ע\"פ ויהי לי שור וחמור, וכמו שא' ר\"ע כשהייתי ע\"ה כו' אנשכנ\"ו כחמו\"ר ובקדוש' נא' יששכר חמו\"ר גרם כו' כחמור למשא וכחמורו של רפב\"י, ומה דקרו לאינש\"י חמר\"י אינש\"י היינו הע\"ה דוקא שהן לעומת ת\"ח כידוע, אך הנה כל זה יתכן לאחר שלימות הבירור דעה\"ד טו\"ר שאז הת\"ח בתכלית השלימות ואין בהם תערוב' מן הרע אפי' כל שהוא, ואז הע\"ה נק' חמר\"י לגביהם נבדלי' מבחי' אדם, כי הת\"ח לא יצטרכו לקבל אז שום אור ושפע טוב מן הרשעי' מאחר שלא ימצא שום טוב ברשעי' כנ\"ל, אבל עכשיו בזמן הבירור דעה\"ד טו\"ר שעדיין הטוב מקבל מן הרע והרע מן הטוב גם כחלק א' מאלפי אלפי' עכ\"פ כנ\"ל, א\"כ גם הת\"ח צריכי' להיות בחי' מקבל שפע מאינש\"י שהן הע\"ה לקבל מהם בחי' חלק א' מאלף כו' טוב שבהם ועי\"ז נברר ונתקן כל בחי' מקצת הרע חלק א' מאלף כו' שבנפש הת\"ח וצדיק ורע לו הנ\"ל, וזהו הטעם שהת\"ח נענשי' על דקרו לאינשי חמרי כי בזה הרי נבדלו מהם בתכלית ואינם מקבלי' מאינשי"],[1900640141,"הללו בחי' הטוב במקצת שבהם וא\"כ הרי לא נשלם חלק המקצת רע שבנפש הת\"ח ומצד ב' טעמים נענשי' הא' מפני שמפסידי' נפשם שלא יש תקוה לחלק מקצת הרע שבהם שנמשך אחר הרע שבאינשי הללו ואם היו אחוזי' ומקושרי' בהם בציור אדם הי' זה תיקון ע\"י העלא' הטוב מן הרשע כנ\"ל והב' מה שמפרידי' את הע\"ה לבלתי יהי' להם תקומה להתעלו' ע\"י הצדיקי' ות\"ח במה דקרו להו חמר\"י ממש להבדילם מבחי' אד\"ם העליון שבזה נאבד גם מקצת הטוב שבע\"ה לדחותו בב' ידים וכתי' לבלתי ידח ממנו נדח כי לא נודע מי יכשר כו' לפי שנעוץ תחלתן בסופן וסופן בתחלתן, ואפשר יעלה לרצון אותו מעט הטוב שבע\"ה יותר מריבוי הטוב שבת\"ח שנק' ראש, כי הרי יוכל להיו' ברגל הרבה כח ועוז יותר מבראש, ולזה אמר ת\"ר אלף רגלי העם אשר אנכי בקרבו, אנכ\"י דוקא מפני שנעוץ תחלתן בסופן דוקא, ולזה א' יש צדיקי' שיגיע אליהם כמעשה הרשעי' ויש רשעי' כו' וד\"ל, אך לע\"ל שיובדלו טו\"ר בתכלית אין לראשי' הנק' ת\"ח חיבור כלל עם הע\"ה כי יתבררו גם בחי' העקביי' כו', ולכך אין בן דוד בא אלא בדור שכולו זכאי להיו' רק טוב או כולו חייב רק רע שאז אין הטוב מקבל מן הרע כלל, ואז הצדיק שיהי' בארץ יהי' רק טוב והוא תכלית השלימו' של בחי' אד\"ם שנא' במשיח ישכיל עבדי כו' (אך מה שהעונש של ת\"ח דקרו לאינשי חמר\"י הוא רק בבניהם שאינם ת\"ח ולא בהם עצמם כי בחי' אד\"ם הוא בחי' התולדה להוליד בדומה לצלמו דוקא, ולפי שהבדיל לע\"ה שהן בבחי' נה\"י מבחי' אדם חסר בנפשו מבחי' נה\"י ולא יולי\"ד בדומה לו כי לא יוכל להיו' בחי' שלימו' בהתפשט\"ו' תולדתו דוקא שהוא מבחי' נה\"י שזהו שרש של הע\"ה אע\"פ שהמוחי' בשלימו' ועיקר התולדה מן המוחי' דוקא אבל להוליד נפש בבחי' מוחי' כמוהו לא יוליד משום שנעוץ תחלתן בסופן דוקא (וכמ\"ש במ\"א בפי' אל עליון גומל כו'), וא\"כ הרי זה העונש לפי העון מה דקרו לאינש\"י חמר\"י זאת תהי' פרי תולדותיהן של צדיקי' ות\"ח להוליד ע\"ה אשר שנא נפשו ולהיפך המלמד [את בן ע\"ה תורה כו' זוכה שיהיו בני בנים] ת\"ח וכמ\"ש לא ימוש מפיך ומפי זרע זרעך כו', כי התורה מחזרת על אכסניא שלה להוליד כיוצא בהן עד כמה דורו' זא\"ז כו' [וראי' גדולה לזה מכללות ציור אדם"],[1900640151,"דכנס\"י שאין] התורה משתכחת מישראל גם בדור האחרון שנק' עקבו\"ת משיחא שנמצא בהם ת\"ח שנק' ראשי אלפי כו' משום דא[תפשטותא דמשה גם בדור היותר אחרון וכמ\"ש ת\"ר אלף] רגל\"י רגלי דוקא משום דנעוץ תחלתן בסופן כו' (וכמ\"ש במ\"א בענין המאמר יבא [טוב ויקבל טוב כו') וד\"ל]."],[1900640025,"<b>בעז\"ה תאדמו\"ר נ\"ע אשר דרש דרש קודם ר\"ה שנת תקע\"ה לפ\"ק בק' לובאויץ</b>\n[א] <b>להבין</b> שרש ענין עגולים ויושר, הנה מבואר בע\"ח שעצמות אוא\"ס ממש הי' ממלא כל החלל כו' [ו]אח\"כ צמצם א\"ע כביכול ונעשה בחי' מק\"פ וחלל כו' ואחר הצמצום נמשך בחי' הקו\"ח כו', והקו הזה נמשך בבחי' עגולים ויושר דהיינו שנמשך ביושר וגם מתעגל וחוזר ומתעגל כו' ויש בו י\"ס דיושר וי\"ס דעגולי' בכלל כו'. ולהבין ביאור זה הנה בדוגמא זו אנו רואים למטה והוא בשרפים ואופנים, ומענין ההפרש שביניהם יובן ג\"כ למעלה בהפרש שבין עגולים ויושר שנמשך מעצמות אוא\"ס בבחי' הקו מלמעלה למטה, אך בענין השרפים ואופנים הוא מלמטה למעלה להיות שאנו רואים שהאופנים הם בציור העגולי' הסובבי' ומשתחווי' כמ\"ש כאשר יהי' האופן בתוך האופן כו' ה\"ז ממש כמו בחי' העגולי' שבבחי' הקו כמ\"ש בע\"ח שהן [כ]גילדי הבצלים כו', אך שהאופנים משתחווי' [ב]בחי' או\"ח מלמטה למעלה ובחי' י\"ס דעגולי' שבקו הוא הנמשך מלמעלמ\"ט מעצמות אוא\"ס כו', ובשרפים נאמר שרפים עומדים בבחי' עמידה בלי הילוך וסיבוב באופנים והוא בבחי' היושר. והענין הוא כידוע דאימא מקננא בכורסיי' שהוא עולם הבריאה [והוא] בחי' חב\"ד שמאיר בשרפים דבריאה, והוא אשר מתפעל[ים] ברשפי אש התלהבות מצד השגתם, שכל התפעלות ברשפי אש הוא מסתעף מן ההתבוננות שבמוח הבינה שנמשך ללב כי בינה ליבא והוא בבחי' יסוד האש וע\"כ נק' שרפים כידוע, והוא בחי' היושר שהוא בחי' אדם בבחי' חב\"ד, וזהו שכתוב שרפים עומדים בבחי' עמידה דאדם כמ\"ש חי ה' אשר עמדתי לפניו ואברהם עודנו עומד שהוא בחי' ביטול דחב\"ד, משא\"כ האופנים שבעולם העשי'"],[1900640039,"כידוע דאופן מקננא בעשי' הרי הוא בבחי' נה\"י בלבד שהוא רק בחי' הודאה, ואמנם אעפי\"כ יש בהם בחי' הביטול דכח מ\"ה מאחר שהמה משתחווי' וכל השתחוואה הוא בבחי' הביטול דחכ' כידוע ע\"כ נק' אופני הקדש בבחי' החכ' שנק' קודש העליון כידוע, וע\"כ משתחווי' וסובבי' שהוא הגלגל שמתגלגלי' תמיד בסיבובם [מ]פני הארת כח מ\"ה דחכ' שמאיר בבחי' נה\"י דוקא, ובזה יש להם יתרון מעלה ומדריגה על השרפים הגם שהשרפים המה בבחי' חב\"ד דבריאה בבחי' היושר כנ\"ל כמשי\"ת בעז\"ה וד\"ל.\n<b>והנה</b> להבין כ\"ז יש להקדים תחלה בבחי' וענין פי' דאוא\"ס עצמו שכלול מי\"ס ובחי' מל' דא\"ס הוא בחי' האחרונה שבו הוא רק בחי' גילוי הארה בבחי' אותיו' בלבד, והכל הוא עדיין בבחי' אור העצמי רק שהוא בחי' גילוי ראשי' אור העצמי', כי פי' אוא\"ס אינו מהות[ו] העצמי רק אורו בלבד כידוע אבל גם [ב]בחי' אורו יש י\"ס כח\"ב אור רצונו וחכמתו [ית'] העצמיי' כו', ובחי' המל' הוא בחי' גילוי אותיו' בלבד שנק' שמו הגדול כמארז\"ל הי' הוא ושמו בלבד, ובלשון הזוהר גליף גליפו בחי' חקיקת אותיו' בטה\"ע בחי' עצמות אוא\"ס כו' והוא אשר נתפס עצמי' האור בבחי' שם, כמו עד\"מ שם האדם שנתפס ומלובש בו כל הארת עצמותו לקרא אותו בשמו כידוע, וזהו הודו על ארץ כו' פי' הודו בבחי' הארה דהארה כמו ונתת מהודך עליו דהיינו מזיו ואור פניו נמשך האור לזולתו שהוא רק הארה דהארה בלבד, וכך כי נשגב שמו גם מל' דא\"ס הנ\"ל והארה הנמשכת משמו נק' הודו הוד שמו הגדול, אבל עצם הזיו דאור מל' דא\"ס נאמר בו הוד והדר לפניו בעצמותו ונק' הוד מל' כמו שהמלך לעצמו משא\"כ כשמאיר הודו לזולתו כו' וד\"ל. והנה בחי' מל' דא\"ס הנ\"ל נק' סוף עולם הא\"ס כמבואר בס' עמק המלך והוא עד\"מ כמו אותיו' הדיבור שהוא סוף גילוי אור השכל והרצון והתענוג כידוע, כך בחי' אותיו' שמו הגדול הנ\"ל הוא סוף גילוי של הרצון ותענוג וחכ' שבעצמו'"],[1900640052,"אוא\"ס, לפי שכל הט\"ס הראשונים דכח\"ב כו' שבאוא\"ס עצמו כלולי' בהעלם בעצמות מלבד בחי' מל' דא\"ס שהוא ראשית הגילוי של עצמות האור דא\"ס כנ\"ל ע\"כ נק' סוף העולם דא\"ס עצמו וד\"ל. והנה מבואר בע\"ח בתחילתו בשער הכללים דבחי' מל' דא\"ס נעשה מקור לא\"ק בבחי' ג\"ר שבו ומבחי' מל' דא\"ק נעשה ג\"ר דע\"י כו' ובל' הזוהר נק' א\"ק עתיקא דעתיקי' כו' ושרשו מבחי' מל' דא\"ס ע\"ד הנז' בשער הכללי'.\n[ב] <b>וביאור</b> זה הנה ידוע עד\"מ כמו שאנו רואי' למטה באדם התחתון שהתענוג ומקור השכל הפרטי [שמחדש] ונק' תענוג שבחכ' שהוא מקור החכ' וכמ\"ש והחכ' מאין תמצא מבחי' אין של התענוג וכמשי\"ת. אך הנה הוא סוף מדריגות [בחי'] התענוג העצמי שלמעלה מהיות מקור לחכ' זאת שמחדש, וכמו אותיו' הדיבור שהוא סוף גילוי השכל כנ\"ל כך בחי' התענוג שהוא מקור לחכ' בפרט הוא סוף גילוי בחי' התענוג העצמי כו'. וזהו דמיון להבין למעלה ביאור ענין בחי' ע\"י סתם ובחי' עתיקא דעתיקא שבחי' ע\"י סתם הוא בחי' התענוג המקור לחכ' כנ\"ל ובחי' עתיקא דעתיקי' הוא מקור התענוג הנמשך למטה בחכ', ושרש של בחי' עתיקא דעתיקי' הוא בחי' מל' דא\"ס הנ\"ל שהוא מקור לג\"ר [דא\"ק] שנק' בלשון הזוהר עתיקא דעתיקי' כו' כנ\"ל. וזהו שכתוב כי עמך מקור חיים מקור כל התענוגי' העליונים כו' כמ\"ש במ\"א.\n<b>ולהבין</b> זה בתוס' ביאור הנה יש להקדים מ\"ש בע\"ח בכמה דוכתי שבחי' פנימי' אבא הוא בחי' פנימי' ע\"י לא ידעתי הטעם כו' להיות שאנו רואים למטה מבשרי אחזה כו' מבחי' התענוג שמתענג האדם ממה שחידש איזה שכל עמוק ביותר בתענוג נפלא ביותר, ולכאורה אנו רואי' ממה שיוקדם המצאת השכל חדש קודם להתפעלות התענוג ממנו שאין זה רק שמתלבש בשכל הזה שחידש מהארת אור התענוג ואין להם שייכות זע\"ז כלל, אך באמת אין זה כי התענוג הנפלא שמתענג באותו השכל הוא מקור ממציא התהוות זה השכל רק שבא בגילוי אחר התגלות אותו השכל, וזה פלא לכאורה דאם הי' התענוג הזה מקור השכל היולי הי'"],[1900640064,"צ\"ל קודם לשכל. אך הענין הזה מופת גמור לענין המאמר שא' בע\"ח דבחי' פנימי' אבא הוא בחי' פנימי' ע\"י דהיינו שפנימי' התענוג הוא מקור כל התענוגי' הנמשך ונשפל למטה כו', וכמו תענוג שבחכ' שבפרט שחידש נשפל וירד בבחי' הארה דהארה הנופל ונובל מעצם [כח] התענוג העצמי שלמעלה והוא הנק' בחי' פנימי' ע\"י, ומשם הוא ג\"כ בחי' מקור מוצא כל המושכלות החדשות להמציא שכליי' עד אין שיעור, וכידוע שזהו בחי' לחלוחי' הרוחני' [ש]במוח ששם הוא משכן התענוג העצמי (שממנה נתהווה הטפה רוחני' במוח) ומשם הוא כח ההבנה להמציא שכליי' חדשים כו', ומקור מוצא השכליי' נק' פנימי' אבא למעלה והוא בחי' פנימי' ע\"י שהוא כח התענוג העצמי כו'. והנה כאשר יורד ונמשך ונשפל איזה הארה דהארה מעצמו' כח התענוג ממילא נמשך מזה מקור מוצא כל השכלות חדשות והא בהא תלי' והי' לאחדים ממש מטעם זה, והוא הסיבה אשר אנו רואים שבהמצאת שכל חדש [יומשך ו]ימצא בו תענוג מורגש מיד לפי שמיד ביציאת שכל החדש ממקור[ו] מקור כל [ה]שכליי' יצא עמו הארת אור כח התענוג העצמי מטעם הנ\"ל שהוא סיבת התהוות[ו מ] מקורו משום דפנימי' אבא הוא פנימי' ע\"י דהיינו כח המשכיל כל שכליי' שהוא בא מבחי' כח התענוג העצמי, כך בפרט בהמצאת גילוי שכל חדש הנה הוא בא בבחי' אור תענוג פרטי היורד מכח עצם התענוג, ולפי שמקור מוצא שכל זה כבר קיבל מכח עצם התענוג ע\"כ יוקדם לבא בגילוי תחלה ואח\"כ יתגלה התענוג שלו אבל הוא מקור מוצאו בין במקורו בעצם כח המשכיל בין בגילוי למטה בפרט, אך אם הי' מקור זה השכל מקבל מבחי' אור זה התענוג הפרטי אז הי' ראוי שיוקדם התענוג לשכל, אבל אם מקור זה השכל מתאחד בעצם התענוג שלמעלה מגילוי זה התענוג ע\"כ יבא גילוי השכל ראשון לגילוי זה התענוג כו' וד\"ל.\n<b>ונמצא</b> מובן עכ\"פ שבחי' עצם התענוג שם מקור מוצא כל השכליי' מאין ליש בבחי' כח היולי לחדש עד אין שיעור ורק מעט מזעיר בחי' הארה דהארה ממנו נופל ויורד בהמצאת שכליי' חדשים בכלי מוח האדם כו'. ולמעלה יובן מכ\"ז שבחי' חכ' דא\"ק שנק' מקור החכ' שברצון ונק' כח המשכיל היולי הוא מתאחד בבחי' עצם כח התענוג העליון [ה]היולי, והוא מ\"ש דפנימי' אבא הוא פנימי' ע\"י כנ\"ל ונק' ג\"כ עתיקא דעתיקי' כנ\"ל ומשם נמשך הארה דהארה בבחי' ג\"ר דע\"י סתם והוא בחי' תענוג שבחכ' בפרט שנק' עדן כמו תענוג הנרגש בחכ' חדשה כנ\"ל, וזהו חכמתא דאדם קדמאה תאיר פניו בגילוי בבחי' חכ' דע\"י וא\"א כו' כמו רבי אבוהו שמצא תוספתא חדתא שהאירו פניו כו' ע\"י התענוג שמתגלה בחידוש"],[1900640076,"חכמה זו ממקורה כנ\"ל וד\"ל. ונמצא שבחי' ע\"י סתם הוא סוף בחי' עצמי' התענוג שבחכ' דא\"ק וזהו זכר רב טובך יביעו פי' רב טובך הוא מקור כל התענוגי' ורק זכר ממנו נמשך לאו\"א דאצי' והוא מבחי' ג\"ר דע\"י סתם שהוא כמו התענוג בפרט שבשכל פרטי כנ\"ל וד\"ל.\n[ג] <b>והנה</b> גם בחי' עצמי' התענוג הנ\"ל הרי הוא מקבל מבחי' סוף עולם הא\"ס והוא שמקבל מבחי' מל' דא\"ס בחי' סוף עולם הא\"ס כו' האותיות דשמו הגדול כו'. וה\"ז עד\"מ באדם למטה כאשר יורד מעצמותו לבא לכלל תענוג סתם ולא מדבר תענוג הפרטי שאין זה רק מבחי' גילוי אותיו' דעצמות נפשו משא\"כ כשהוא טרוד בהעלם עצמותו ממש שאינו נפנה כלל לבא לידי בחי' תענוג העצמי ג\"כ כו' וד\"ל. ובכ\"ז יובן מ\"ש בזוהר בכמה דוכתי דכל הנאצלים בשם הוי' בכלל הוא רק בחי' רזא דשמי' בלבד כו' ואפי' בבחי' קוש\"י שהוא בחי' פנימי' ע\"י ששרשו בבחי' מל' דא\"ס סוף עולם הא\"ס גם זה [אינו] רק בחי' אותיו' שמו בלבד בחי' השפלה וירידת עצמות אורו כנ\"ל ומכ\"ש מיו\"ד דחכ' ולמטה כו' וד\"ל.\n<b>והנה</b> יש להקדים עוד ענין א' בביאור מל' דא\"ס הנ\"ל שהוא רק בחי' חיצוני' התפשטו' [בלבד] כו' כמו בחי' חיצוני' התפשטות המלוכה והממשלה על זולתו הנפרד כו' שזהו בחי' מל' דאצי' למטה בבי\"ע כו'. ויובן זה ממשל הידוע מבחי' אותיו' הדיבור בהמה\"פ, דהנה ידוע ומבואר במ\"א בענין בחי' אותיות הדיבור במבטא הגשמי' כמו אותיו' דטלנ\"ת מהלשון ובומ\"ף מן השפתיים, שאין הלשון והשפתיים כמו חומר מוכן לקבל צורת האותיו' הללו דוקא גם לא כחומר כלי העין לגבי הראי' הרוחני', שא\"כ הי' התינוק והבהמה יכולי' לדבר כמו שיכולי' לראות בעין ולשמוע באוזן ולהשכיל בכלי המוח כו', אלא האותיו' הללו קבועי' בעצם הנפש בכחות הרוחניו' [ד]שכל ומדות ונק' רוח ממללא שהיא נפש המדברת כידוע רק שמתלבשים בה' מוצאות [הפה] בדרך הלבשה בלבד להיות נראי' בהגשמה קול ואות גשמי' בלשון ושפתים, אבל אין להם שייכות ויחוס עם גשם הלשון והשפתיים כלל לא כמו חומר העין כו' ומכ\"ש שאינו כמו [קול] הכינור שהקול יוצא [מהכאת העץ ב]חללי הכינור, או כאשר מכין עץ בעץ וכה\"ג,"],[1900640087,"אבל [כאן] אין קול אות ד' וטי\"ת שיוצא מן הלשון יוצא מצד עצם הלשון שהוא מוכן להוציא' אלא אות ד' וטי\"ת שבנפש הרוחנית מתלבשי' בלשון ומניעין אותו להיות נשמעין בקול אותיות גשמיים, וראי' לדבר זה מבואר במ\"א באריכות. אמנם האותיות שבמבטא הגשמי הן הנה האותיו' שבנפש רק שירדו להתלבש בלבוש גשמי דה' מוצאות כו', וע\"כ כל ענין המשל והדמיון לבחי' המשכות האור האלקי בעולמות אינו רק בבחי' אותיו' הדיבור בה' מוצאות דוקא, וכמ\"ש ואתה מחי' את כולם [מ]א' עד תי\"ו שבה' מוצאות וכמ\"ש בס\"י [ו]קבען בפה וכמ\"ש ויאמר אלקי' יהי אור כו' בדבר ה' כו' והוא בחי' אותיו' הדיבור שמהן נבראו כל העולמות, ואין זה רק בחי' חיצוני' דחיצוני' שבאותיו' עליונים הקבועים בעצם בחי' מל' דאצי' הנק' רוח ממללא וכמ\"ש ויהי האדם לנפש חי' האדה\"ע שבא בבחי' כח הדיבור, כמו עד\"מ אותיו' הרוחני' שבנפש עצמו והוא הנק' אם כל חי כאשר בא באותיו' הדיבור בה' מוצאות כמ\"ש בדבר ה' כו', אמנם הן הנה בחי' אותיו' העליונים שבמל' דאצי' עצמ[ה], וזהו ענין ד' רבתי דאחד וכמ\"ש במ\"א [באריכות] וד\"ל, ונמצא שרק בחי' גילוי אותיו' החיצוני' דמדת מל' הוא מקור כל הנבראי' להחיו' רוח שפלים בכל עולם לפ\"ע, והוא מ\"ש מלכותך מכ\"ע בחי' התפשטות חיצוני' בלבד, ועד\"ז יובן ג\"כ בבחי' אותיו' המח' עצמה שהוא בחי' לאה עלמא דאתכסי' שהוא ג\"כ ע\"ד הנ\"ל באותיו' הדיבור שהרי כח המח' עצמה קודם שתבא להיו' אותיו' המח' הוא רק כח שכלו שהיא [רק] מחשבת שכל בלבד, ו[ה]גם [ש]יש בה כל האותיו' במח' שמתהווה אח\"כ אבל המה רוחני' בערך רוחני' השכל שחושב, רק אח\"כ באים בבחי' הגשמו' אותיו' מח' והוא ע\"י בחי' ה\"ג מנצפ\"ך דאימא כמו ע\"י ה' מוצאות הפה בדיבור כו' וכמ\"ש במ\"א [באריכות וד\"ל]. והיינו מ\"ש בזוהר תרין נוק' פריש שלמה מלכא אתי מלבנון כלה כו' לאה ורחל מח' ודיבור כידוע, והן ב' אחיות שנשא יעקב שהוא בחי' המדות שבלב שמח' ודיבור"],[1900640098,"מלבישי' אותם כנראה לעין שכל מה שלבו חפץ מהרהר במח' ומדבר בדיבור כו' וכמ\"ש במ\"א ונק' לבושי' לגופא שהוא בחי' ז\"א, ועד\"ז גם בחי' המדות נק' לבושים לגבי או\"א ואו\"א מלבישי' לזרועות דא\"א עד רום המעלות שהוא בחי' מל' דא\"ס שאינו רק בחי' חיצוני' האותיו' דעצמות אוא\"ס וכמ\"ש גליף גליפו חקיקת אותיו' וב' גליפות הללו היינו ע\"ד הנ\"ל באותיו' הדיבור, כך למעלה במל' דא\"ס יש ב' מיני אותיו' וחיצוני' האותיו' נמשך ממקורן שהן אותיו' העצמי', והיינו פי' גליף גליפו כמו חקיקת אותיו' המבטא מאותיו' הרוחני' שבנפש כנ\"ל, והכל בבחי' טה\"ע בבחי' אוא\"ס כנ\"ל, וז\"ש ראו כי אני אני [הוא] כו' וכמ\"ש במ\"א, וגם בעצמות אוא\"ס כלול מיו\"ד ספירות ובחי' אותיו' דמח' ודיבור מלביש למדות ומדות לחו\"ב וחו\"ב לכתר והכל בבחי' העלם עצמות אוא\"ס כמו שהוא למטה בי\"ס הגלוי' כו'), וע\"כ נק' בשם מל' דא\"ס בחי' התפשטות החיצוני' לזולתו הנפרד כמו אותיו' הדיבור דיו\"ד מאמרות בבחי' מל' דאצי' בבי\"ע כנ\"ל וד\"ל.\n[ד] <b>והנה</b> מעתה יש להבין בביאור ענין עצמות אוא\"ס שהי' ממלא כל מקום החלל כו' ואח\"כ צמצם א\"ע ונעשה מקו\"פ וחלל ואחר הצמצום נמשך הקו כ[ו', להיות] ידוע שלשון השתלשלות [כמו] לשון שלשלת כו' אינו נופל רק בדבר שנמשך בהדרגה מלמעלה למטה מעילה לעילה מדריגה אחרי מדריגה מעליון לתחתון עד מדריגה היותר תחתון, ובזה יש חילוק מדריגות מריש כל דרגין עד סוף המל' ואין זה רק בבחי' ההתגלות אור בלבד שבחי' הגילוי [אור] שייך לומר בחי' השתלשלות במדריג' שבעליון הגילוי יותר ולמטה הימנו אין הגילוי כ\"כ, וכן מתמעט האור בהתגלות שלו במיעוט אחר מיעוט בירידתו למטה מטה כל שיורד מדריגה אחת יותר יותר יתמעט אור[ו] בגילוי עד שהוא בתכלית הצמצום [ב]סוף כל המדריגות, והוא בחי' או\"י שהולך ומתמעט במיעוט [ו]צמצום אחר צמצום כמו בראש הקו\"ח ששם גילוי אור הראשון בתכלית המעלה להיות [מקור] לג\"ר דא\"ק ומשם יורד [ונמשך] בירידות המדריגות להתמעט בגילוי זה עד שבעשי' עקבי' [דא\"ק] האור הזה בתכלית הצמצום וההסתר כידוע בפי' אשר חרפו עקבות משיחך שהן ע\"ש דנוג\"ה דעשי' שמחרפי' לאור אלקי המצומצם בהם בסוד גלות כו', וכ\"ז אינו שייך רק בבחי' הגילוי אור שהוא בחי' התפשטות אור מן העצמות שבבחי' התפשטו' הדבר עצמו שייך [ענין] צמצום ומיעוט אחר מיעוט"],[1900640109,"דהיינו להתגלות בצמצום או בהתרחבות כו', אבל [ב]בחי' עצמות הדבר שממנו נמשך האור דהיינו בחי' עצמות אוא\"ס ממש לא שייך לומר בו בחי' השתלשלות בירידת המדריגות בבחי' מיעוט אחר מיעוט עד שימצא ראש וסוף כנ\"ל אלא שוה ומשוה ראש וסוף בלי ימצא ראש וסוף מעלה ומטה כלל וכלל, וכמ\"ש בע\"ח דכל עיקר בחי' הקו הוא כדי שיהי' נמצא בחי' מעלה ומטה כו' אבל [בעצמות] אוא\"ס שוה ראשית הקו עם סופו כמ\"ש קמי' כחשיכ' כאורה מקור האצי' עם סוף העשי' שווי', לפי שבבחי' העצמיו' א\"א לומר בו בחי' השתלשלות מדריגות מעליון לתחתון כלל מאחר שהוא בחי' אור עצמי' ולא בא עדיין בבחי' התפשטו' והשפעה כלל וכלל וד\"ל.\n<b>וגם</b> בחי' גילוי אור מן העצמות אעפ\"י שאינו רק בחי' גילוי ואינו עצמותו ממש מ\"מ אחר שהוא מבחי' גילוי עצמותו כמו שהוא בעצם למעלה מבחי' התגלות והתפשטות האור לזולתו ג\"כ לא שייך בו בחי' חילוק המדריגות דמעלה ומטה כלל, ולפי\"ז גם בבחי' גילוי האור דא\"ס אעפ\"י שאינו רק בחי' אור וזיו המאיר מ\"מ מאחר שנק' בשם עצמות אוא\"ס דהיינו בחי' התגלות עצמותו כמו שהוא קודם שיבא לכלל בחי' התפשטות השפעות אור בשביל התהוות [ה]עולמות [ב]בחי' ממלא וסובב כ[ו' גם בו לא יתכן לומר בחי' מעלה ומטה וז\"ש בע\"ח דקודם שצמצם אא\"ס א\"ע כבי'] הי' האור ממלא כל מקום החלל ומעלה ומטה שווין כו', וע\"כ כדי שיהי' התגלות אור בבחי' התפשטות האור לעולמות הוצרך לצמצם א\"ע כנ\"ל והוא הנק' חלל ומק\"פ, כו', וביאור הדבר הנה יש ב' מיני התגלות, הא' התגלות עצמות כמו שהוא כנ\"ל והב' בחי' התגלות מן העצמי' כדי שיגרום להיות בחי' מעלה ומטה כמו בחי' הקו הנ\"ל שגם זה צריך שיומשך כח זה הגילוי מבחי' העצמי' ג\"כ והוא אשר צריך להתצמצם בעצמו כדי לבא לבחי' גילוי זה הרי כח ומקור הגילוי הזה הוא ג\"כ בעצמות כמ\"ש בכ\"י האריז\"ל עצמו על ענין העלם העצמות שצמצם ושיער בעצמו בכח איך שיבא בפועל כו', והוא ענין הצמצום דמק\"פ וחלל בשביל ההתגלות דקו\"ח שהוצרך לזה להיות בחי' גילוי מן העצמות ואין זה ערך לבחי' התגלות עצמותו ממש כמו שהוא שלא לבא לבחי' גילוי אור בשביל ההשפעה כלל כנ\"ל.\n[ה] <b>ולהבין</b> זה בתוס' ביאור יש להקדים לזה משל א' כמו האומן שמצייר וחושב בשכלו איך לעשות איזה כלי או בנין נאה ומהודר, שבודאי תחלה יעלה במחשבתו כללי' עשיי' הכלי או הבנין דהיינו שיתפוס במחשבתו כללי' כל"],[1900640120,"מהות הכלי והבנין כמו שצ\"ל אחר גמר עשיי' הצריך ונאה לו, וא\"כ הרי בשעה שמצייר כל מהות הכלי במחשבתו בכללי' מעשיה אז תקיף המח' שלו [לכל] הכלי מכל צד כאלו מחשב ומצייר בכלי שכבר עומדת בגמר כל המעשה, אמנם מיד יעלה במחשבתו לצייר פרטי [כל] מעשיה של הכלי איך לעשות כל פרט ופרט שבה וה\"ז צמצום והתחלקות המח' הכללי' אשר קדם שהקיפו לכל הכלי מראשו לרגלו כא' ממש בלי קדימה והתחלקות כלל ועתה מצייר במחשבתו בהתחלקות פרטי' שבה, ואז כאשר תתחלק המח' בצמצומי' הללו ודאי יעלה צמצום היותר אחרון ראשון והוא שמתבונן תחלה איך לצייר רגלי הכלי בלבד ואח\"כ עולה במחשבתו איך לעשות ידיה ואח\"כ חללה ואח\"כ ראשה ואח\"כ קירוי' וכיסוי' וכיוצא, ומיד אחר שיגמור במחשבתו כל פרטיה מרגלה לראשה מלמטה למעלה אזי תתפס כל מהות הכלי כמו שהוא בגמר[ה] במח' כללי' בכללו' עשייתה כמו שחשב עליה מקודם כנ\"ל אז היא מכוונת בכללי' ענינה כמו שחשב תחלה, ואח\"כ מכח מח' כללי' זו שאחר התחלקות מח' הפרטי' הרי מתחיל לעשות כל פרט ופרט מן הכלי, ובכל עת ועת שיתעורר לעשות איזה פרט ממנ[ה] ה\"ז כח מח' הפרטי' והרי יצא מן הכלל ב' פעמים א' בהיותו טרוד במח' שמחשב בפרט אחר מח' הכללי' ומכח המח' הכללי' יצא מחשבת הפרט והב' משעה שמתחיל לעשות בפועל ממש שיוצא כל מח' פרטי' פעם ב' מכללי' המח' שלאחר התחלקות מחשבת הפרט כנ\"ל וד\"ל. ועכ\"פ בין במח' איך לעשות ובין במח' שבעשי' ממש הרי מוכרח לסלק ולצמצם המח' הכללי' כשמתחיל לצייר במח' בפרט ואם אינו מסלק המח' הכללי' לא יוכל לצמצם ולחלק מחשבתו בפרט כו' וד\"ל.\n[ו] <b>והנמשל</b> מכ\"ז יובן למשכיל למעלה בהיות מבואר למעלה שיש ב' מיני התגלות והתגלות העצמות כמו שהוא א\"א לומר גם בחי' מקיף וסובב כלל מאחר שהוא למעלה מבחי' השפעת אור לגמרי כו' וכנ\"ל, וא\"כ מ\"ש בע\"ח בבחי' מקיף הראשון שמקיף כל הקו מראשו לרגלו כאחד כו' היינו בחי' התגלות הב' הנ\"ל שזהו מ\"ש ששיער בעצמו בכח איך שיבא בפועל והוא בחי' מח' אחת הנז' בזוהר בראשית שהוא בחי' מח' הכללי' שכוללת כל בחי' התחלקות ההשתלשלות דקו כו' מראשו לרגלו כא' ממש בלי קדימה לראש על הסוף כמשל מחשבת האומן בכללות מעשה הכלי כו' כנ\"ל, אך בחי' גילוי כללית זה נמשך מן העצמות כדי שיהי' בחי' קו\"ח שהוא בחי' מעלה ומטה כנ\"ל, ובחי' הקו הזה כמו התחלקות המח' בפרט שיוצא מן הכלל בפרט[י] מעשיי' של הכלי מרגלה לראשה כו' וכנ\"ל, וכך בחי' סוף מעשה דקו בסוף העשי' הוא פרט הראשון שעלה במח' תחלה ועולה מלמטה למעלה בדרך פרטי' עד ראשית הקו כו', אך זהו בהכרח"],[1900640131,"לאחר הסתלקות המח' הכללי' אזי יכול לצמצם המח' בפרט שהוא בחי' הקו כו', והצמצום והסתלקות המח' הכללי' הוא הנק' מק\"פ וחלל אבל מכח המח' הכללי' שקודמת מוצאת כל פרט שבמח' כנ\"ל במשל במחשבת האומן בפרט אחר כללות מחשבתו, ואמנם מבואר עוד שבשעת עשי' בפו\"מ אז חוזר ויוצא הפרט מן הכלל, וכך למעלה אחר בחי' פרט המח' בעצמי' המאציל שעלה סוף מעשה קודם כנ\"ל וחוזר להיות מחשבה כללי' והוא מח' דראשית הקו שנק' מח' הקדומה שכוללת כל פרטי [ה]המשכות שבפועל ממש בגילוי אור דקו דאצי', כמו מח' שבעשי' שיש בה כלל ופרט כנ\"ל ובה עולה ראשונה שראשית הכלי עד שיורד לחשוב בפועל בסופה והוא בחי' או\"י דקו שהולך ונמשך מלמעלה למטה כו' וד\"ל.\n<b>ואמנם</b> מובן שבין בכח בין בפועל פרט המח' מקבל מן הכלל ואחר צמצום כללי' המח' בעצמותו כו', וכך למעלה בחי' מח' הכללי' שלפני הקו בכח מקור לפרט המח' ששיער בעצמו כו', וכן בגילוי פועל המח' בכלל מקור למח' בפרט וכמ\"ש קורא הדורות מראש שצופה ומביט בסקירה ומח' אחת כל שעתיד להיות אצי' ובריאה כו' עם כל העליו' ו[ה]ירידות כו' והוא בראש ומקור דא\"ק כו' ושם שווי' ראש וסוף ב[לי] קדימה לאחד כלל וכלל כמובן מתוך משל הנ\"ל וד\"ל.\n<b>ומעתה</b> יובן שרש בחי' עגולי' ויושר דבחי' עגולי' הוא בחי' ע\"ס דמקיפי' שקדמ[ו] לבחי' ע\"ס דיושר דקו\"ח דהיינו כמו בחי' מח' הכללי' הנ\"ל שקודם לבחי' מח' הפרטי' כך בחי' העגולי' [הוא] המח' בכלל שמקפת מכל צד ואין בה בחי' התחלקות עדיין כו' כנ\"ל, ואח\"כ מצמצם ומסלק המח' הכללי' ובא לחשוב בפרט כו' שאז האור הולך ב[ה]דרגה במיעוט אחר מיעוט עד סוף הקו דיושר כו', ובתחילת הקו שם בחי' גילוי אוא\"ס יורד והולך ומתמעט ומתצמצם עד סוף העשי' ששם האור בתכלית ההסתר כנ\"ל וד\"ל. אך הנה א\"כ י\"ל דלפי\"ז בחי' [ה]עגולי' גבוהי' מהיושר שהרי הוא קודם ומקור לבחי' יושר בין בכח בין בפועל לפי המובן מכל הנ\"ל, ולמה אמר בע\"ח דבחי' העגולי' הוא בבחי' נפש ובחי' היושר הוא בבחי' הרוח וידוע דבחי' רוח גבוה מבחי' נפש והוא ראוי להיות בהיפוך שבחי' העגולי' הוא בבחי' רוח והיושר בבחי' נפש כפי הנ\"ל, אך הענין הוא כידוע הכלל בכ\"מ שכל הגבוה גבוה במדריגה יותר לא יוכל לבא ממנו בגילוי למטה רק מבחי' חיצוניות ולא מבחי' פנימיות כלל מפני עוצם רוממות מעלתו שאין המקבל יכול לקבל רק מבחי' האחרונה שבו, משא\"כ בחי' ומדריגה שלמטה ממנו יכול לבא למקבלי' גם מבחי' פנימיות, וזה שכתוב בע\"ח בכמה דוכתי שבחי' חיצוני'"],[1900640142,"שבמקיף נעשה אור ומקור לתחתון בבחי' או\"פ שבו כו', ודוגמא לדבר זה ממש מה שמצינו ביהושע שהי' מהלך נגד רוחו של כל א' [וא'] כו' והכניסם לארץ כו' משום דפני יהושע כפני לבנה ויכול כל השפעתו להתקבל בבנ\"י גם מבחי' הפנימי' שבו, אבל פני משה כפני חמה ולא יכלו בנ\"י לקבל ממנו רק מבחי' חיצוני' שבו שנתלבש ביהושע כמו אור החמה באור הלבנה, וכן בכל רב ותלמיד הרי כל פנימי' שבתלמיד יכול לבא בגילוי למקבלי' אבל מפנימי' השכל של המשפיע לא יוכלו המקבלי' לקבל, וכמו שא' לא קאי' איניש אדעתי' כו', וגם כאן מבחי' העגולי' להיותם במדריגה גבוה ביותר שהרי הם בחי' מח' הכללי' הנ\"ל א\"א שיאיר מהם כ\"א בחי' הנפש בחי' אחרונה שבהם לפי שאור חיותם רב וגבוה מאד נעלה עד שמחי' את כל ההשתלשלות דיושר בהשוואה א' מראש לרגל כו' היא הנותנת שאין ההארה רק מבחי' חיצוני' שלהם שהוא בחי' נפש, משא\"כ בחי' היושר להיות נמוך במדריגה שהרי הוא האור הבא למטה מטה בצמצום והתחלקות המדריגות במיעוט אחר מיעוט כדמיון מח' הפרטי' כו' ע\"כ גם כל בחי' פנימי' שבו יוכל לבא בגילוי, וע\"כ המשכת האור ביושר הוא בבחי' רוח וד\"ל. ואמנם מובן ממילא שבחי' נפש דעיגולי' גבוהים מבחי' הרוח דיושר כי בחי' חיצונית שבעליון למעלה מבחי' פנימיות דתחתון וע\"כ מבחי' חיצונית שבעליון נעשה בחי' מקיף לתחתון כמ\"ש בע\"ח (ועיקר הטעם הוא לפי שבחי' היושר שהוא בבחי' פרצוף אדם גימ' מ\"ה הוא בחי' רוח האדם כו' ובחי' העגולי' שהן למעלה מבחי' התחלקות עדיין כנ\"ל שהוא בבחי' נפש לבד ואדרבה מפני עוצם הרוממות מתלבש גם בבחי' האחרונה משא\"כ במי שאינו גבוה כ\"כ שאינו בא למטה במדריגה כ\"כ כמ\"ש במ\"א וד\"ל). וראי' לדבר זה מענין תורה ותפילה שהתו' נק' חיי עולם למעלה מהתפלה שנק' חיי שעה וע\"כ התורה גם שמלובשת בענינים גשמיי' והתפלה היא בלב ומוח בהשגה רוחני' מ\"מ שרש התו' גבוה יותר מפני שהוא נק' נובלות חכ' ש\"מ, וע\"כ גם חיצוני' שבה גבוה יותר מפנימי' דתפלה שנק' חיי שעה (וזהו כנ\"ל דכל הגבוה [יותר] מתלבש יותר בחיצוני' וע\"כ התו'"],[1900640152,"ירדה למטה יותר מהתפלה וכן ענני כבוד שקיבלו אבנים וחיצים כו' לפי שהיו מבחי' [ה]מקיפי' שיורדים ומתלבשי' בחיצוני' יותר מבחי' אופנים כנ\"ל וד\"ל).\n[ז] <b>ואחר</b> כל הנ\"ל יש להבין שרש ענין ההפרש בין ענין בחי' השרפים לאופנים כנ\"ל, דהנה מבואר למעלה בבחי' השרפים שנק' עומדים כו' בבחי' אור דיושר הנ\"ל והוא בחי' הילוך האור בהדרגה מעליון לתחתון בחי' חב\"ד חג\"ת נה\"י, וחב\"ד למעלה מחג\"ת כו' והכל בבחי' הגילוי רק שהולך בהדרגה דהיינו מבחי' התבוננות בהשגתם באלקו' דאור אימא מקננא בכורסי' כנ\"ל שהוא אור אלקי' המאיר בגילוי עליהם מזה נולד אצלם אוי\"ר בהתגלות בבחי' רשפי אש התלהבות גדולה, וע\"כ נק' שרפים והוא בחי' חג\"ת שנולד מחב\"ד כו', ובחי' אוי\"ר בגילוי מוליד לבחי' המעשה ו[ב]השתדלות בתמיד[ות] שנק' בחי' נה\"י והוא תמידי' עבודתם למעלה בשירות ותשבחות למשוך אחרי ה' בעסק תמידי לא יפסיקו כלל, וה\"ז עד\"מ איש החסד שנולד החסד מצד השכל ואח\"כ נולד המעשה והעסק בזה לילך ולהשתדל בטוב [ו]חסד זה בפו\"מ והוא ג\"כ בחי' חב\"ד וחג\"ת ונה\"י כנ\"ל בשרפים וד\"ל.\n<b>אמנם</b> הנה מובן במשל זה שאור זה הולך ומתמעט במיעוט אחר מיעוט שהרי עיקר ומקור הראשון הוא השכל והטעם אל האהבה, ומיד שנולדה האהבה נסתלק אור זה השכל, והטעם שהרי א\"א שיאיר כל השכל והטעם בהתפעלות האהבה רק מעט מזעיר הימנה מאיר בה בלבד, וכמו\"כ אחר התפעלות האהבה שנולד מזה החסד בפו\"מ לילך [ו]להשתדל בעסק גמור בטובת זולתו בגופו ובממונו בתמידי' הרי נסתלק בשעת העסק בחסד בפ\"מ עיקר פנימי' אור האהבה שבלב, וזה ברור שא\"א שתבער האהבה באותו [ה]דבר שחפץ בו לעולם בלי הפסק שהרי במשך זמן תתקרר בודאי עד שיבא לידי שכחה לגמרי על אותו דבר האהוב לו, אך עכ\"פ יוכל להשתדל בעסק החסד בפ\"מ מפני כח אותה האהבה שהי' לו רק שהוא עושה בקרירות אבל חיות קצת יש בה מהארת אותה האהבה במעשה זו תמיד, וא\"ל הי' בטל ממילא והי' רפיון ידים במעשה זו בתמידות, וא\"כ הרי כבר נתעלם בעסק זה מהארת האהבה ומכ\"ש הארת השכל והטעם ונק' נצח ענף החסד [בחי'] בדי ערבות שאין בהם טעם כו' רק הארה בעלמא בבחי' נצחון והסכם בלבד נשאר מאור המדה שבלב כו', ואין לה ערך לעצם התעוררות האהבה כמו שנולדה"],[1900640159,"ונמשכה מן השכל בתחילתה, וכמ\"כ אין ערך לגילוי הארת השכל והטעם שמלובש באור האהבה לגבי עצם אור השכל והטעם כמו שהוא טרם שנולד אהבה מחמתה כו' וד\"ל.\n<b>אך</b> הנה למעלה בשרפים דעולם הבריאה אין הענין כן אלא להיפוך ממש, דהיינו שבחי' ההשגה בשכל וטעם באלקות שמאיר עליהם מבחי' אימא דמקננא בכורסי' כנ\"ל, הרי הוא בבחי' התגלות בתוקף גדול ובחי' התפעלות אהוי\"ר בהתלהבות [גדולה] נכלל ובטל בהשגה [זו] כביטול מנה במאתיים לפי שמרוב תוקף התפעלות השכל נכלל ובטל בו התפעלות המדות ומכ\"ש בחי' העסק בפ\"מ כל היום בתמידי' בשיר וכה\"ג כו' שבטל ונכלל בהתפעלות המדות, כי יש בכלל מאתים מנה וכידוע שזהו בחי' מוחי' דגדלות שבחי' חב\"ד הוא העיקר ומקור הנגלה ובהם כלולי' חג\"ת ובחג\"ת כלולי' בחי' נה\"י כו', אבל האופנים שהן בבחי' נה\"י כנ\"ל הרי שם הוא להיפוך ממש והוא שהתפעלות האופנים היינו בבחי' נה\"י, ובחי' חב\"ד וחג\"ת בהעלם בבחי' נה\"י ונק' בזוהר תלת גו תלת שהוא בחי' עיבור כמו עד\"מ הוולד שראשו בין ברכיו כו'.\n[ח] <b>וביאור</b> הדברים מובן ע\"ד הנ\"ל במשל שפע החסד בפ\"מ שנמשך ונולד מן האהבה שבלב והאהבה נולדה מן השכל שיש כאן ב' העלמות א' העלם והסתלקות השכל בשעה שנולדה האהבה כנ\"ל והב' הסתלקות והעלם האהבה בשעה שנולד העסק והעשי' כנ\"ל באריכות ולא נשאר בגילוי רק מעשה החסד בפ\"מ בלבד, ובחי' חג\"ת שהוא התפעלות המדות בהעלם גדול בנה\"י ובמדות השכל והטעם בהעלם כו' וה\"ז כמו הולד שראשו בין ברכיו כו' וד\"ל. וזהו הנק' בחי' עיבור שהוא תג\"ת חב\"ד בחג\"ת וחג\"ת בנה\"י והוא בזמן הגלות כאשה עוברה כו' וכתיב בטרם תחיל ילדה (והוא כמו בחי' שינה וזה שכתוב עד יעבור כו' בימי עיבור), והנה זהו הנק' בחי' מוחי' דקטנות שהוא היפוך בחי' מוחי' דגדלות הנ\"ל בשרפים דחב\"ד עיקר וחג\"ת ונה\"י נכללי' בו כו' וד\"ל. וזהו שבזמן הגלות נאמר משכני אחריך כו' וכתי' אחרי הוי' תלכו, שבנ\"י בגלות הן בבחי' הקטנות"],[1900640166,"מאד בבחי' נה\"י דהיינו שאף בניצוץ האלקי כ\"א בחי' ההמשכה וההילוך אחרי הוי' רק בבחי' העסק והעשי' בתמידות ההשתדלות כו' שאינו רק ענף אור האהבה בעצם שאין בה רק מעט מזעיר ממנה בלבד כו', וגם מ\"ש לדבקה בו אין זה רק [בחי' ההמשכה מה שנמשך ונדבק להיות עוסק בעבודת ה' בתו\"מ ותפילה עד\"מ בין איש לרעהו שאנו רואים] כאשר יתפעל באהבה אליו יתמשך לבו אחריו כל היום [ו]לא יפרד ממנ[ו] כלל, דגם שבהמשך הזמן כבר נסתלק אור עצם האהבה מ\"מ ילך וימשך אחריו תמיד כי זהו ענף אור האהבה שמאיר תמיד בהמשכה זאת כו', וכך מ\"ש אחרי הוי' תלכו תמיד וכן לדבקה בו הגם שאינו אלא להתמשך לבו אחרי הוי' לעשות ולעסוק תמיד בעבודתו מ\"מ יש בו מהארת אור עצם האהבה ע\"כ נמשך אחרי הוי' [תמיד] בלי הפסק כלל כו', וזהו בזמן הגלות שהוא בבחי' עיבור תג\"ת בבחי' נה\"י בלבד וחב\"ד וחג\"ת כלולים בו בהעלם, אמנם הנה כתי' זכרתי לך חסד נעורייך לכתך אחרי במדבר בבחי' הקטנות דנה\"י כו' שיש בזה יתרון מעלה גם מבחי' מוחי' דגדלות כמו בבחי' חב\"ד דשרפים והוא מ\"ש באופנים לשון קד\"ש בחי' ביטול דחכ' כו' ולא נז' קד\"ש בשרפים, אבל האופנים נק' אופני הקדש כו' לפי ששרשם בבחי' ביטול דחכ' שלמעלה מבחי' ביטול דחב\"ד דשרפים אעפ\"י שאין עבודתם רק בבחי' נה\"י בלבד כנ\"ל.\n<b>והענין</b> הוא כי הנה בבחי' נה\"י הנ\"ל שהוא רק העסק וההמשכה בלבד בתמידות אחרי הוי' ועבודתו כו' יש בזה בחי' ביטול העצמי כו' עכ\"פ, שהרי עד\"מ הנ\"ל במי שנמשך אחרי אוהבו הרי הוא מניח א\"ע בבחי' ביטול עצמ[ותו] לילך אחריו להיות לו לטפל כו', אך זהו בחי' ביטול חיצוני בחיצוני' הענין כמו ההליכה אחריו וכה\"ג, אבל בחי' פנימי' הביטול הוא בלב ומוח כמו [עד\"מ] אמיתי' הביטול לפני גדול בשררה כמלך או רב גדול בחכ' עד שיתבטל במציאות ממש והי' כאבן דומם ממש בלי מח' ותנועה כו', וזהו הנק' בחי' ביטול שבחכ' עצמה כ\"ח מ\"ה האמיתי והוא ענין ההשתחוואה בארץ על פניו בשיטוח ידיו ורגליו שהוא ענין ביטול במציאות ממש, אבל בחי' ביטול חיצוני' הנ\"ל נק' בחי' ביטול שבנה\"י דחכ' כמו בחי' ההודאה שבמוח שהוא ג\"כ בחי' ביטול עצמי להודות לחבירו ולהניח א\"ע כו' כידוע, אבל הוא רק ביטול חיצוני כמו בכפיפת [הראש] לבד וכה\"ג שנק' השתחוואה חיצוני' ויכול להיות שאין בזה בחי' ביטול פנימי בלב ומוח כלל וכלל. אך מ\"מ כפיפת הראש מביאה לידי השתחווא' אמיתי' בשיטוח על הארץ על פניו כו' בחי' ביטול במציאות הנ\"ל כי נעוץ סב\"ת נה\"י בחב\"ד כו' (ובחי' ביטול דחכ'"],[1900640173,"עצמה הנ\"ל יש ג\"כ בחי' נה\"י, והוא כמו שרש נשמת משה ואהרן שהן בבחי' נו\"ה דאבא ואמר ונחנו מ\"ה בבחי' ביטול דחכ' כו', אך זהו רק הסתעפות הביטול שמשים א\"ע כאילו אינו כמ\"ש ונחנו מ\"ה אבל אין זה בחי' אין ומ\"ה הביטול האמיתי שבא ממילא מצד אוא\"ס ששורה באין דחכ' כו'), וזהו מ\"ש בזוהר דו\"ר רו\"ד שיראה תתאה בחי' ביטול חיצוני' הנ\"ל [הוא] רק [בחי'] ביטול היש[ות] מגיע לבחי' ביטול האמיתי הנ\"ל. וז\"ש הן יראת הוי' היא חכ' וכמ\"ש יהיב חכמתא לחכימין דבחי' חכ' תתאה הנ\"ל וכמ\"ש במ\"א וד\"ל.\n[ט] <b>ועפי\"ז</b> יובן יתרון מעלת האופנים על השרפים כנ\"ל, דהנה אנו רואים שהשרפים הם עומדים בלתי משתחווי' ומתגלגלי' בהילוך אבל האופנים המה הולכים בהשתחוואה תמידי' בגלגול וסיבוב בלכתן לא יופסק סיבובן כלל ולכך נק' חומר וכלי האופנים בשם גלגלי' בספרי חכמי התכונה [ונלאו] לעמוד על טעם סיבובם בתמידות בלי הפסק כלל וכלל. אך הענין כמ\"ש וצבא השמים לך משתחווי' וקאי על האופנים דוקא ועיקר הטעם הוא לפי שבחי' השרפים הוא מבחי' היושר שהוא בהדרגה חב\"ד חג\"ת כו', והאופנים הם [מ]בחי' העגולי' אך שהם בבחי' הקטנות שהוא רק בחי' נה\"י בלבד וחג\"ת וחב\"ד בהם בהעלם, אמנם יש בהם יתרון מעלה מן השרפים אעפ\"י שהם בבחי' חב\"ד מפני בחי' הביטול דחכ' עצמה שנעוץ תחב\"ס בבחי' נה\"י בביטול דחכ' כמו בכפיפת הראש בהודאה והשתחוואה חיצוני' כנ\"ל שזה הגבה למעלה מבחי' ביטול דחב\"ד דשרפים וע\"כ נק' אופני הקודש דחכ' ואין השרפים נק' בשם קודש.\n<b>וביאור</b> הדברים מובן עפ\"י הנ\"ל דהגם דאופן מקננא בעשי' רק בבחי' הודאה והשתחוואה בגלגול וסיבוב חיצוני' בלבד אבל יש בזה בהעלם מבחי' ביטול הפנימי דחכ' עצמה שנק' קודש, ע\"כ נק' אופני הקודש אעפ\"י שאין התפעלותם בבחי' רשפי אש כלל רק מתגלגלי' בתמידו' כנ\"ל, משא\"כ השרפים אעפ\"י שהתפעלותם הוא ברשפי אש מצד ההשגה דחב\"ד כו' ויש בחב\"ד שלהם בחי' ביטול כידוע אך אין לו ערך לגבי בחי' ביטול הפנימי שיש בהעלם בגלגל דאופנים החיצוני', שהרי מה שיש בחי' ביטול בשרפים אין זה רק לפ\"ע צמצום כלי השגת חב\"ד שלהם בלבד אבל בבחי' ביטול דאופנים יש בחי' ביטול האמיתי"],[1900640179,"ביטול העצמי מכל וכל כמו השתחווא' בשיטוח על הארץ שנק' ביטול במציאות כנ\"ל.\n<b>ויובן</b> זה עד\"מ מי שמשיג במעלת רבו הנפלאה [מפני] שמשיג איכותו ומהותו של שכל רבו ויורד לעומק דעתו אזי יש בו בחי' הביטול בעצמו כפי ערך צמצום השגתו בעומק דעת רבו בלבד, אך כאשר נפלאה ערך מעלת הרב על התלמיד שאין לתלמיד השגה בו כלל וכלל כי לא יוכל לעמוד כלל על דעת הרב מפני שהוא נפלא לגמרי מערכו עד שאינו יודע איך לשבחו מאחר שהוא מופלא ממנו לגמרי וכו', אז בחי' ביטולו הוא רק ביטול העצמי' שאינו רואה את עצמו לכלום לגבי ערך רבו והוא בחי' ביטול שלמעלה מן ההשגה כי אינו מתבטל מצד ההשגה שלו במעלת רבו עליו אחר שהוא מופלג הימנו לגמרי, רק זהו בחי' ביטול העצמות מכו\"כ ואינו יש ודבר כלל אלא כאילו אינו במציאות חכם כלל לגבי רבו, משא\"כ אם יש לו השגה ברבו גם הוא נחשב בעצמו לגבי' חכם רק שמתבטל לגבי מעלת רבו שגדול בחכ' הימנו הרבה וכו' הרי ביטול זה במדה ושיעור לפי ערך מעלת רבו עליו כו' וד\"ל.\n<b>וזהו</b> משל להבין ההפרש בין אופנים להשרפים, שאעפ\"י שהשרפים יש בהם בחי' ביטול אינו רק לפ\"ע השגתם באור אלקי עליהם והוא מבחי' אור אימא דמקננא בכורסיי' כנ\"ל במשל התלמיד המשיג במהות ואיכות חכמת רבו איך שגדול ממנו הרבה שעכ\"פ בחי' ביטול שלו [הוא] במדה לפ\"ע השגתו כו', אבל האופנים אעפ\"י שהן [ב]בחי' נה\"י [ב]בחי' קטנות המוחי' דהיינו רק [ב]בחי' ההודאה והשתחווא' חיצוני' בכפיפת הראש וכה\"ג, עכ\"ז יש בהם בחי' ביטול גבוה יותר והוא בחי' ביטול העצמי מכל וכל [והוא הגילגול] והסיבוב שלהם בתמידות בלי הפסק כלל שמורה עוצם תוקף הביטול במציאות, מפני שבחי' הודאה זו הוא מפני שנפלא ערך אור האלקי עליהם ביותר מכלי השגתם עד שאין להם השגה כלל רק שמשיגי' הפלאו' ערך אור האלקי שהוא נפלא לגמרי מערכם, כמשל הנ\"ל בתלמיד שנפלאה ערך רבו עליו לגמרי כו' שזהו בחי' ביטול העצמי שאינה במדה ושיעור אחר שהוא למעלה מהשגתם כו', ונמצא דבחי' ביטול העצמי דאופני' גבוהי' מביטול מצד [ה]השגה דשרפים אעפ\"י שבאופנים השגה אלקי' בהעלם ובשרפים הוא בבחי' גילוי חב\"ד כו', אדרבה היא הנותנת שיש באופנים בחי' ביטול העצמי כמובן עפ\"י משל הנ\"ל, ולכך השרפים עומדי' בבחי' ביטול שבאה במדה ושיעור לפ\"ע ההשגה, והאופנים מתגלגלי' בלי הפסק כו' והגלגל עצמו מורה על בחי' ביטול עצמי כמו ההשתחוואה בארץ כנ\"ל וד\"ל.\n[י] <b>והנה</b> עד\"מ הגלגל דגלגלי' הגשמי' שהן חומר וכלי להאופנים כידוע בפי' ויסר את אופן מרכבותיו כו', הרי אנו רואי' שבסיבוב וגלגול זה העליון"],[1900640185,"שבו יורד למטה והתחתון שבו עולה למעלה ובגלגול הב' חוזר להיות התחתון עליון והעליון תחתון וכן חוזר חלילה כמה פעמים בענין הסיבוב והגילגול, דהיינו שכמה פעמים מעליון נעשה תחתון ומתחתון עליון [עד שלא נודע באמת לקרות לזה עליון ולזה תחתון גם בעיגול הגלגל כשהוא עומד בלי גלגול כלל מאחר שעומד להתגלגל ולהיות מעליון תחתון ומתחתון עליון] בלי שיעור וגם מצד עצם בחי' עיגול דגלגל א\"א לומר בו בחי' מעלה ומטה כמו בקו דיושר כידוע והכל מטעם אחד כו', והנמשל מזה יובן ג\"כ בבחי' האופנים שהן בבחי' העגולי' שאין בהם בחי' מעלה ומטה עליון ותחתון [ע\"ד] הנ\"ל בגלגל הגשמי כו' והוא כידוע שבחי' נה\"י שהוא רק בחי' ההודאה הנ\"ל נק' תחתון ובחי' ההשגה דחב\"ד נק' עליון. והנה בשרפים שנא' בהם עמידה הרי חב\"ד למעלה מנה\"י לעולם כו', אבל האופנים שמתגלגלי' הרי לפעמי' עולה בחי' נה\"י למעלה וחב\"ד למטה דהיינו שבחי' ההודאה בהם בגילוי להודות להוי' על הפלאו' אור האלקי וכו', אבל בחי' [ה]השגה אלקי' שמחמתה באה ההודאה היא בהעלם והפלאה מהם וה\"ז כמו שבחי' חב\"ד שלהם היא בירידת המדריגה למטה, ובחי' נה\"י שבהם שהוא בגילוי גמור בהם הרי הוא למעלה ליכלל באלקות בבחי' גילוי כו' ומיד חוזר העליון להיות תחתון והוא בחי' ביטול העצמי' שיש בהעלם בבחי' חב\"ד זה שבהעלם באופנים שהוא גבוה יותר מבחי' ביטול דחב\"ד דשרפים כנ\"ל הטעם ובחי' ההודאה שלהם למטה במדריגה כו' ומיד חוזר העליון להיות תחתון מפני שבחי' נה\"י דהודאה [בגילוי] וביטול העצמי [הוא] בהעלם כו', ופי' בגילוי דהגילגול דמעליון נעשה תחתון ומתחתון עליון הכל הוא בחי' ביטול שלמעלה מן הדעת שאין שם בחי' ראש וסוף ולא נודע מי [ה]עליון כו' ונק' ביטול במציאות כו', משא\"כ ביטול שמצד ה[דעת] יש בו ראש וסוף עליון ותחתון תמיד בסדר א' ולא יעלה התחתון להיות עליון ולא ירד העליון כו', מאחר שבחי' הביטול מסתעף מן ההשגה הרי בחי' ההשגה בגילוי יותר עליון ובחי' נה\"י מסתעף ממנו ועומד למטה ולא יתגל[גל] כלל, כמו אדם שעומד על רגליו שאעפ\"י שכופף ראשו בהודאה אין ראשו למטה ורגליו למעלה אלא רגליו למטה כי הראש למעלה מהרגל וז\"ש שרפים עומדים, משא\"כ בחי' הודאה דאופנים שהוא בחי' העגולי' שהראש נעשה סוף ומן הסוף ראש עד מבלי ימצא בחי' ראש וסוף כלל כנ\"ל וד\"ל.\n[יא] <b>וזהו</b> [ו]החיות רו\"ש כמראה הבזק כו' הוא כמו הלהב שיוצא מן החרסי' כו', ויש בזה ב' אופנים הא' כמו הלהב שיוצא מן החרסי' שאותו שלהבת עצמו שיצא הוא שחוזר ונכנס וחוזר ויוצא וכך הוא תמיד, וזהו הנק' רו\"ש שאותו"],[1900640191,"שרץ הוא שחוזר ושוב כו', וכך הוא בבחי' גלגול וסיבוב באופנים דכתיב בהן כי רוח החי' באופנים כו' והחיות רו\"ש שבחי' רצוא [הוא] בחי' הסתלקות למעלה ושוב בחי' ירידה למטה והוא מה שבסיבוב אחד יורד העליון למטה שהוא בחי' שוב והתחתון עולה למעלה בבחי' רצוא ומיד חוזר העולה להיות יורד והיורד חוזר להיות עולה, נמצא דמי שהי' בבחי' רצוא בעלי' הוא שיורד אח\"כ בבחי' שוב ולהיפוך מיד שזה [ש]עכשיו יורד חוזר להיות עולה והעולה יורד עד שחוזר חלילה כך כמה פעמים, הרי כל חלק ממנו הי' בבחי' עלי' וירידה רו\"ש כמה פעמים ולא שחלק זה אינו אלא עולה וזה אינו אלא יורד והיינו בחי' ביטול במציאות שאין שם ראש וסוף כנ\"ל, [משא\"כ] בחי' רו\"ש דשרפים אינו כמו להב שיוצא שהוא עצמו חוזר ויורד כו' אלא העולה שוב אינו יורד והיורד שוב אינו עולה, רק כמו עד\"מ ב' בנ\"א זה עולה וזה יורד ופגעו זע\"ז שזה עולה עוד וזה יורד עוד ומתרחקי' ביותר כו', וה\"ז כמו כח חיות הנשימה שברוח החיים שבלב שהיא ג\"כ בבחי' רו\"ש כידוע, אך הוא לעולם בבחי' מעלה ומטה שאין העליון יורד ולא התחתון עולה כמו ברו\"ש דהאופנים בגלגל כו', שהרי הנשימה באה [ללב ע\"י הדפק שבלב שדופק ב' דפיקות הא' בבחי' העלאה שהוא עליות החיות למעלה, והב' הוא בבחי' ההמשכה וירידת האור והחיות] בלב, אמנם אין זה החיות שיצא ועלה הוא שחוזר ונכנס בדפיקה הב' אלא רוח חיות חדש הוא שנכנס להיות או\"י שבא בבחי' ירידה תמיד רק שאינו יורד רק לאחר שקדם לו ההעלאה מחיות שבא קודם לו כי רוח אייתי רוח כו', ולפי שרוח האדם הוא העולה תמיד והעלאה זאת גורמת תמיד המשכות אור וחיות חדש ואח\"כ חוזר ועולה מבחי' רוח החיים [ב]דפק האדם וממשיך עוד רוח חדש, ועד\"ז הלב דופק תמיד בבחי' רו\"ש אבל לא שאותו האור שיוצא ועולה הוא אותו האור והחיות שיורד [ולא אותו האור שיוצא ויורד הוא שעולה] אלא שזה שעולה אינו יורד וזה שיורד אינו עולה כו' וד\"ל. וכך הוא בבחי' רו\"ש דשרפים שהחיות היוצא מהם [בבחי'] העלא' ותשוקה אינו חוזר ויורד כלל ואותו האור שהוא בבחי' שוב בנפילת התשוקה למעלה אלא לחזור למטה אינו חוזר ועולה, אך מ\"מ אחר הרצוא שוב ואחר השוב רצוא וזהו בתמידות והוא כמו נשימת רוח החיים שבלב ממש, משא\"כ באופנים שאותו חלק העליון ממנו שעולה הוא עצמו שיורד וכן חוזר חלילה כנ\"ל, וכ\"ז ההפרש [הוא] בין בחי' יושר לבחי' עגולי' שבבחי' אדם דיושר החיות רו\"ש אבל אין העליון למטה ואין התחתון למעלה משא\"כ רו\"ש דעגולי' כמו באופנים העליון תחתון כו' כנ\"ל וד\"ל.\n[יב] <b>והנה</b> עיקר סיבת ההפרש בכל הנ\"ל באופני' ושרפים הוא להיות ששרש השרפים הוא מבחי' הקו הנמשך ביושר בבחי' ראשית הגילוי מן העצמות הבא בבחי' המשכות בגילוי ומבואר למעלה שיש בו בחי' מעלה ומטה דהיינו שבתחילתו מאיר אוא\"ס בו בגילוי יותר ולמטה מטה בגילוי אחר גילוי"],[1900640197,"מתמעט האור במיעוט אחר מיעוט עד סוף הקו כו', והיינו שיש בו בחי' קדימה א' על זולתו שהעליון נאצל תחלה ואח\"כ מתמעט האור ונאצל הב' כו'. וזהו שנק' הדרגה דראש וסוף כנ\"ל וא\"כ אין בו לעולם שיהי' העליון תחתון אלא העליון תמיד עומד למעלה והתחתון תמיד עומד למטה (ואעפ\"י שיש בחי' עליות העולמות כמו מבריא' עולה באצי' כו', וכן הירידה מאצי' לבריאה ומבריאה ליצי' כו' לא שאור הבריאה נעשה בבחי' אצי' ממש רק שעלה לשם בלבד וכן אור האצי' לא ירד להיות בבחי' אור דבריאה ממש רק שירד ונגלה בבריאה לבד, [ו]עד\"ז כל ענין עליות וירידות הנז' בס' המקובלי', משא\"כ בבחי' עגולי' שהעליון נעשה תחתון ממש כנ\"ל ועוד דעליות וירידות הללו היינו כמו מלאכי אלקי' עולי' ויורדי' שזה שעולה עולה ואינו יורד וזה שיורד אינו עולה שהוא כמו בחי' רו\"ש דגשמי' שבלב כך אור האצי' יורד ונגלה למטה ואור הבריאה עולה, ולא שזה האור שעלה הוא שיורד וחוזר ועולה כו'. אך בעליות העולמות בשבת הרי האור דבריאה שעלה הוא שיורד בחול ואותו האור דאצי' שירד בחול עולה בשבת וכך חוזר חלילה, ואפשר זהו בבחי' היושר ג\"כ דעליון נעשה תחתון ממש וחוזר ועולה וכן מתחתון לעליון מצד בחי' ההתכללות דעליון בתחתון ותחתון בעליון כמו המדות עולי' בשכל והשכל יורד במדות והמח' עולה ונכללת במדות כו' והמדות יורדי' ומתלבשים במחשבה וכן מח' בדיבור ודיבור במח' ושכל ברצון ורצון בשכל כידוע, ואדרבה מצד בחי' ההתכללות דבחי' התיקון דיושר יותר מתלבש ויורד העליון בתחתון ותחתון מתעלה בעליון בבחי' העגולי' שאין עיגול מגיע לעיגול הגבוה המסבבו לעולם רק בעיגול אחד הוא שנעשה העליון לתחתון בסיבוב [ו]כנ\"ל, והוא מפני שע\"ס דעגולים כלולי' כא' מבלי קדימה לא' על זולתו כלל רק כמו בחי' מח' הכללי' הנ\"ל ע\"כ אין בו ראש וסוף וגם הרי בשעה שהתחתון עולה אז ממש העליון יורד כנראה לעין בעיגול המתגלגל שחלק העולה אינו חלק היורד רק שהוא עצמו בעלות[ו הוא ש]חוזר ויורד כנ\"ל, משא\"כ [ב]בחי' היושר [ש]כאשר המדה עולה בשכל אז אין השכל יורד במדה וכן להיפוך, שכאשר השכל יורד למדה אין המדה עולה בשכל לפי שע\"ס דיושר נתהוו זמ\"ז בבחי' קדימה לא' על זולתו כו'), אבל שרש האופנים הרי הוא מבחי' העגולי' הסובבי' בהשוואה א' מבלי שיש קדימה וסדר [ב]הדרגה דעליון ותחתון, ע\"כ בחי' המקיפי' דעיגול שבקו הוא המחי' לכללות ההשתלשלות ראש וסוף כא' כנ\"ל, כי זה האור אינו בא בבחי' גילוי אחר גילוי רק בבחי' העלם על הכל בשוה כו', ולפי\"ז מובן דאעפ\"י שהאופנים הן בבחי' עשי' בלבד כו' דאופן מקנן בעשי' מ\"מ שרשם למעלה יותר גבוה מן השרפים דבריאה כמו שבחי' העגולי' דקו יותר נעלה מבחי' היושר דקו אעפ\"י שהיושר בבחי' רוח והעיגולי' בבחי' נפש בלבד מטעם כל הנ\"ל וד\"ל."],[1900640202,"<b>(אך</b> יש להבין בענין והחיות רו\"ש הנ\"ל בשרפים שהרי מבואר למעלה בבחי' רו\"ש בשרפים הוא מה שעולה אינו יורד כו', והרי נאמר והי' מדי חודש כו' יבא כ\"ב להשתחוות כו' שהוא בחי' עליי' המלאכי' דבריא' באצי' והן עצמם חוזרי' ויורדים כמ\"ש בזוהר במלאכים שנק' משריין כו', וכמו כל נבואת הנביאי' שראה את המראה דמרכבה עליונה למטה ממש רק שמעולם לא ירדה שכינה למטה מיו\"ד והמרכבה עצמה היא שנושאת את הכסא כו', אך זה אפשר לומר דהמרכבה הוא שרשה מבחי' העיגולי' דתוהו והיינו כמו האופנים וחיות הקודש דוקא אבל לא השרפים שנק' עומדי', וא\"כ איך ראה ישעי' למרכבה דשרפים למטה כמ\"ש וינועו אמות הסיפים כו' ויגע ע\"פ כו' אלא צ\"ל שגם האופנים הן לאחר בחי' התיקון, וע\"כ א' בזוהר דכליל דא בדא כו' רק ששרשם למעלה בבחי' העיגולי' כו' וע\"כ לענין עליות וירידות שוים שרפים ואופנים, וגם בענין רו\"ש שוים שעל כולן נאמר והחיות רו\"ש כו').\n[יג] <b>והנה</b> ידוע דשרש בחי' רו\"ש הוא [בחי'] מטי ולא מטי רק שבחי' רו\"ש הוא מלמטה למעלה ובחי' מטי ולא מטי הוא מלמעלה למטה ובחי' מולמ\"ט הוא שרש רו\"ש, וידוע דבחי' רו\"ש הוא בבחי' ז\"א שרשו בבחי' אדם דיושר ובחי' מולמ\"ט הוא בבחי' ע\"ס דעגולי' מלמעלה למטה כמ\"ש בע\"ח וע\"כ מטי תחלה ואח\"כ לא מטי, אבל הרצוא תחלה לשוב כמ\"ש במ\"א לפי שבחי' מולמ\"ט הוא בבחי' ראשית הגילוי מן העצמות מלמעלה למטה כו'.\n<b>ובזה</b> יובן הטעם מה שהשרפים אומרים קדוש ואח\"כ מכה\"כ שהוא בחי' רצוא תחלה כי קדוש לשון מובדל ומופלא מן ההשגה כו' ואח\"כ מכה\"כ למטה מטה בבחי' שוב והאופנים הם אומרי' ברוך בבחי' המשכה מלמעלה למטה תחלה בבחי' מטי ואח\"כ ולא מטי בהשתחוואה וביטול אך השתחוואה שדרך ירידה קודם להשתחוואה ש[ב]דרך [עלי'] והסתלקות כמו והאופנים מתנשאים כו' מטעם [הנ\"ל] ששרשם בבחי' עיגולי' דתוהו ושרש השרפים בבחי' יושר דרצוא קודם כו' אך בחי' מולמ\"ט שרש [בחי'] רו\"ש ע\"כ נק' אופני הקדש כנ\"ל, וז\"ש שהשרפים או' קדוש ולא ברוך והאופנים או' ברוך ולא קדוש כו', כי הנה ידוע שבחי' מל' דא\"ס"],[1900640206,"עצמו נק' כבוד והוא כתרגום כבודו זיו יקרי' כו', וז\"ש ולכבודי בראתיו בחי' א\"ק שנק' אדם דבריאה בכללות כנודע, וזהו הודו על ארץ ושמים (שמים מבחי' עיגולי' דתוהו וארץ מבחי' יושר דתיקון והוד זה למעלה מבחי' עיגולי' ויושר, וזהו הודו על ארץ שקדמה לשמים במח' הכללי' כנ\"ל). והנה שרש השרפים הם מבחי' היושר כנ\"ל והוא שמשיגי' בחב\"ד שלהם בגילוי גמור באוא\"ס [ד]אור אימא מקננא בכורסי' כנ\"ל, ובכל השגה יש בחי' ביטול השגה איך שנפלא ונבדל ממנו בערך ומעלה כמשל הנ\"ל בהשגת התלמיד בהפלאת רבו שזה גופו מושג אצלו כו', וע\"כ השרפים אומרי' קדוש לשון הבדלה בערך גם שאפס קצהו מושג בחב\"ד שלהם אבל באים לבחי' ביטול ההשגה לומר קדוש אך גם שהוא קדוש ומובדל אצלם מ\"מ אומרים מכה\"כ וזה היפוך לכאורה, אלא צ\"ל דעצמות אוא\"ס קדוש ומובדל אך זיו ואורו מכה\"כ דא\"כ מה זה ששואל[ים] אי' מקום כבודו דמשמע שגם בחי' מל' דא\"ס מובדל [מהשגתם], אך האמת הוא דגם בחי' כבודו מובדל רק שאומרי' שקדוש ומובדל מהם בלבד אבל נמצא למטה דוקא בבחי' חכ' שבתו' שבארץ בבחי' יושר דתיקון, כי כבוד ל\"ב נתיבות חכ' והיינו לכבודי בראתיו לאדם דתיקון בכלל ופרט כו' ואין כבוד אלא תו' ל\"ב נ\"ח דתיקון כו', והשרפים אינם משיגי' רק לאפס קצה הארה זו דתיקון ולכך בקשו תנה הודך על השמים כו' וזהו מכה\"כ דוקא.\n<b>אבל</b> האופנים מתנשאים לעומתם [ואומרים] ברוך כבוד הוי' כו' פי' ברוך הוא בחי' [ה]המשכה בגילוי מן ההעלם היפוך בחי' ההעלם וההבדל בערך דקדוש כו', והטעם הוא לפי ששרש האופנים הוא בבחי' העיגולים המקיפי' דקו כו' שלמעלה מבחי' ההשגה בגילוי ע\"כ א\"א לומר קדוש ומובדל כו' מאחר שאין להם ההשגה באיכות ההפלאה, כנ\"ל במשל התלמיד שנפלא ערך רבו עליו לגמרי ואינו אלא מודה בהודאה כו', וע\"כ האופנים מתגלגלי' בסיבוב כנ\"ל באריכות. אמנם יש יתרון מעלה באופנים מצד בחי' ביטול העצמי' מכו\"כ בחי' ביטול הפנימי' דכ\"ח מ\"ה הנק' כבוד ל\"ב נ\"ח כו', ע\"כ האופנים אומרים ברוך כבוד הוי' שיתברך ויומשך בחי' כבוד הוי' העצמי שהוא בחי' מל' דא\"ס שנא' בו לכבודי"],[1900640210,"בראתיו כנ\"ל מבחי' העלם המקיף שיבא לידי גילוי, דהיינו מבחי' מח' הכללי' הנ\"ל יצא ההעלם לידי גילוי למטה מטה כמו לעתיד דכתיב ונגלה כבוד הוי' ממש כמו שהוא במקורו העצמי אז יהי' למטה כמו למעלה ממש, שזהו בחי' העיגולים שאין בו [בחי'] מעלה ומטה כלל כ[נ\"ל, ו]זהו שהאופנים מתנשאים לעומת השרפים שהן בבחי' יושר והדרגה גילוי האור בבחי' התיקון וע\"כ אומרים מכה\"כ וכמו חי אני וימלא כבוד ה' כו' כמ\"ש במ\"א. אבל האופנים אומרים שיתברך כבוד הוי' העצמי [ש]בבחי' העיגול[י'] המקיפי' שהוא למעלה מבחי' [כבוד ה'] שבחכ' דתיקון כמו ל\"ב נ\"ח דתו' שבארץ וכה\"ג [ו]זהו שאומרים ברוך כבוד הוי' ממקומו [דוקא ממקומו ה]עצמי, וכמ\"ש הנה מקום אתי וקאי על בחי' מקום בכללות שהוא בגדר מעלה ומטה מזרח ומערב כו' שהוא בבחי' היושר דקו מראשו לסופו שכ\"ז נכלל ב[בחי'] מל' דא\"ס עצמו שהוא האותיות בבחי' העיגול הסובב הכל בהשוואה א' מראש לסוף, וכמשל הנ\"ל במח' הפרטי' שנכלל במח' הכללי' בסקירה א', וכמו עד\"מ המצייר לכל מהות הכלי כמו שהיא בכל פרטי חלקי' מבלי קדימה לחלק ראשה על רגלה וכנ\"ל דמסיבת צמצום והסתלקות מח' הכללי' נתהווה מח' הפרטי' כו', וע\"כ מבקשים שיבא לידי גילוי בחי' מח' הכללי' שבמקומו העצמי שמכוחו נמשך [בחי'] הקו בבחי' היושר והוא ענין ברוך שהוא בחי' א\"ס ממש, משא\"כ מה שמכה\"כ בבחי' התיקון אינו רק הארה בעלמא מכבוד העליון הזה שבמקומו העצמי', אך ע\"י בחי' כבוד דתו' יזכו לראות עין בעין בכבוד הוי' ממש העצמי לעתיד, וזהו שבקש משה הראיני נא את כבודך העצמי' והשיב ופני לא יראו כי תו' נובלות חש\"מ מבחי' אחוריים ומשם הוא בחי' התיקון להבדיל בין טמא כו', אך עי\"ז יוכל להיות בחי' חיבור עיגולי' ביושר להיות נראה [ה'] פא\"פ רק עכשיו הוא פנים כו', וזהו שכתוב יהללו שמו כו' כל התו' שמותיו כו' ולא בשמים [וים] היא שה[ם] בחי' עיגולי' אלא בארץ כו' במחול בחי' עיגולי' כמ\"ש אז תשמח בתולה במחול וכן יעשה מחול לצדיקי' כמ\"ש במ\"א וד\"ל."],[1900640316,"פרק א) <b>בבקר</b> אין דער פרי באלד ווי ער שטייט אויף זאל די ערשטע מחשבה ורצון זיין אין הרהור תשובה, היינו צו דערמאנען זיך כל החטאים און אלע די שלעכטע הרהורים וואס ער האט אין זיך. נאך דעם זאל ער זאגן תהלים תיכף ומיד מיט איין לב נשבר ונדכה מאד זייער צובראכן גאנץ טיף אין הארצן בתכלית און ניט געמאכטע צובראכענקייט.\nפרק ב) <b>דער</b> היפוך איז ווי מען הויבט אן אריין צו לייגן זיך די ערשטע מחשבה ורצון אין שלעכטע זאכן און בפרט אין תאות ניאוף און אנדערע שלעכטס פירט ער זיך אין עומק הרע אז ער ווערט נאך געפירט א גאנצן טאג ווארום די ערשטע מחשבה ורצון איז נאר דער עיקר. בכן זאל מען תיכף ומיד נעמען זיך צום הארצן און זאגן תהלים און בפרט דעם קאפיטל נ\"א ער איז א גרויסער תיקון פאר די עוברי עבירות חמורות דהיינו אשת איש און דאס גלייכן.\nפרק ג) <b>כל</b> לבבות דורש ה', איז טייטש השי\"ת זעט נאך אויף די נקודת הלב אויפן פינטל פון אמת אין איטלעכינס הארצן ווי זי איז מיט גאר דעם אמת און ווי די צובראכענקייט איז אין הארצן צי זי איז צום תכלית און ניט פון אויבן, אזוי ווי דער פסוק זאגט קרוב ה' לנשברי לב וגו' דהיינו ווער עס האט איין טיפע מרירות הלב און עס (ער?) איז באמת זייער צובראכן תמיד אין פינטל פון הארצן פון זיינע חטאת נעורים וכו' און וויל איין תקומה האבן ער זאל זיין נפש ניט פארלירן ח\"ו, דעם העלפט השי\"ת און גיט אים גרויס הילף תשובה צו טאן היינו ער שטארקט אים זייער אין זיין דעה און אין זיין הארץ ווי ער געלוסט אין דער מחשבה אזוי גיט ער אים א גאנצן טאג און איז א סור מרע בפועל ממש, אויך אין דער מחשבה ורצון קערט זיך אפ זיין הארץ פון אלע שלעכטס אפילו ניט צו קוקן מיט די אויגן אויף וואס מען טאר ניט און ווי דאס איז בדוק ומנוסה.\nפרק ד) <b>די</b> צייט ווען דער בעל תשובה זאל זיך צוברעכן די הארץ איז צוויי צייטן. איינס פארן שלאף היינו דוקא אז ער זאגט קריאת שמע על"],[1900640324,"המטה, און בשעת ער זאגט די ווידוים זאל ער זיך דערמאנען אלע זיינע חטאות נעורים אלעס בפרטות מיט איין חשבון ברור און זאל בא זיך איין הסכם מאכן זייער שטארק אז ווייטער להבא זאל ער דאס ניט טאן ח\"ו, ווארום דער עיקר תשובה איז נאר דוקא עזיבת החטא בפועל דאס איז מען זאל אוועק ווארפן די ערשטע מעשים רעים וחטאים אזוי ווי דער פסוק זאגט יעזוב רשע דרכו ואיש און מחשבותיו וכו', און דער וידוי בלב נשבר באמת איז איין גרויסער חיזוק מען זאל באמת תשובה טאן אויף אייביג, און נאך איין פעולה איז פון אמיתית הוידוי בלב נשבר אז מען האט מן השמים אויף אים גרויס רחמנות צו העלפן אים און מוחל וסולח זיין כל החטאים ועוונות שלו אויף עבר, אזוי ווי אין פסוק שטייט ומודה ועוזב ירוחם, דער וואס איז מודה דוקא ועוזב בפועל ממש ירוחם ווערט ער דערבארעמט היינו גרויס רחמנות אויף זיין נשמה זי זאל ניט פארפאלן ווערן אין קליפות הטמאות ח\"ו.\nפרק ה) <b>די</b> אנדערע צייט איז ווען דער בעל תשובה זאל זיך צוברעכן די הארץ, איז אין דער פרי אלע טאג ווי ער שטייט אויף פון שלאף כנזכר לעיל, און אלע מאנטאג און דאנערשטאג און ערב ראש חדש זאל דער בעל תשובה זאגן דעם וידוי פון על חטא נאך תפלת המנחה דוקא בלחש, און בשעת ער זאגט על חטא שחטאנו לפניך, זאל ער זיך דערמאנען אויף אלע חטאים און זאל אויסריידן כל לבבו אז ער האט חרטה באמת און די הארץ טוט אים זייער וויי על העבר און להבא וועט ער שוין מער ניט טאן ח\"ו, ויבכה און ער זאל וויינען מקירות הלב פון פינטל פון הארץ בדמעות מיט טרערן זאל ער אפווישן דעם פנים איז דאס איין גרויסער תקון צו דעם פגם אראפ צו נעמען וואס ער האט פוגם געווען אין צלם אלקים, אזוי ווי דוד המלך ע\"ה האט געזאגט אשחה בכל לילה מטתי בדמעתי ערסי אמסה וכו', און אזוי זאל ער טאן אלע טאג פאר דעם שלאף בק\"ש שעל המטה און אין דעם וידוי וואס ער זאגט, און בפרט אין דעם פסוק בידך אפקיד רוחי וכו'.\nפרק ו) <b>די</b> תשובה ווערט צוטיילט אויף צוויי חלקים. איין חלק איז תשובה במעשה דאס ווערט גערופן עזיבת החטא אזוי ווי אויבן געשטאנען. דער"],[1900640332,"אנדער חלק איז תשובה בלב אין הארצן דאס ווערט גערופן תשובה פנימית פון גאנץ טיפן הארץ מיט געוויין און מיט וידוי אלע טאג כנזכר לעיל. די תשובה במעשה דארף מען תמיד האלטן זיך ניט צו פארגעסן ח\"ו היינו ניט נאך צו געבן די מחשבה און ניט טראכטן קיין שום שלעכטס ח\"ו צו טאן מכל שכן ח\"ו ניט אריין צו גיין בכיון אין איין ארט וואס ער קאן דארטן אריין פאלן אין שלעכטס ח\"ו, ווארום אז אפילו ער לייגט אריין די מחשבה במזיד צו טראכטן פון עניני ניאוף אדער דאס גלייכן ווערט ער שוין גערופן בשם רשע וואס ער וויל ניט טאן תשובה און אפילו כמה פעמים איז ער זיך מתעורר באמת צו טאן תשובה אבער עס איז ניט צום אמת ווארום ער איז חוזר צו זיין טומאה במזיד ממש ח\"ו.\nפרק ז) <b>די</b> תשובה באמת איז נאר צום ערשטן אין דער מחשבה אין מוח און דער ווילן הנקרא רצון בלב אין הארצן אז דער הסכם איז שטארק מען זאל ניט טאן דאס וואס מען טאר ניט און האט באמת חרטה אויף אלע חטאים פון עבר איז דאס דער סימן הטוב, און אז מען איז זייער נזהר אין דער מחשבה און מען דערלאזט ניט אריין צו דער מחשבה נאך צוגעבן זיך קיין שום שלעכטס אזוי ממילא וועט דאס הארץ ניט וועלן קיין שום שלעכטס צו טאן ח\"ו.\nפרק ח) <b>און</b> נאך איין זאך איז די שרשים פון תשובה צו דער מחשבה און צו דער הארץ איז די אויגן, אז מען זאל ניט נאך געבן די אויגן צו זען און פשיטא ניט מסתכל זיין היינו ניט איין צוקוקן זיך בכיוון אויף שיינע נקבות מכל שכן ניט ריידן פיל מיט זיי און ניט צו פארבריינגען בכיוון מיט זיי ווארום דאס מאכט איין פייער פון חמימות התאוה אין הארצן ווערט מען נאך געצויגן נאך די שלעכטס וואס מען איז פריער אריין געפאלן. עס שטייט אז די אויגן זיינען איין סרסור הנקרא מעקלער אריין צו בריינגען אין הארצן און די הארץ איז איין סרסור צו בריינגען למעשה צו טאן איין עבירה בפועל ממש. דער כלל איז העין רואה והלב חומד די אויגן זעהען און די הארץ גלוסט, און דאס איז גאר די סיבה צו אלע בעלי תשובה וואס זיינען ניט גאנץ און פאלן אריין ווידער אין זייער טומאה רחמנא ליצלן, דאס איז בדוק ומנוסה.\nפרק ט) <b>אפילו</b> די מענטשן וואס זיינען ניט אין עבירות חמורות שאט דאס אויך זייער שטארק. דערפון קען מען קומען צו מקרה לילה און צו נאך שלעכטס ח\"ו רחמנא ליצלן און אפילו נשים שאט דאס נאך מער, ביי זיי איז דאס"],[1900640340,"כמעט ווי איין היתר גמור איין צו קוקן זיך אין איין שיינעם מאנסביל און ריידן פיל מיט זיי און דערפון קריגן זיי ביי נאכט די שלעכטע חלומות פון זווגים וואס דערפון ווערן זייערע קינדער געבארן מיט דער חולי הנקרא שלעכטי זאכן וואס בעונותינו הרבים איז ניט גאנץ די קינדער נאר איין חלק חמישית או יותר און דאס איז נאר בעון הזה.\nפרק יוד) <b>עוד</b> נאך איין זאך איז פאראנען אין די שרשים פון תשובה שלמה באמת היינו מען זאל ניט זיין אין הוללות און ליצנות הנקרא בלשון אשכנז פרייליכקייט אין הארץ מיט ליצנות, היינו דאס איז איין צולאזענקייט אין הארצן איין צולאזענע הארץ צו ריידן פיל צו טאן תאוות עולם הזה און צו פרעסן און צו זויפן פיל, נאך צוגעבן די הארץ אין פריסטקייט און פרייליכקייט וואס דאס איז גאר דער היפך פון תשובה, ווארום ווער עס איז באמת צו בראכן פון זיינע חטאת נעורים והרהורים רעים וחטאים ואפילו מן עון קרי מוציא זרע לבטלה ר\"ל, ווי קאן ער אזוי איין חוצפה האבן צו ריידן פיל דברים בטלים של הוללות נארישקייט ווען אפילו עס איז ניט ניבול פה און נאך צו געבן זיך אין עסן און טרינקען. ער דערמאנט זיך ניט זיינע מעשים רעים וחטאים וואס ער דארף האבן זייער פיל סיגופים ותעניתים כדי ער זאל פאריכטן זיין נפש, און ער נעמט נאך און איז מוסיף אויף זיך צו פארלירן דעם נפש לגמרי מיט דיזע פרישקייט והוללות ותאוות רעים וואס זיי וועלן אים ווייטער בריינגען צום ערשטן, אז זאל אים שוין גאר ניט העלפן ער זאל קיין מאל ניט האבן איין לב נשבר וועט ער זיין פון די דאזיגע חוטאים גדולים וואס זיי העלפט גאר קיין תשובה ניט און מען דער לאזט אים ניט צו טאן תשובה, היינו דער יצר הרע איז זיי מסית צו הוללות וליצנות אין פרישקייט און תאות רעים בכדי זיי זאלן פאר פאלן ווערן אן תשובה ח\"ו.\nפרק יא) <b>און</b> ווידער איז דער טעם באמת פון וואס מיר האבן געזאגט ווארום דער עיקר תשובה האמיתית איז די צובראכנקייט אין הארצן פון חטאות נעורים צום אמת איז בודאי דער סימן איז (אז?) מען קען די הארץ ניט אויף הויבן קיין מאל נאך צוגעבן זיך אין דער וועלט און אז ער קאן זיין אין הוללות וליצנות און אין אכילה ושתי' אין דאגת פרנסה צו לעבן בריוח ולא בצער איז ער בודאי ניט צו בראכן מיטן אמת נאר פון אויבן איז ער נתפעל געווארן איין וויילע און ער וועט ווידער אריין פאלן אין זיין שלעכטס בלי ספק. ועל זה האבן די חכמים געזאגט רשעים מלאים חרטות די רשעים זיינען תמיד אין חרטות, ווארום"],[1900640348,"איין וויילע טוען זיי תשובה וחרטה און נאך דעם זיינען זיי ווידער חוטאים מיט דעם וואס זיי גייען בשרירות לבם כנזכר לעיל. נמצא זיינען זיי תמיד אין חרטות און השם יתברך נעמט ניט צו איין בעל תשובה וואס ער איז פאלש און איז חוזר צו זיין שלעכטס מען פאר טרייבט אים אז ער זאל ניט קענען תשובה טאן אייביג.\nפרק יב) <b>פון</b> דעסט וועגן איז ניט איין חיוב אויף דעם בעל תשובה אז ער זאל זיך סגופים אן טאן און איין צו בויגן די קאפ און צו זיין גאר אן געשטעלט פון אויבן אז ער איז צו בראכן, דען דער עיקר איז די הארץ באמת. השי\"ת זאגט גיב מיר דיין הארץ און דיינע אויגן וועל איך וויסן אז דו ביסט מיינער, און די חכמים זאגן אפילו אז ער וועט פאסטן מאה תעניתים איז ניט אזוי גוט ווי איין צובראכנקייט אין הארצן צום אמת, אבער ניט צו ווייזן זיך בדרך איין אנשטעל פון פרושים, אדרבה איין בעל תשובה דארף זיין אין שמחה וואס ער איז אפ געקערט געווארן פון שלעכטס צו גוט און פון מות לחיים און ניט אויף צו הויבן די הארץ צו ריידן פיל דברים בטלים, גם ער זאל א גרויסער שפל זיין פאר אלע מענטשן ווארום אלע זיינען בעסער פאר אים, אפילו אז מען וועט אים זידלען שטארק זאל ער דאס אן נעמען באהבה איין כפרה אויף זיינע עונות, און זאל ניט פרעסן און זויפן נאר ווען עס איז איין צייט דהיינו פון שמחת יום טוב און מכל שכן ניט צו זיין בהוללות וליצנות כנזכר לעיל. און זאל תמיד זיצן במקום יהודים יראים און זיך ניט מתחבר זיין צו רשעים, כמו שכתוב אשרי האיש אשר לא הלך בעצת רשעים וכו'.\nפרק יג) <b>כתיב</b> וחטאתי נגדי תמיד. דעם פסוק האט געזאגט דוד המלך ע\"ה אז זיינע זינד שטייען אנטקעגן אים תמיד, דער פירוש איז ער האט קיין מאל ניט פארגעסן אויף זיינע חטאים און האט אויף זיי תמיד תשובה געטאן און האט פאר זיך געשטעלט בכל רגע צו מאכן אין הארץ איין צו בראכענקייט, אזוי דארף איטליכער בעל תשובה צו טאן ער זאל ניט מסיח דעת זיין פון זיינע חטאים תמיד אפילו אז ער איז פאר טראגן זייער אין זיינע עסקים, און אפילו אין דער צייט אז אלע יהודים זיינען בשמחה פון איין מצוה אדער יום טוב ושבת, זאל ער זיך צום הארצן נעמען אז ער איז ערגער פאר אלע מענטשן, ווארום ער איז א גרויסער חוטא, און דער הרהור תשובה מיט א גרויסע צובראכענקייט פון דעם"],[1900640356,"וואס איז מכיר מקומו השפל און איז בא זיך נבזה ונמאס אויף דעם טוט השי\"ת השגחה געבן און איז מקבל בימין מקרבת, דהיינו מיט דער רעכטער האנט, אזוי ווי מיר זאגן וימינך פשוטה לקבל שבים, די וואס טוען תשובה באמת היינו תמיד בלא היסח הדעת תמיד דוקא.\nפרק יד) <b>על</b> כן האבן די חכמים געזאגט איין מענש דארף תשובה טאן דהיינו אלע טאג, און מען מיינט ניט אויף איין צייט זאל ער נתפעל ווערן מיט גרויס בכיות און נאך דעם וועט ער גאר די הארץ אפ קערן אין זיינע עסקים און קאן ווידער חוזר זיין צו שרירות לבו הרע, אזוי ווי פיל מענטשן זיינען גענארט, אזוי ווי די רשעים וואס ווילן קיין תשובה שלימה טאן זיינען זיי מלאים חרטות, וכמו אחטא ואשוב, ווארום צו זיין איין בעל תשובה באמת דארף נאר דער עיקר זיין איין הסכם אין הארצן מאכן אז ער זאל ניט נשתנה ווערן קיין מאל ח\"ו, היינו בכל עת ובכל שעה ורגע זאל ער ניט מסיח דעת זיין מהתפעלות פון זיין אמת הארץ כי כל לבבות דורש ה' ובוחן כליות ולב מען קאן אים ניט נארן און ממילא וועט אים השם יתברך העלפן.\nפרק טו) <b>דער</b> עיקר מכוון איז פון תשובה אז מען זאל דעם נפש אלקית מתקן זיין היינו וואס ער האט פוגם געווען אין צלם אלקים. דער כלל איז אזוי ווי עס איז פאראן מות הרוחני בנשמת אלקות דהיינו געטליכע געשטארבן ווארום עס איז נפסק געווארן דער הבל וואס דער נפש איז מקבל חיות אלקי געטליכע לעבן. אזוי ווי ביי עונש כרת שטייט הכרת תכרת הנפש, אזוי פון תשובה שטייט והרוח תשוב אל אלקים די נשמה ורוח קערט זיך אום אין זייער מקור וואס לעבט, נמצא פון תשובה ווערט די נשמה אפגעלעבט אזוי ווי איין גוף גשמי ווערט פון טויט לעבעדיג, כמו שכתוב שובו שובו מדרכיכם הרעים ולמה תמותו וכו' החפץ אחפוץ במות הרשע כי אם בשובו מדרכו וחיה, על כן זאל איטליכער בעל תשובה גלויבן אז די תשובה אמיתית בריינגט אים צום לעבן און ציט אים ארויס פון מות לחיים, אזוי ווי פון מות לחיים בגשמיות, און דריבער דארף ער זיין אין שמחה"],[1900640363,"זייער און דאס איז דער סימן פון איין בעל תשובה וואס איז איין אמת אז ער איז אין שמחה באמת פון דעם וואס ער איז ארויס פון מות ורע לחיים וטוב, כמו שכתוב ראה נתתי לפניך את החיים ואת הטוב המות והרע מות ממש וכו'.\nפרק טז) <b>על</b> כן מחמת דעם טעם הנזכר לעיל שטייט איין בעל תשובה זאל געבן צדקה אלע פרייטאג און אלע ערב ראש חדש מחיה זיין זיין נפש, פאר דעם וועט מען מחי' זיין מיט חיות אלקות זיין נשמה וואס זי איז געשטארבן, ווארום אזוי ווי איין רוצח נפש קומט אים מיתה, דער פאר אזוי איז פאר קערט דער וואס איז מחי' איין נפש קומט אים אז מען זאל זיין נפש מחי' זיין דריבער שטייט צדקה תציל ממות, היינו אזוי ווי צדקה איז מחי' ומציל ממות בגשמיות אויף דעם וואס עס איז נגזר געווארן אז ער זאל שטארבן בגשמיות, אזוי איז צדקה מציל פון מות ברוחניות אז די נשמה זאל ניט שטארבן און זאל קומען צו איר שרש, בכן אלע ערב שבת קדש און אלע ערב ראש חדש זאל איטליכער בעל תשובה געבן צדקה לעניים און זאל פאסטן, ווארום די תעניתים זיינען ממעט חלבו ודמו וואס ער האט ביזן אהער אריין געלייגט אין דער תאוה מיט אש זרה וואס די קליפה האט דרינען גערוט, און דער עיקר איז די צובראכענקייט פון גוף דוקא פון תענית ווערט מיט דעם פאריכט דאס וואס ער האט מיט דער תאוה רעה פוגם געווען אין צלם אלקים ווי זיין חטא איז געווען, און מיט דער צדקה וואס ער גיט אין תענית דוקא אז דער גוף איז צו בראכן קען די צדקה מחיה זיין די נשמה אז זי ווערט ווידער לעבעדיג כנזכר לעיל.\nפרק יז) <b>עס</b> שטייט פריער אין אות ו' ואות ז' אז דער עיקר תשובה איז די צוויי צייטן. צום ערשטן אין דער מחשבה צו טראכטן, ורצון און דער ווילן פון הארצן זאל אפ געקערט זיין אין דער מחשבה מיטן שטארקן הסכם. היינו דאס זאל ניט זיין אין דער מחשבה און אין זינען והיינו מה שכתוב ולא תתורו אחרי לבבכם ואחרי עיניכם אשר אתם זונים וכו', מען זאל זיך ניט קערן צו די אויגן מען זאל זעהען די אויגן צו פארשליסן כמו שכתוב עוצם עיניו מראות ברע מען זאל איין האלטן די אויגן צו פאר שליסן ניט צו זען אויף וואס מען טאר ניט, ומכל שכן ניט איין צו קוקן זיך מיט כוונה, אפילו ניט מיט א גלוסט הארץ נאר פון ווייטן"],[1900640368,"טאר מען אויך ניט נאך געבן די אויגן, ומכל שכן מתבונן צו זיין בכיוון וואס עס ווערט גערופן המסתכל במקום וכו', און אזוי האט געזאגט איוב ומה אתבונן על בתולה פון וועסט וועגן זאל איך זיך מתבונן זיין אויף איין בתולה ווארום עס וועט דערפון קומען איין הרהור וחמדה אין הארצן. די חכמים זאגן העין רואה והלב חומד די אויגן זעט און די הארץ גלוסט, די אויגן מיטן הארץ ביידע זיינען צוויי סרסורים צו איין עבירה במעשה און אזוי זאגן די חכמים דער וואס איז אין רגילות איין צו קוקן זיך בכיוון על נשים יפות וועט ער בודאי קומען צו איין עבירה במעשה, און בפרט ווען ווייבער זיינען אליין זאל דער בעל תשובה גאר ניט שטיין מיט זיי און ניט ריידן מיט זיי אדרבה ער זאל אנטלויפן און זאל צומאכן די אויגן כדי ער זאל ניט קומען צו איין הרהור וחמדה דאס איז דער אמת לאמיתו. ואפילו בשעת עסק אין מארק אדער אין קראמען זאל ער ניט ריידן מיט נשים ניט מער וואס עס גיהער צו זיין עסק, וכן און אזוי ווייבער וואס זיצן אין די קראמען זאלן ניט פארבריינגען מיט מאנזבילן יונגע לייט ווארום דאס שאט זיי זייער צו קינדער רחמנא ליצלן כנזכר לעיל.\nפרק יח) <b>די</b> אנדערע זאך איז תשובה במעשה וואס ער זאל ניט טאן דאס וואס ער האט ביז אהער געטאן דאס איז דער רעכטער אמת פון תשובה על פי התורה וואס השי\"ת איז מוחל באמת אזוי ווי אין פסוק שטייט יעזוב רשע דרכו, דאס איז אז ער האט חוטא געווען בעון מוציא זרע לבטלה ומכל שכן נאך גרעבערע עבירות זאל ער ווייטער דאס ניט טאן און זאל דאס מקבל זיין אויף זיך אין וידוי דעל חטא, און זאל זאגן מיט גאר דעם גאנצן הארצן ועל חטאים אויף דער עבירה וואס עס קומט מלקות אדער מיתות בית דין אדער מיתה בידי שמים ווי ער ווייס אין זיך, און זאל בעטן פון השי\"ת סליחה ומחילה אויף זיינע חטאים, און אויף איטליכער עבירה וואס ער געדיינקט זאל ער אויסריידן פאר השי\"ת אין זיין וידוי אז ער וועט ווייטער דאס ניט טאן ח\"ו, דאס איז די תשובה באמת וואס השי\"ת נעמט צו און איז מוחל וסולח באמת.\nפרק יט) <b>און</b> אזוי זאגן די חכמים הבא לטהר מסייעין אותו מלמעלה, דער וואס וויל מטהר זיין די הארץ פון אלע שלעכטס מיט תשובה באמת אזוי העלפט אים השי\"ת מיט פיל העלפן, היינו פון השי\"ת ווערט געשיקט זייער פיל גוטע מחשבות וואס ער ווערט ממילא צובראכן אין זיין הארצן און ער ווערט"],[1900640373,"אומגעקערט פון שלעכטס תמיד, און פארקערט ח\"ו הבא לטמא פותחין לו שערי טומאה ווער עס וויל זיך מטמא זיין אין שלעכטע מחשבות אזוי עפנט מען אים די שערי טומאה פון אויבן היינו די שלעכטע מחשבות והרהורים אז ער זאל זיך קערן צו אלע שלעכטס, און מען גיט קיין מאל איין מחשבה טובה אז ער זאל תשובה טאן בכדי ער זאל פאר פאלן ווערן, דאס איז דער וואס האט קיין מאל קיין תשובה ניט געטאן און האט מחטיא געווען נאך פיל מענטשן.\nפרק כ) <b>אך</b> דער וואס האט געטאן במעשה תשובה באמת וברצון אבער ער האט ווידער חוטא געווען אין דער זעלביגער עבירה ח\"ו דאס ווערט גערופן איין פאלשער בעל תשובה אויף דעם זאגן די חכמים רשעים מלאים חרטות, רשעים וואס טוען ניט קיין תשובה שלימה באמת זיינען זיי אין חרטות, ער דער מאנט זיך תמיד און טוט תשובה און טוט ווידער עבירות איז דאס כטובל ושרץ בידו אזוי ווי מען איז זיך טובל אין איין מקוה און האלט איין שרץ אין האנט, אזוי טוט ער תשובה פאר השי\"ת און האט חרטה און טוט ווידער שלעכטס איז דאך די טומאה אין גאנצן בשעת זיין תשובה אזוי איין תשובה ווערט גאר ניט גערעכנט פאר איין תשובה פאר השי\"ת, אך אבער פארט איז בעסער דער וואס טוט אזוי תשובה ווי דער וואס האט קיין מאל געטאן קיין תשובה, און זיינען בשרירות לבם זיי גייען נאך זייער הארץ ממילא זיינען זיי פול מיט כל התאוות רעות וואס מען פאר טרייבט זיי פון תשובה רחמנא ליצלן, אבער די וואס האבן געטאן תשובה נאר זיי ווערן ווידער נכשל אין דער עבירה און אין די תאות און טוען ווידער תשובה דעם העלפט מען פון השי\"ת זיי זאלן טאן תשובה מיטן אמת זיי זאלן קיין מכשול האבן אייביג. והיינו מחמת השי\"ת האט אויף זיי רחמנות ווארום זיי האבן אין הארצן הרהור תשובה באמת נאר זיי קאנען ניט אריבער צו צייטן די תאוה רעה צו ברעכן די הארץ, און השי\"ת איז דורש כל לבבות ובוחן כליות, שיקט ער אויף זיי יסורים קשים ומרים זיי ווערן געפאלן אין געזונט אדער קינדער שטארבן בא זיי אדער אנדערע יסורים קשים ומרים מאד וואס עס צוברעכט זיי זייער כדי זיי זאלן תשובה טאן באמת און זיי זאלן ווייטער ניט נכשל ווערן קיין מאל און זאל מכופר ווערן אלע זיינע חטאים באמת ווארום די יסורים זיינען ממרק היינו עס סייערט זייער.\nפרק כא) <b>דאס</b> איז א גרויסער חסד פון השי\"ת צו די וואס האבן איין מאל תשובה געטאן מיטן אמת אז זיי זאלן האבן אראפ פאל אדער אין געזונט אדער"],[1900640377,"אין פרנסה און אין קינדער אז זיי זאלען צובראכן ווערן כנזכר לעיל, אבער דיזע מענטשן וואס האבן קיין מאל ניט געטאן תשובה מיטן אמת נאר פון אויבן און אז איין הרהור תשובה איז אריין אין זיי אויף איין צייט און נאכדעם באלד איז די הארץ ווידער אזוי ווי פריער, אזעלכע מענטשן איז מען גאר ניט מייסר מיט יסורים אדרבה עס גייט זיי זייער גוט אין דער וועלט בכדי אז זיי זאלן קיין תשובה ניט האבן אייביג. די סימנים זיינען אזוי ווי איטליכער ווייס ביי זיך דעם אמת, ווען ער טוט תשובה באמת לאמיתו איז ער זייער צובראכן און איז אין גרויס שפלות בא זיך און איז זייער שטארק אפגעקערט פון שלעכטס, אפילו בשעת ער איז בא זיך אין איין מלחמה צו צייטן קען ער באשטיין און ברעכט דעם יצר הרע און קערט זיך אפ פון אים זייער גרינג. אך אבער ווען ער איז אין איין סיבה וואס דערפון ווערט ער נכשל און האט באלד חרטה באמת, דהיינו אז ער זיצט כמה שנים בלא אשה אן איין ווייב, אדער אז ער האט מחבר געווען זיך מיט אנשים קלים ורקים מיט שלעכטע מענטשן וואס זיי בריינגען אים אריין אין טראקטירן זויפן ממילא קומט ער צו איין עבירה אבער איין מאל און ניט מער, און באלד טוט אים די הארץ זייער וויי און וויינט און פאסט און טוט תשובה באמת און טוט שוין מער ניט, פון אלע זיינע סיבות אדער דאס גלייכן, זעט השי\"ת דעם אמת און איז אים מוחל וסולח און העלפט אים אז ער זאל תשובה טאן באמת, און דער סימן להיפך איז דער וואס איז מיט איין מכשול בעבירה ווערט ער נאך געצויגן ווייטער ביסלעך ווייס ביז ער טוט זיך נאך צו גיין ממלא תאותו זיין און קומט צו אלע עבירות ביז ער קען שוין קיין תשובה טאן אויף אייביג. וזהו מה שאמרו חכמים דאס איז וואס די חכמים זאגן בדרך שאדם רוצה לילך אין דער וועג וואס איין מענטש וויל גיין מוליכין אותו פירט מען אים אריין וכן אמרו הבא לטמא פותחין לו.\nפרק כב) <b>הסדר</b> דער פירונג פון הבעל תשובה זאל זיין אזוי, כאור הבקר גאנץ פרי ווי ער שטייט אויף זאל ער זען צו דערמאנען זיך אויף אלע זיינע חטאים כמ\"ש דוד המלך ע\"ה וחטאתי נגדי תמיד און זאל זאגן דעם קאפיטל נ\"א מיט גאר דעם הארצן, ובפרט דעם פסוק כבסני מעוני ומחטאתי טהרני, ווען אפילו עס איז ניט פון עבירות חמורות דארף מען זאגן דעם קאפיטל דוקא, ווארום דער וואס (האט) נאר פוגם געווען בברית הקדש במזיד היינו מוציא זרע לבטלה בידים ח\"ו איז דאס אזוי הארב ווי מיט איין נקבה כמ\"ש כי השחית כל בשר את דרכו"],[1900640381,"וכו' און אפילו בנעוריו פאר בר מצוה. ואם אחר י\"ג שנה אז ער איז שוין א בר עונשים זאל ער פאסטן כסדר און זאל זאגן דעם קאפיטל הנזכר לעיל אלע טאג, און אלע מאנטיג און דאנערשטאג און אלע ערב ראש חדש אחר תפלת המנחה זאל ער זאגן על חטא און ועל חטאים שאנו חייבים וכו' זאל ער זיך דערמאנען אלע זיינע חטאים און זאל בעטן מחילה און סליחה פון השי\"ת.\nפרק כג) <b>ער</b> זאל זאגן תהלים אלע טאג פארן דאוונען דאס וואס שטייט דרינען דער ענין פון תשובה זייער ערנסט, און זאל דאוונען אין סידור מיט גרויס הכנעה ובושה בשעת אז ער שטעלט זיך פאר השי\"ת און זאל זאגן אין סידור איטליכן ווארט מיט גרויס הכנעה אין הארצן, און זייער ערנסט איין שבח והודי' צו געבן צו השי\"ת וואס ער איז מקורב געווארן צו השי\"ת און איז ניט פאר שטויסן געווארן אין שלעכטס ח\"ו, און דערפון זאל ער זיין אין שמחה בשעת ער זאגט פסוקי דזמרה פון ברוך שאמר ביז ק\"ש ושמונה עשרה, נאר פאר ברוך שאמר זאל ער זיך זייער אראפ ווארפן פאר השי\"ת מיט גרויס שפלות און מיט גרויס בושה פון זיינע חטאים, און דאס האבן די חכמים געזאגט אין עומדין להתפלל אלא מתוך כובד ראש, מען זאל זיך ניט שטעלן דאוונען נאר איין געבויגן די קאפ מחמת גרויס בושה פון חטאת נעורים וואס איטליכער מענטש ווייס בא זיך זייער גוט, און זאל זיין ניט גענארט און ניט גרינג צו מאכן זיך דאס.\nפרק כד) <b>אין</b> שמונה עשרה אין דער ברכה סלח לנו זאל דער בעל תשובה גוט דער מאנען זיך אויף אלע זיינע חטאים און זאל בעטן סליחה ומחילה אויף זיך אליין, און בפרט נאך דער ברכה פון השיבנו אז מען בעט והחזירנו בתשובה שלימה לפניך זאל ער מקבל זיין אויף זיך צו טאן תשובה שלימה, און השי\"ת איז בודאי מקבל זיין גיבעט אזוי ווי מיר זאגן הרוצה בתשובה, וכן כתוב וימינך פשוטה לקבל שבים נאר די וואס ווילן מיטן אמת דוקא. און אין דער ברכת רפאינו זאל ער מכוון זיין צו השי\"ת אז ער זאל היילן דעם חולי הנפש וואס ער האט זייער פוגם געווען מיט זיינע עבירות זאל זיין נפש ניט שטארבן ברוחניות פון איר שרש כנזכר לעיל. און אין דער ברכה ולמלשינים זאל ער מכוון זיין אויף אלע שלעכטע מקטריגים וואס ער האט אויף זיך אן געפירט אויבן, ווארום פון"],[1900640385,"איטליכע שלעכטס ווערט איין מלאך רע המקטרג וואס ער שטראפט אים בגשמיות אין פרנסה און אין געזונט מכל צרה שלא תבא כמו שכתוב תיסרך רעתך, זאל ער בעטן אז השי\"ת זאל די מקטרגים אראפנעמען פון אים און פון כל עם בני ישראל היינו זיי זאלן קיין תקומה האבן. און אין דער ברכה שומע תפלה זאל ער גאר זיין הארץ אוועק געבן צו השי\"ת אז השי\"ת זאל צוהערן זיין תפלה און זאל האבן איבער אים גרויס רחמנות, און השי\"ת הערט צו בודאי אזוי ווי מיר זאגן כי אתה שומע תפלת כל פה, און בפרט צו אזעלכע וואס זייער הארץ איז זייער צובראכן פון חטאות נעורים און טוען תשובה און תפלה הערט צו השי\"ת בודאי און העלפט אים אז ער זאל ווידער מקורב ווערן צו השי\"ת באמת, און ממילא וועט אים השי\"ת מקבל זיין ברצון השגחה צו געבן אויף זיי תמיד אין זייער אייגינס און אין אלע זאכן כמ\"ש וישוב אל ה' וירחמהו און ער וועט אים היטן פון אלע צרות, נאר די תפלה אין שמע קולינו זאל זיין מקירות הלב פון טיפן הארצן מיט גרויס מרירות והכנעה בתכלית, אזוי ווי חנה הצדיקת האט מתפלל געווען וחנה מדברת על לבה והיא מרת וכו'. און אין נפילת אפים זאל דער בעל תשובה זיך נאך מער אראפווארפן און זאל אויף זיך מקבל זיין די מיתות בית דין כמו בוידוי ק\"ש שעל מטה.\nפרק כה) <b>נאכן</b> דאוונען זאל ער לערנען וואס ער קאן אפילו א פרשה חומש און א קאפיטל פון עשרים וארבע בנביאים וכתובים, א' פרק או חצי פרק משניות אדער שלחן ערוך או\"ח, און זאל חזרן כמה פעמים. און ווער עס איז מער למדן זאל קובע עתים לתורה זיין צו לערנען בית יוסף עם שלחן ערוך ואחרונים בכל יום בבקר, ובכל שבוע לילה אחת זאל ער לערנען א גאנצע נאכט עד הבקר. און זאל פאסטן און זאל לערנען די מוסר וואס אין זהר הקדוש און ראשית חכמה בשער התשובה, און אז מען פאסט ביז נאך האלבן טאג ביז זייגער איינס ווערט דאס גערעכנט פאר איין תענית. און בשעת אכילה זאל מען ניט עסען מיט תאוה ווי איין בהמה ח\"ו און זאל זען ניט אן צו פרעסן זיך, נאר בכדי צו דערהאלטן דעם געזונט כדי ניט נאך צוגעבן דעם חוש התאוה בתאות אכילה און זאל עסן איין גרינגע זאך של חלב עם לחם מעט כדי ער זאל דעם בויך ניט ממלא זיין, ער זאל ניט קומען פון דעם חלילה ווידער לשרירות לבו הרע חס ושלום."],[1900640388,"פרק כו) <b>די</b> חכמים זאגן פון אכילה גסה אן צושטאפן דעם בויך דערפון קומט מען צו זנות לילה, ווארום פון די תאות גשמיות אכילה גסה ווערט די הארץ גרויס און גראב זייער און דער גוף ווערט זייער פארגרעבט און מגושם און מזוהם אז דעם חימום הגוף איז אזוי ווי פון א בהמה וסוס, און דאס גאר דער היפוך פון צובראכענקייט אין הארצן און שפלות, און מכל שכן די וואס זיינען זיך מרבה בתענוגים באכילה צו עסן דאס בעסט און מיט גרויס צערעמאניע און מיט גרויס נחת והרחבת הלב אן צו טאן תענוג אפילו ער עסט אביסל דאס איז נאך מער מגושם דעם גוף דערפון ווערט דער חלב מגושם און ווערט פעט און גראב כמו שכתוב שמנת עבית וכו'. ביז אז זיין הארץ ווערט פארשטאפט לגמרי. ממילא האבן זיי ניט צייט צו האבן הרהורי תשובה קיין מאל אויף זייער לעבן. בכן איין בעל תשובה באמת זאל זען צו עסן אביסל און ניט מיט חימום בכדי ער זאל ניט קומען צום חום התאוה און קיין נחת רוח ותענוג ניט אן צו טאן זיך אין דער אכילה און ניט עסן פיל געריכט(ן). ווארום איין בעל תשובה דארף זיך זייער היטן ער זאל ניט מרבה חלבו ודמו זיין פון דער אכילה. אדרבה ער דארף ממעט זיין חלבו ודמו מיט סיגופים צו פאר ריכטן דעם חום התאוה רעה פון זיינע חטאים.\nפרק כז) <b>עוד</b> נאך איין זאך איז פאראנען וואס דערפון על פי רוב איז די סיבה וואס בעלי תשובות זיינען חוזר לסורם הרע און ווערן ווידער נכשל אין זייער שלעכטס נאך מער אז פון תענוג האכילה שנקרא זולל, ומשקה הנקרא סובא ער האט גרויס תאוה צו טרינקען פיל שטארקע משקה וואס זי איז זייער מחמם און צינט און ברענט דאס הארץ און גאר דעם גוף איז דאס זייער מחמם, אזוי ווי די משקה יי\"ש אז מען טרינקט אביסל מער ווי די מאס איז, ווערט מען אנגיצונדן צו אלע תאות רעות, בקיצור יי\"ש איז שורף הלב והנשמה דאס איז זייער מחמם די בלוט און פאר פירט דעם דעת לגמרי, אפילו די מענטשן וואס זיינען ריין פון חטאים שאט דאס זיי זייער, ווארום זיי ווערן מחומם זייער און גייען אראפ פון שכל ויראת אלקים און קומען צו פיל מדות רעות צו כעס ורציחה והגבהת לב מאד וואס השי\"ת האט דאס פיינט זייער, ווי עס שטייט אין פסוק און אין פיל ספרים אז דער סובא יין איז הורג אפילו נשמות כשרים זיי קומען צו עבירות חמורות ח\"ו, בכן איין בעל תשובה זאל זען ניט צו טרינקען קיין שום משקה חזק אפילו שטארקע ביר ומכל שכן יי\"ש זאל ער ניט פאר זוכן ווארום עס ווערט איין רגילות צו טרינקען יי\"ש פארן עסן ב' או ג' פעמים, בכן זאל ער גאר ניט פארזוכן יי\"ש לגמרי אפילו קידוש והבדלה זאל ער מאכן על שכר ולא על יי\"ש בשום אופן."],[1900640391,"פרק כח) <b>איין</b> בעל תשובה זאל זיך פאר היטן ניט צו שלאפן בייטאג באלד נאכן עסן, ווארום דעם חום האכילה איז אין שלאף מרבה חום הדם קען ער קומען צו שלעכטע מחשבות דהיינו קרי ח\"ו אדער קישוי אבר כידוע, בכן זאל ער באלד נאך דער אכילה ניט שלאפן לערך איין שעה ויותר און זיך צו ברעכן די הארץ פון דעם וואס ער פילט ביי זיך גראבקייט פון דער אכילה ושתי', און זאל זען צו טאן איין עבודה וטרחא, און ער זאל זייער שטארק זיין ביי זיך ווארום עס שטייט אז מען עסט ניט מיט תאוה און מען בענטשט ערנסט באמרו הזן וכו' ופסוק ואכלת ושבעת וברכת את ה' מען בענטשט השי\"ת וואס ער איז זן ומפרנס וכו', אזוי גיט אים השי\"ת אז פון דעם כח וואס פון דער אכילה דוקא זאל ער האבן גרויס כח אין די ביסל אידישקייט צו זיין איין סור מרע במעשה ובמחשבה במצות ובמעשים טובים מיט איין לב שלם. ובפרט אז מען גיט צדקה לעניים נאכן בענטשן חאטש אביסל כדי חיות דאס איז א גרויסער תקון להנשמה אז זי זאל איין געהיט ווערן פון אלע די שלעכטס. ומכל שכן צדקה תציל ממות. צדקה איז מציל פון מות הגשמי און פון מות הרוחני, כמו שכתבנו לעיל. די צדקה דארף מען געבן אין צוויי צייטן. איין צייט איז פארן דאוונען אזוי ווי דוד המלך ע\"ה האט געזאגט אני בצדק אחזה פניך. און די אנדער צייט איז נאכן עסן אדער פארן עסן אזוי ווי עס שטייט אין זהר הקדוש, און ער זאל מהדר זיין צו זאגן אלע טאג מאה ברכות, און דאס למען השם אלע רגע צו דער מאנען זיך אז ער איז דער קנעכט פון השי\"ת, דרום ברויכט ער מהדר צו זיין צו געפינען אלע רגע איין מצוה ועבודה צו השי\"ת. דהיינו לפחות אויף צושטיין פאר איין למדן און צו זען טאמער האט ער צייט זאל ער אוועק גיין פון זיין פרנסה צו לערנען אדער זאגן פיל קאפיטליך תהלים וכיוצא בו. דער כלל איז למען השם ניט צו פארגעסן אז ער איז דער קנעכט פון השי\"ת אזוי וועט ער געהאלפן ווערן פון השם יתברך צו דינען אים."],[1900640317,"פרק כט) <b>דער</b> עסק פרנסה איז עס זאל זיין דער האנדל באמונה זייער, היינו ניט צו נארן קיינעם אפילו אויף א פרוטה און זייער ניט באגערן איין פרעמדען גראשן, ווער עס איז איין קרעמער זאל ניט כאפען איין פאלשע מאס און קיין פאלשן וואג, וכש\"כ ניט צו פארלייקענען און ניט מטעה זיין און פשיטא ניט אויף צו עסען פרעמדע געלט, זעהן צו באצאלן אלטע חובות אין דער צייט חאטש עס איז אים זייער איינג, דער וואס צאלט ניט ווערט ער אנגערופען רשע אזוי ווי אין די עבירות חמורות פון ניאוף כמ\"ש לוה רשע ולא ישלם ווי עס שטייט אין די עשה\"ד לא תרצח ולא תנאף לא תגנוב, רציחה הארגענען און גזילה גזלענען געלט איז גלייך, ווארום די געלט די ביסל וואס דעם לעבען דערהאלט נעמט מען אוועק איז אזוי ווי רציחות נפשות רבות וואס זיי היינגען אן דעם, בכן דארף מען בעסער זעהן צו דערהאלטן נפשות רבות, און פארקערט ווערט ער אן גאר זיין תשובה על ח\"נ.\nפרק ל) <b>אדרבא</b> דער בעל תשובה דארף זעהן צו טאן גרויסע גמ\"ח מיט לייטן וויפל זיין יכולת איז, והעיקר צו דער הערן דעם רחמנות און דאס איינגקייט פון עניים און אפילו פון עשירים אין זייער איינגקייט און זאל ניט האבן קיין שטארקע הארץ און ניט קיין שלעכטע אויגען ח\"ו, אדרבא נאר גרויס רחמנות האבן און ניט אנדערש, בכן דארף מען זעהן צו זיין תקון וכפרה על החטאים צו דערהאלטען נפשות רבות מיט גרויסע התאמצות און גרויסע חסדים וואס ער קען טאן, גיין און טאן און ריידען וויפל ער קען און אין זיין געלט זייער מותר זיין נאך זיין פארמעג, נאר זיין מגמתו און זיין נפש זאת כל ימיו רק ליגן אז נאר ער זאל"],[1900640325,"טאן נפשות רבות טובות וחסדים רבים, ומכש\"כ אין מו\"מ זאל ח\"ו פון זיין האנט ניט ארויס גיין קיין עולה אדרבא נאר עס זאל זיין געלט אריבער גיין וויפל ער קען טראגן ווען דאס איז זייער אנגעלייגט פאר השי\"ת, כמ\"ש בחסד ואמת יכופר עון, והשי\"ת וועט אים בודאי בעצאלן ווי זיינע מדות בכפלים כמ\"ש אזוי ווי עס שטייט כל המרחם על הבריות מרחמין עליו מן השמים.\nפרק לא) <b>ובפרט</b> אז מען טוט אכזריות מיט איין עני ואביון ומדוכא אדער מיא איז אים נוגש ביז ער גיט דעם איבעריגען קלייד, דערויף שטייט אז זיין צעקה גייט זייער ארויף כמ\"ש והי' כי יצעק אלי ושמעתי כי חנון אני, אדרבא דארף מען זעהן אז ער זאל האבן איין הילף צו זיין לעבן ניט צו לאזן אים פאלן וכש\"כ זיינע קינדער זאל מען זעהן העלפן ארויסצוגעבן, ובפרט הכנסת כלה איז זייער איין גרויסע מצוה, און ניט איין האלטן די האנט אין געבן אדרבא צו געבן מיט גרויס שמחה ונדבת לב כמ\"ש ולא ירע לבבך וכו', די צדקה וחסד גייט פאר דעם מענטשן בשעת ער איז אין עולם האמת כמ\"ש צדק לפניו וכו' והלך לפניך צדקך וכו', וואס דו טוסט בעוה\"ז גייט פאר דיר לעוה\"ב אין ג\"ע און איר זאלט מלביש ערומים זיין כמ\"ש כי תראה ערום וכו'.\nפרק לב) <b>וכש\"כ</b> זיינע אייגענע קרובים, ובפרט זיין אב ואם און זיינע ברידער און שוועסטער זאל ער זעהן אויסצוהאלטן זיי ווי זיינע יכולת איז ע\"פ חיוב ומצוה של תורה, וכש\"כ ניט איין האלטן די האנט כמ\"ש וחי אחיך עמך וכו' ומבשרך אל תתעלם וכו', ואפילו קרובים ווייטע זאל מען דערהאלטן און אויס צו געבן זייערע קינדער אדער צו העלפן זיי מיט גאר דעם כח ויכולת, און דאס אויך משגיח צו זיין אויף די קראנקע, וואס זייער לעבן היינגט אויף איין האר וואס ווערט אנגערופן בקור חולים פון עניים, און בע\"ב וואס זיינען זייער אראפגעפאלן איז נאך מער מצוה וועט ער פאר דער מצוה איין כפרת עון האבן, ובפרט אז ער טוט די חסדים בסתר וכו', וכן איז דער וואס ווארפט אריין אין צדקה פושקע פאר"],[1900640333,"שלאסענערהייט דאס וואס ווערט אנגערופן מתן בסתר וואס מען גיט אין דער פינסטערניש אין בית המדרש פארן דאוונען אדער ביי זיך אין דערהיים פארן עסן, צו האבן גרויס בטחון אין השי\"ת בשעת אז מי איז זיך עוסק אין פרנסה חאטש מי איז זייער צוטראגן און מיט גרויס יסורים און מיט גרויס דוחק ביז דער כח און געזונט ענדיגט זיך, דאס ווערט גערופן מיצוי הנפש, אזוי ווי היינטיגע צייטן איז אזוי גרויסע דלות ר\"ל, און א ווייטאק אין גרויס לחץ ודוחק פון אלץ, פון דעסטוועגן זאל מען שטארק בטחון האבן אויף השי\"ת אז ער איז א גרויסער רחמן וחסדן, ער איז משגיח זייער און צו מפרנס זיין אלע מענטשן מיט חסד און גיט אים ברכה והצלחה. און וואס מיא טוט איין עסק חאטש דאס איז זייער בדוחק און זייער קליין, דעם בטחון צום אמת הערט השי\"ת און שיקט צו איין ברכה והצלחה ניט לפי\"ע אזוי ווי עס בדוק ומנוסה.\nפרק לג) <b>פארקערט</b> די וואס מיינען אז זייער גרויסע מיהע מיט גרויסע התאמצות אין זייער שטארקע עבודה און צו היטן איינצוהאלטן די האנט פון צו געבן צדקה, און פארגעסט גאר אויף השי\"ת אז ער איז דער משגיח און מפרנס באמת, מחמת ער פאר לאזט זיך גאר ניט אויף בטחון נאר אויף זיך, זעהט מען במוחש אז פון זיין געלט ווערט גאר נישט, עס וועט כלה ווערן גאר אין פרעמדע ערטער עס גייט נאר לאיבוד אפילו זיינע קינדער קומט גארנישט אן זיי זיינען עניים, און מכש\"כ דיא וואס האבן גיגאזלט עניים אדער מיט גרויס רווחים גיליהען וואס איז מעהר פון קרן, אדער ער האט פיל מענטשן גרויסע עוולות גיטאהן במו\"מ און מכ\"ש ער האט פיל אנגעזעצט בכוונה, אויף דעם זאגט דער נביא אז זיין תפלה נעמט מען ניט אהן און השי\"ת קען ניט זעהן די הענט וואס האבן בלוט כמ\"ש ידיכם דמים מלאו אזוי ווי רציחה ממש.\nפרק לד) <b>די</b> דארפס לייט זייער עסק איז מיט ערלים תמיד, זיי זיינען זייער אפגעריסן פון אידישקייט און פון דעם ווערן זיי אריין געפאלן אין תאוות און אין גראבע עבירות עם נכריות ר\"ל, און מחמת זיי זיינען ניט צו געקלעפט מיט יהודים כשרים ובפרט אין די מקומות הרחוקים וואס יהודים זיינען"],[1900640341,"דארטן ניט פאראן אזוי ווי עס איז ידוע. בכן אין די עצה זיי זאלן זיך האלטן ערליכע מלמדים לומדים, זיי זאלן מיט זיי לערנען ספרי מוסר און אויס ריידן די הארץ, און זאלן צדקה טאן מיט עניים און עוברים ושבים תמיד, און זאלן זעהן אלע שבת אין איין מנין זיין, קאן זיין אז זיי זאלן מעהר צדקה טאן עם עניים און מעהר תשובה טאן אזוי אויך זיי זאלן ניט נעכטיקן בא ערלים.\nפרק לה) <b>נאר</b> דאס וואס איז גרויסע מלשינות געווארן בעוה\"ר איינער דעם אנדערן צו מסר'ן און וויל אפנעמען זיין ביסל פרנסה און מחי', דערפון קומט אויף זיי צרות פון די שררות און זיי זיינען פארטריבן געווארן, און אזוי איז פון שנאה און מחלוקת אין שטאט וואס איש את רעהו וויל דערשלינגען אין פרנסה, ובפרט סכומות (?) ווארפן זיי אויף דעם פרעמדן נאר זיך צו היטן ניט צו געבן אפילו פרוטה אחת, און טוען גרויסע נגישות ואכזריות לעניים ודלים ארויסנעמען טירן און פינסטער און קיסענס און פערענעס, פון דעם ווערן זיי בדלות אין פרנסה און אין בנים ר\"ל, און ווערן זייער גיקוועצט אין גרויסע הוספות פון שררה און זיי קענען ניט דערהאלטן, און גאט ב\"ה איז ניט פאראן אין הארצן ממילא גייט מען אריין אין א פאסטקע אלע די מחשבות רעות וואס דער פון ווערט מקטרגים רעים, אויבן און אונטן וואס זיי זיינען שלוחי הדין צו שלאגן אין פרנסה און אין בנים ר\"ל. וזהו ומצאוך צרות רבות ורעות ואמר ביום ההוא הלא על כי אין אלקי בקרבי מצאוני הרעות האלה, וזהו תחת אשר לא עבדת את ה' אלקיך בשמחה ובטוב לבב דוקא ועבדת את אויבך וכו' וד\"ל, השי\"ת זאל אראפנעמען פון זיי דעם רוח שטות וואלט בודאי זיין אלדי ברכות והצלחות."],[1900640349,"פרק לו) <b>דער</b> בעל תשובה דארף זיך זעהן קובע עתים לתורה זיין מיט א חבר אחד טוב ווי צו לערנען אדער צו הערן גוטע אגדות פון עין יעקב בין מנחה למעריב, ווארום נאך צו גיין אין דרך הישר דארף מען מיט גרויס חשק צו זוכן דאס אזוי ווי מען זוכט דעם לעבן, און באלד נאך מעריב צו לערנען אין ספרי מוסר וכה\"ג, און זאל ניט גיין מיט חבורות מענטשן וואס זיי זיינען פוסטע לייט און ריידן דב\"ט און הוללות וליצנות כמ\"ש אשרי האיש אזוי וואויל דעם מענטשן אשר לא הלך בעצת רשעים וואס ער איז ניט געגאנגען אין דער עצה פון די רשעים צו זיין, ובדרך חטאים לא עמד די שלעכטע וועגן וואס חטאים גייען דארטן לא עמד איז ער ניט געשטאנען, ובמושב לצים דאס זיינען די קלים וואס אין ליצנות והוללות וניבו\"פ זיי זיינען ערגער פאר די חטאים ורשעים דאס זיינען אפיקורסים זיי בריינגען צו אל דאס שלעכטס, נאר כי אם בתורת ה' חפצו וכו' מי זאל זיך מדבק זיין עם לומדי תורה און זאל לערנען תורה מיט זיי, וועלן זיי אריינפירן אים און צו קלעפן צו דרך הישר, היינו ווארום מחמת די ווערטער פון ד\"ת און מוסר גייט אריין אין מוח און אין הארץ, און איטליכער וואס רעט פון דער תורה און מוסר נעהמט אים די נשמה, אזוי ממילא ווערט מען נאך געצויגן נאך השי\"ת מיט גאר דעם הארצן און מי ווערט ריין פון אלע מחשבות רעות און די הארץ ווערט אויך ריין, דאס איז דער היפך פון דרך רשעים וחטאים ולצים, בכן איז דאס פון די גרויסע יסודות צו דעם וואס וויל צום אמת גיין אין דרך הישר בתשו\"ש, דאס איז דער עיקר תשובה אפ צו קערן פון שלעכטס און צו קערן צו השי\"ת צו גיין אין זיינע וועגן דרך הטוב והישר בתורתו ובמצותיו.\nפרק לז) <b>נאך</b> סעודת הלילה זאל מען זיך ניט לייגן באלד שלאפן, מי דארף לערנען ע\"י אדער שעה\"ת פון ראשית חכמה א חצי שעה ויותר, בכדי דער חימום המאכל אויף ניט בריינגען צו קרי ח\"ו, און זאל לייענען די לאנגע ק\"ש"],[1900640357,"שעהמ\"ט אין סידור איטליכן ווארט מיט גרויס הכנעה אין הארצן און זייער ערנסט כנ\"ל, ווארום ווי מי ווערט אנטשלאפן פירט מען די נשמה אין מקום הטומאה וואוהין ער האט זיך געצויגן אין גאנצן טאג מיט די הרהורים און מחשבות שלעכטע וואס ווערט אנגערופן לבושים צואים, און די קליפות הטמאות זיינען אים מטמא מיט שלעכטע חלומות פון ניאוף ר\"ל ביז ער צו קרי ח\"ו, בכן דארף מען לייענען די ק\"ש מיט איין הרהור תשובה, היינו ארויס צונעמען פון דעם שרש דעם רצון אין מח' וואס מען האט אריין געלייגט אין שלעכטס. וזהו דאס איז דער עיקר הכוונה פון ק\"ש אז מי זאגט יה\"ר שתשכיבני לשלום ואל יבהלוני חלומות והרהורים רעים ולא אישן המות דאס איז דער מות דקליפות וואס זיי זיינען ממית די נשמה ר\"ל.\nפרק לח) <b>בכן</b> דארף מען זעהן און זיך פארן שלאף זייער צובראכן ווערן מיט איין אמת און זאל זיך דערמאנען אויף אלע חטאים וואס מען האט פון קינדווייז, אויף איטליכער מעשה און הרהור, און זאל מיט זיך איין גוטען חשבון מאכן און ניט גרינג מאכין זיך און זאל האבן אויף אין אמת לב נשבר ונדכה, דאס הייסט איין פארדרוס עס זאל אים זייער פארדריסן אין פינטל פון הארצן ביז מי זאל וויינען אויף איין אמת בדמעות טרערן, און איטליכער טרער ווערט געציילט פאר השי\"ת און נעמט אן זייער לנחת ולרצון און איז מוחל וסולח באמת אויף עבר אפ צו מעקן כל החטאים, און מיט די טרערן זאל מען דעם פנים אפוואשן ווערט בודאי דער פנים בצלם אלקים וואס מי האט פוגם געווען ווערט ער פאריכט ווערן, אזוי ווי דוד הע\"ה האט געזאגט אשחה בכל לילה מטתי בדמעתי ערסי אמסה וכו', און ווען עס איז נישט דער לב נשבר ביז טרערן זאל מען עכ\"פ אויף איין אמת א קרעכץ טאן, די קרערכצן און די זיפצן אז עס איז מקירות הלב צו ברעכט אים די קליפות וואס איז נדבק געווארן אין דער נשמה וגוף און וועט שוין אים מטמא (?)"],[1900640364,"זיין ח\"ו, וועט דאס בודאי אן גענומען ווערן פאר השי\"ת, ובפרט אז ער זאגט די וידוי זאל ער מקבל זיין ד' מיתות ב\"ד ווי ער וויטש (?) פון זיינע עבירות, דער עיקר איז בשעת אז מען זאגט דעם פסוק בידך אפקיד רוחי, אין דיין האנט השי\"ת גיב איך אוועק מיין רוח ונשמה זאל ניט זיין צו די קליפות און דו זאלסט מיך אויסלייזן מיט גרויס רחמנות וכו' ווי מי זאגט דריי מאל דעם פסוק בידך אפקיד רוחי ווערט מען אויסגעלייזט.\nפרק לט) <b>דוד</b> הע\"ה האט געזאגט אם זכרתיך על יצועי אז איך האב זיך אויף דיר דער מאנט אויף מיין בעט פארן שלאף דהיינו בק\"ש שעהמ\"ט ובפרט בפסוק בידך אפקיד רוחי אזי גם באשמורות אהגה בך אין דער פרי ווי מי שטייט אויף גייט די מח' ורצון מיט זיין הארצן נאך דיר, ווארום ווי מי לייגט זיף אויפן בעט אזוי מיט דעם שטייט מען אויף מיט איין לב נשבר ונדכה באמת, און ווי מי דער מאנט זיך צו השי\"ת פארן שלאף אזוי שטייט מען אויף מיט א לב נשבר ונדכה באמת און מיט איין רצון צו קעהרן זיך צו השי\"ת בתפלה ווארום די קליפות הטמאות האבן אפ גיטראטן בשעת מי האט גיוויינט און גיקרעכצעט אין ק\"ש שעהמ\"ט כמ\"ש דוהע\"ה יגעתי באנחתי אשחה בכל לילה מטתי בדמעתי ערסי אמסה וכו' סורו ממני כל פועלי און כי שמע ה' קול בכיי אזי תפלתי יקח וכו' יבשו ויבהלו מאד כל אויבי וכו' דעריבער דארף איין ת\"ח זאגן דעם פסוק בידך אפקיד רוחי בכדי לעורר זיין על נפשו ער זאל ניט אריין אין היכלות הקלי' פון די הרהורים רעים וואס קיינער איז ניט ניצול געווארן פון זיי פאר בייגייענדיק ניט מיט איין כוונה לכתחלה, דארף מען דעריבער אויף שטייענדיג זאגן שלא עשני גוי ועבד וכו'."],[1900640369,"פרק מ) <b>דהיינו</b> עס איז ניט צו גיקלעפט אין דער נשמה פון די קלי' הטמאות וכו' ביז מי קאן זאגן נשמה שנתת בי טהורה היא, זי איז ריין פון קליפות הטמאות ווארום מי האט געזאגט בידך אפקיד רוחי וכו' ע\"כ זאגט מען ברוך אתה ה' המחזיר נשמות לפגרים מתים וכו', דען דער גוף איז איין פגר מובס אהן דער נשמה והשי\"ת איז מחזיר די נשמות אפ גערייניגט פון די לבושים הצואים וכו', בכן דארף מען אין שמחה זיין אזוי ווי מען גייט ארויס פון א תפיסה און פון אפילה לאור דעריבער זאגט מען פוקח עורים ומתיר אסורים וכו' גלייך ווי מי איז ניי געבארן אלע טאג, כמ\"ש חדשים לבקרים רבה אמונתך, אלע אין דער פרי שיינט אריין א כח ואור חדש פון דער נשמה אין גוף שנק' אמונתיך מיט דעם גרויסן כח קען מען דאוונען מיט איין אמת הארץ, און צו זיין איין גאנצן טאג אין סו\"מ באמת, בכן דארף דער דאוונען זיין מיט א חדוה מצד אלקות וואס מי איז צוגיקלעפט מחמת דער נשמה הטהורה כו' און אין מרירות און אין בכי' דארף מען זיין מחמת דעם גוף וואס ער איז זייער מגשם פון אלע תאוות רעות זאל מען דערפון גרויס בושה ושפלות האבן און פון דעסטוועגן זאל מען זאגן דעם ווארט בשמחה ובטוב לבב אז השי\"ת איז אריין אין הארצן באמת קאן קיין שלעכטס ניט אריין קיין מאל."],[1900640318,"<b>פוקח עורים\nנעתק מלשון אשכנז ע\"י הרה\"ח מוהר\"ר שמואל דובער ז\"ל מבאריסוב</b>\n<b></b>העתקת חלק הראשון ללה\"ק וביאור עליו מאת הרשד\"ם נ\"ע\nפרק א) <b>בבוקר</b> בבוקר בקומו משנתו תיכף קודם נטילת ידים יעורר מחשבתו הראשונה לעשות התעוררות רצון בדרך כלל על כל החטאים שלו ועל כל המחשבות זרות והרהורים רעים שיש בו, ואחר כך אחר נטילת ידים ואחר ברכת השחר וברכת התורה תיכף ומיד יאמר תהלים בלב נשבר ונדכה, מאד ומאד, מעומק נקודת הלב בתכלית, ושלא יהי' מוטעה בנפשו בכח הדמיוני ח\"ו, או בדרך צביעות הנקראת (בלשון אשכנז) א גימאכטע צוברא[כינקייט.\n<span data-k=\"ks\"><b>קיצור.</b> המחשבה הראשונה היא יסוד הנהגת היום לטוב ולרע והמחשבה הראשונה התעוררות תשובה כללית.</span>\nפרק ב) וההיפוך באת זה לעומת זה הוא, כשנופל במחשבתו הראשונה"],[1900640326,"בענינים זרים ורעים ח\"ו, שבזה ועל ידי זה ממילא יתקע מחשבתו ורצונו לקשר את נפשו בזה בכלל, וגם בתאות נאוף וכיוצא בו בפרט, אזי ממשיך עליו ועל נפשו שרש ומקור עומק הרע, שיהי' לבבו נמשך רק רע כל היום ח\"ו, הבנין של כל היום מיוסד הוא רק על העמוד היסודי שמיסד בנפשו במחשבתו הראשונה בכלל שהיא העיקרית, על כן העצה היעוצה לנפילת מחשבתו הראשונה בכלל ח\"ו שיתמרמר בלבבו תיכף ומיד על זה מאד ויאמר ספר תהלים בכלל, ובפרט קפיטל נ\"א, שהוא תקון גדול אפילו לעוברי עבירות חמורות ח\"ו, כמו אשת איש וכיוצא בזה.\n<span data-k=\"ks\"><b>קיצור.</b> במחשבה ראשונה הרעה ממשיך על נפשו עומק רע והעצה לאמר תהלים בלב נשבר.</span>\nפרק ג) <b>כל</b> לבבות דורש הוי' פירוש השי\"ת הוא היודע והוא הבוחן ובודק גנזי נסתרות, דהיינו שהוא ית' דורש ומבקש נקודת האמת שבתוך נקודת הלב של כל אחד ואחד, ושיהי' לבבו נשבר לחלקים קטנים באמת לאמיתו, ולא בדרך העברה בעלמא מן השפה ולחוץ, וכמו שכתוב קרוב הוי' לנשברי לב, פירוש כל מי שיתמרמר לבבו בעומק אחר עומק, ונעשה לב נשבר ונדכה בתכלית,"],[1900640334,"ובאמת לאמיתו. לשוב לפניו ית' על חטאות נעורים שלו בכדי שתהי' לו איזו תקומה שלא יאבד את נפשו שתהי' נכרתת משרשה ח\"ו, אזי הקב\"ה עוזרו ומסיעו בתוספת כח מלמעלה שיוכל לשוב לפניו ית', והיינו שממשיך עליו ועל נפשו כח ועוז שיאיר אור האלקי במוח הדעת שלו, ומשם יומשך ויאיר גם במדות שבלב, הכלל הוא למקום שמחשבתו הראשונה האמיתית הולכת ונמשכת, שם שם לו חק ומשפט על כל היום כולו, בכללות כל הכחות כולם כאחד לשוב לפניו ית', וממילא נעשה סור מרע בפועל ממש ונעשה הסכם חזק בלבו שלא להמשך עוד במחשבה ורצון לכל מיני רע ח\"ו, ואפילו שלא להביט בעיניו כלל וכלל על הענינים האסורים, וכל זה הוא בדוק ומנוסה.\n<span data-k=\"ks\"><b>קיצור.</b> המרירות העמוקה מנקודת האמת שבלב בתשובה עושה לב נשבר באמת ואז הקב\"ה עוזרו בכל כחות נפשו ונעשה סור מרע בפו\"מ.</span>\nפרק ד) <b>מחויב</b> לקבוע לו שעת הכושר יום יום בשתי עתים מיוחדות שיוכל לעשות לו לב נשבר ונדכה הנ\"ל, הא' היא בלילה קודם השינה דוקא שצריך להאריך בקריאת שמע שעל המטה לפי נוסח האר\"י ז\"ל ובשעה שיאמר הודוי הגדול בפה יעשה חשבון ברור בנפשו היטב לזכור את עצמו על כל החטאות נעורים שלו בפרטי פרטיות ויעשה הסכם חזק בלבו שעל להבא לא יחזור עוד לסורו ח\"ו, כי שרש ועיקר התשובה הוא דוקא עזיבת החטא בפועל ממש, כמו שכתוב יעזוב רשע דרכו ואיש און מחשבותיו כו', וכשעושה כך וכך אזי ממשיך עליו ועל נפשו תוספת כח בשני אופנים, הא' הוא שעל ידי הודוי בלב נשבר באמת כנ\"ל, הרי על ידי זה גופא נמשך ונעשה מאליו וממילא חזוק גדול"],[1900640342,"בנפשו בשפת אמת תכון גם על להבא שיוכל לעשות תשובה באמת עד עולם. והב' היא שעל ידי נקודת אור האמת שמאיר בנפשו בענין הודוי ולב נשבר הנ\"ל אזי מעורר למעלה מעלה בשרש ומקור הרחמים רבים שירחמו עליו ומסיעים לו שישוב לפניו ית' תשובה שלמה מבחינת עומק עומק, עד שנמחל ונסלח לו לגמרי כל החטאים ועונות שלו, וכמו שכתוב מודה ועוזב ירוחם, פירוש שנמשך עליו ועל נפשו הארת בחי' רחמים רבים להאיר גם כן בנשמתו המלובשת בגופו שלא תהי' מן האובדים והנדחים בשלש קליפות הטמאות לגמרי ח\"ו.\n<span data-k=\"ks\"><b>קיצור.</b> ב' זמני תשובה בכל יום, בבקר ובלילה קודם השינה, שע\"י הוידוי נעשה חיזוק התשובה וע\"י לב נשבר מעורר רחמים למעלה לסלוח לו.</span>\nפרק ה) <b>ועוד</b> שעת הכושר יש לו לבעל תשובה לקבוע לו על בחי' לב נשבר הנ\"ל בבוקר בקומו משנתו תיכף כנ\"ל (פ' א'), וגם בכל יום שני ויום חמישי בכל שבוע, ומידי ערב ראש חדש בחדשו, ועוד זאת שמידי ערב ראש חדש לעת תפלת המנחה יאמר אחר התפלה הודוי דעל חטא בלחש, ובשעה שמוציא בפיו ובשפתיו על חטא שחטאנו לפניך, יזכור את עצמו על כל החטאים שלו בפרט, וישפוך את כל לבבו להוציא בשפתיו, ויפרט בפה מלא את כל החטאים הנ\"ל להתחרט באמת בדאבון לב על העבר, ובהסכם חזק בלבו גם על להבא שלא יחזור עוד לסורו ח\"ו, ויבכה בדמעות מקירות הלב, עד שירחץ את פניו ממש עם הדמעות, וכמו שאמר דוד אשחה בכל לילה מטתי בדמעתי כו', וכן יעשה לדורות מדי יום ביומו קודם השינה בקריאת שמע שעל המטה בשעת אמירת הודוי בכלל, ובפרט בפסוק בידך אפקיד רוחי, שגם תלמיד חכם צריך לאומרו מחמת שהוא נקרא חד פסוקא דרחמי, וכל זה הוא תקון גדול לכל הפגמים שפגם בנפשו ונשמתו הנקרא צלם אלקים.\n<span data-k=\"ks\"><b>קיצור.</b> יום שני חמשי וערב ר\"ח להתעורר בלב נשבר, ובערב ר\"ח לומר הוידוי במרירות ובתחנונים רחמים ובכל לילה הפסוק בידך אפקיד רוחי.</span>\nפרק ו) היוצא מכל הנ\"ל שבענין התשובה יש ב' בחינות, הא'"],[1900640350,"הנקראת תשובה במעשה שזו היא עזיבת החטא כנ\"ל, והב' היא הנקראת תשובה בלב שזו היא בחי' תשובה פנימית מעומקא דלבא ובבכי' בדמעות בשעת הודוי כנ\"ל, ובחינת תשובה במעשה הנ\"ל מחויב לעשותה תמיד שלא לשכח על זה ח\"ו, והיינו שיהי' שומר את עצמו בתכלית ההרחקה שלא תומשך מחשבתו מחשבת חוץ ח\"ו בכדי שלא יומשך עוד למחשבה רעה לעשותה בפועל ממש, ומכל שכן לשמור את נפשו ולהרחיק את עצמו מלכנס ח\"ו במקומות שיוכל לפול בהם ברע ח\"ו, כי באמת אפילו גם במחשבה בעלמא אם יתקע מחשבתו במזיד במחשבה זרה ורעה כמו תאות נאוף וכיוצא בה אזי נקרא בשם רשע שאינו רוצה כלל לעשות תשובה, ואז אפילו אם לפעמים נתעורר בתשובה מכל מקום איננה באמת לאמיתתה כלל וכלל, מחמת כי הוא חוזר בתמידות לטומאתו במזיד ממש ח\"ו.\n<span data-k=\"ks\"><b>קיצור.</b> תשובה בלב, תשובה במעשה עזיבת החטא בפועל וצריך לשמור עצמו תמיד ולהרחיק עצמו מלכנוס למקום שיוכל ליפול ברע, החושב במזיד מחשבה רעה נקרא רשע.</span>\nפרק ז) <b>כללא</b> דמלתא ראשית ועיקר התשובה היא במחשבה במוח שעל ידי זה נמשך ממילא גם בחינת רצון בלב הנקרא רעותא דלבא (כנ\"ל פ' ג') ועיקר סימן טוב לתשובה האמיתית הוא כשנעשה ההסכם חזק בהחלט מחשבתו ודעתו שעל להבא ישמור את עצמו בתכלית מלעשות איזה דבר מדברים האסורים, ומתחרט הוא באמת על העבר כנ\"ל, וכשעושה כך ונזהר מאד מאד"],[1900640358,"במחשבה (כנ\"ל פ' ו') אזי ממילא לא יומשך עוד רצון בלב לעשות הרע בפועל ממש ח\"ו.\n<span data-k=\"ks\"><b>קיצור.</b> ההסכם המוחלטי בחרטה על העבר ובשמירת המחשבה להבא הוראה על תשובה אמיתית.</span>\nפרק ח) <b>והנה</b> יש עוד שרשים המביאים לידי תשובה במחשבה ותשובה בלב ושתתקיים בנפשו היטב בשפת אמת עד עולם, דהיינו העינים שיהי' עוצם עיניו מראות ברע אפי' בדרך הבטה והעברה בעלמא, ומכל שכן שלא להסתכל במזיד ביופי הנקבות, ופשיטא דפשיטא שלא להרבות שיחה עמהם ולהתפקח עמהם בצותא חדא ח\"ו, כי בזה ועל ידי זה נעשה בלבבו חום התאוה ברשפי אש זרה ורעה ח\"ו, שנמשך ממילא אחרי כל מיני הרע שהי' בו מקודם, וחוזר עוד לסורו ח\"ו, וכידוע שהעינים הם המה הסרסורים המביאים האש זרה הנ\"ל למדות שבלב, והמדות שבלב נעשו גם כן סרסורים להביא לידי מעשה בפועל ח\"ו, כללא דמלתא העין רואה והלב חומד וכלי המעשה גומרין, פירוש שכל עיקר הסבה וגרמא בנזקין לכל הבעלי תשובה שאינם שבים לפניו ית' בשלמות וחוזרים עוד לסורם ח\"ו להפיל את נפשם בטומאתם בבאר שחת ח\"ו הכל הוא על ידי סרסור העינים כנ\"ל וכל זה הוא בדוק ומנוסה.\n<span data-k=\"ks\"><b>קיצור.</b> השרש המביא לידי תשובה במחשבה שרש הפועל, ותשובה בלב היא שמירת העיכוב בדבר האסור אפילו בדרך העברה.</span>\nפרק ט) <b>ואפילו</b> שלא נפל בעבירות חמורות רחמנא לצלן, מחויב הוא גם כן לשמור את נפשו להיות עוצם עיניו מראות כנ\"ל, מחמת כי כל זה היא הסבה שמביאו לידי מקרה לילה וכיוצא"],[1900640365,"בזה רחמנא לצלן, ועוד זאת כי גם הנשים מחויבות גם כן לשמור את עצמן מכל הנ\"ל ולהתרחק מזה בתכלית כי ההסתעפות שנסתעף מזה אצלן היא מזקת ביותר, והיינו כי על פי הרוב רובא דרובא הוא כהיתר גמור אצלן להסתכל ביופי הזכרים ולהרבות שיחה עמהם באין מעצור לרוחם, ואחר כך בלילה שעת השנה נופלים ונכשלים מזה בהרהורים רעים וחלומות רעים מעניני הזווג ומצד זה מולידות בהילדים חולאים שנולדו לכתחלה בחולי רעה הנקרא בלשון אשכנז, שלעכטע נאטורין רחמנא לצלן, אשר בעונותינו הרבים רובם ככולם כמעט מתים ולא נשארו בחיים רק חלק חמישית או יותר, וכל זה הוא רק בעון הזה רחמנא לצלן.\n<span data-k=\"ks\"><b>קיצור.</b> הראי' גורמת מקרים רעים, וגם נשים מחוייבות להזהר בזה והעדר השמירה גורם חולי הילדים ומיתתם.</span>\nפרק י) <b>זאת</b> ועוד אחרת בענין השרשים המביאים לידי תשובה שלמה באמת כך הוא, דהיינו שמחויב הוא לשמור את נפשו מהוללות ולצנות שנמשך מצד עוצם פתיחת הלב לכל דבר באין מעצור לרוחו הנקראת זחות הלב ופתיחתו ביותר שלבו פתוח לכל דבר בכל מיני שחוק וכל קלות ראש. וממילא מרחיב פיו ולשונו גם ברבוי דברים בטלים עד שנופל גם במעשה בכל מיני תאות עולם הזה כמו להיות זולל וסובא וכיוצא בזה, מחמת כי הוא רק הולך ושובב בדרך לבו כל היום (הנק' בלשון אשכנז פרישקייט און פרייליכקייט) וכל זה הוא היפוך גמור מבחי' התשובה. והטעם הוא כי שרש ועיקר התשובה באמת הוא ענין ובחי' לב נשבר הנ\"ל שזהו היא הבושה וההכנעה תמיד בלבו שלא יקל ראשו בשום פעם לאיזה דבר מכל הנ\"ל ח\"ו. והסימן לזה הוא בשני אופנים, הא' הוא שיהי' נבזה בעיניו נמאס, ותמיד יהי' מצר ודואג בלבו על חטאות נעורים והרהורים רעים וחטאים ועון קרי ומוציא זרע לבטלה רחמנא לצלן, ואזי על ידי זה ממילא לא יוכל להרים ראשו ולבו בחוצפא יתירה כל כך להיות בהרחבת הפה ולשון מדברת, ברבוי דברים בטלים של הוללות אפילו במלין דשטותין בעלמא שאינו נבול פה וכיוצא, וכן לא יומשך גם כן בשרירות לבו באכילה ושתי' וכיוצא, והיינו בשומו אל לבו היטב על כל המעשים רעים וחטאים שלו, שמוכרח הוא לתקן הנפש בכמה תעניות וסגופים, ולא די שאינו מתקן את נפשו אלא אדרבה הוא מוסיף פשע לאבד ולשחת את נפשו לגמרי חס ושלום על ידי הוללות ולצנות ותאוות רעות שמפילים אותו לבאר שחת ח\"ו שיהי' חוזר עוד לסורו כבראשונה, באופן שלא יהי' לו עוד שום תקוה לעולם ח\"ו"],[1900640370,"שלא יוכל לבוא עוד לבחינת לב נשבר הנ\"ל עד עולם, ויהי' נמנה ח\"ו בין אותם שאין מכניסים אותם במחיצתו של הקב\"ה ואין מספיקים עוד בידו לעשות תשובה, והיינו שהשטן הוא היצר הרע הוא המסית ולהפילו בכל הנ\"ל בכדי שיבא לידי שאול ואבדון לגמרי בלא תשובה עד עולם ח\"ו.\n<span data-k=\"ks\"><b>קיצור.</b> זחות הלב ושרירותה מביאים לידי הוללות ליצנות ודברים בטלים היפך התשובה בבושה והכנעה שנבזה בעיניו נמאס.</span>\nפרק יא) <b>והסימן</b> הב' לתשובה האמיתית הוא שהבושה וההכנעה והלב נשבר שלו יהי' גם מצד אמיתת כח ואור אלקי מלמעלה בבחינת השגה במוחו ולבו תמיד ואזי בזה ועל ידי זה לא ירום לבבו עוד כלל וכלל להיות נמשך גם בדברים המותרים כמאכל ומשגל וטרדת דאגת הפרנסה להיות ירא לנפשו שיהי' בריוח ולא בצער ומכל שכן בהוללות ולצנות ח\"ו, והטעם לזה הוא כי בחינת לב נשבר הנ\"ל על ידי נבזה בעיניו נמאס כו', שלא מצד השגה במוח ולב כלל לא יתפעל מזה רק לשעתו בדרך העברה בעלמא מן השפה ולחוץ ולא מתוך תוך פנימית לבבו שיהי' לבו נשבר באמת לאמיתו, ואזי ממילא יוכל לפול עוד ברע ח\"ו בלי שום ספק, ועל זה אמרו רבותינו ז\"ל רשעים מלאים חרטות, כי התשובה שלהם היא רק לשעה ואחר כך חוזרים ומתחרטים והולכים בשרירות לבם כו', והשי\"ת אינו מקבל לשבים כאלו, ששקר ענו בנפשותיהם, ואדרבה יהי' נדח ממנו נדח ח\"ו, שלא יוכל לעשות תשובה עוד עד עולם.\n<span data-k=\"ks\"><b>קיצור.</b> ההכנעה הבאה מהשגה היא רק לשעה ועלול לחזור לסורו, אבל הבאה מלמע' מהשגה הוא ירא להיות מרווח ומסגף גם מדברים המותרים.</span>\nפרק יב) <b>ואף</b> על פי כן אין חיוב על הבעל תשובה לעסוק בתעניות וסגופים ולכוף את ראשו בחיצונית שיהי' נגלה ונראה מבחוץ שהוא בבחינת לב נשבר. כי השרש ועיקר של כל הנ\"ל הוא הלב דהיינו שהש\"י כביכול אומר תן לי לבך ועיניך (כמאמר רחמנא לבא בעי) ובזה אדע כי חפץ אתה בתשובה לשוב"],[1900640374,"אלי ממש, וכידוע על פי מאמר רבותינו ז\"ל דאפילו יתענה מאה תעניתים לא יתקן את נפשו כל כך, כמו על ידי לב נשבר באמת ובתכלית אפילו פעם אחת בלבד (דוגמא לזה ממה שנתבאר בשער התשובה חלק ג' סימן ו' בענין ביאור הפסוק תחת גערה במבין מהכות כסיל מאה יעוין שם היטב) ועל כן אין החיוב עליו להתנהג בחיצונית במדת הפרושים, ואדרבה שמחויב הוא להיות בשמחה ששב מדרכו הסוררה לדרך הטובה והישרה, ויצא ממות לחיים, רק שיזהר בכל שעה ממש שלא ירום לבבו ח\"ו להרחיב פיו ולשונו בדברים בטלים, גם יזהר את עצמו שיהי' שפל רוח בפני כל אדם אפי' בפני הפחותים והגרועים ממנו דהיינו שהוא יתבונן בנפשו היטב איך שכולם טובים וכשרים ממנו, ואזי ממילא אפילו אם יחרפו ויגדפו אותו לשפוך סוללה על פניו יותר מכפי המדה יקבל גם כן באהבה לכפרה על עונותיו. וגם יזהר את עצמו שלא להיות זולל וסובא ח\"ו, זולת בסעודת יום טוב זמן שמחתנו שהיא סעודת מצוה רשאי אז להרבות מעט באכילה ושתי'. ומכל שכן להרחיק את עצמו לגמרי מהוללות ולצנות כנ\"ל, ויהדר בתמידות להיות בדבוק חברים, עם יהודים הכשרים יראים וכן שלמים, ולא להתחבר לרשע ח\"ו, כמו שכתוב אשרי האיש אשר לא הלך בעצת רשעים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> לב נשבר באמת טוב ממאה תעניות, ולא רק שלא יהי' ניכר בחיצוני' כמדת הפרושים אלא יהי' בשמחה ששב לה' ויהי' שפל ונעלב.</span>"],[1900640378,"פרק יג) <b>כתיב</b> וחטאתי נגדי תמיד, הנה דוד המלך עליו השלום אמר הפסוק הזה להורות וללמד דרכי התשובה באמת, דהיינו שמעולם לא הסיח דעתו להרהר בתשובה על ענין החטא שלו, בשומו אל לבו תמיד כאלו החטא עומד לנגדו בכל רגע ממש, בכדי שיהי' לו לב נשבר באמת, וכך כל בעל תשובה האמיתי מחויב להתנהג כן דהיינו שלא יסיח"],[1900640382,"דעתו כלל וכלל מענין החטאים שלו, ואפילו בלכתו בשוק כל היום ופונה לבצעו בטרדה רבה בעסקים, או אפילו באותן העתים שכולם שרויים בשמחה כמו באיזו שמחה של מצוה או שבת ויום טוב, מכל מקום הוא מחויב להתבונן ולשים אל לבו היטב איך שהוא גרוע ופחות ערך מכולם, ויעשה חשבון עם נפשו איך שהוא חוטא ופושע יותר מכולם ואין דוגמתו ממש, עד שיבא מזה לתכלית השפלות במרירות עצומה בבחינת לב נשבר ונדכה בתכלית, ואזי על ידי שהוא מכיר מקומו השפל ונבזה בעיניו נמאס אזי משגיח עליו השי\"ת לקבל אותו בימין קרבתו, כמו שכתוב וימינך פשוטה לקבל שבים, פירוש שבים דהיינו אותם שעושים תשובה תמיד בלא היסח הדעת דוקא.\n<span data-k=\"ks\"><b>קיצור.</b> השב צריך להיות חטאו תמיד גם בשבת ובזמני שמחה לנגד עיניו עד שיתמרמר בנפשו תמיד על זה.</span>\nפרק יד) <b>על</b> כן אמרו רז\"ל כל ימיו בתשובה פירוש שיהרהר בתשובה בתמידות יום יום דוקא, ולא שיבכה בדמעות ויתפעל לשעה בלבד ואחר כך תיכף יטה את לבבו בעניני העולם ובעסקים, כי בזה ועל ידי זה יוכל לחזור לסורו ולילך בשרירות לבו הרע ח\"ו, וכאשר נראה בעליל שרבים נבוכו בזה, וזהו באמת כמו אחטא ואשוב כו', שעל זה אמרו רז\"ל רשעים מלאים חרטות כו', ואינם רוצים כלל לעשות תשובה, כי שרש ועיקר הבעל תשובה האמיתי שיעשה ההסכם חזק בלבו שלא יסיח דעתו מכל הנ\"ל, ובהתפעלות אמיתית מנקודת לבבו דוקא בכל עת ובכל שעה בכדי שלא ישתנה ח\"ו עד עולם, וכל לבבות דורש ה' ובוחן כליות ולב לדרוש רק על אור האמת שבנקודת לבבו, ואז ממילא ישלח הוי' עזרתו מקדש לקבל אותו בימין מקרבת כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> וזהו כל ימיו בתשובה, ולא רק התפעלות זמנית ואז תשובתו מתקבלת.</span>\nפרק טו) <b>והנה</b> שרש ועיקר הכונה של בחי' תשובה בכלל הוא בכדי לתקן את נפשו דהיינו תקון הפגמים שפגם בצלם אלקים, כי על ידי הפגמים שפגם בנפשו אזי נעשה מות הרוחני גם בנשמתו האלקית ונפסק החבל, חבל נחלתו בשרש נשמתו למעלה שלא יוכל לקבל עוד חיות אלקי למטה בנפשו וכמו שכתוב הכרת תכרת הנפש כו', אבל על ידי התשובה כתיב והרוח תשוב אל האלקים כו'. פירוש שנפשו ורוחו חוזרים ושבים למקורם ושרשם מקור החיים, חיי החיים אור אין סוף ברוך הוא, נמצא שעל ידי התשובה יצא ממות הרוחני לחיי האלקי ויחי' נשמתו בחיי האלקות כעין תחית המתים בגשמיות ממש, וכמו שכתוב שובו שובו כו' ולמה תמותו כו', אם אחפוץ במות הרשע כו' כי אם בשובו מדרכו וחי' כו', ועל כן זאת היא תורת האדם בעולם הזה, ראשית שכל בעל תשובה יאמין באמונה שלמה שעל ידי תשובה האמיתית יזכה לחיים נצחיים שיצא ממאסר הגוף בחי' מות בנשמתו, ולכלל ולדבק בחיי נשמתו חיי החיים אור אין סוף ברוך הוא, שזהו ממש כמו ממות לחיים בגשמיות, ואחר כך מזה גופא צריך להיות בשמחה ובטוב"],[1900640386,"לבב מאד שיהי' שש ושמח בנפשו על שיצא ממות ורע לחיים וטוב, וכמו שכתוב ראה נתתי לפניך היום את החיים ואת הטוב ואת המות ואת הרע כו', וזהו עיקר הסימן של הבעל תשובה שהתשובה שלו היא באמת לאמיתו.\n<span data-k=\"ks\"><b>קיצור.</b> הפגם גורם מות בנה\"א וע\"י התשובה תחיית המתים בחיים נצחיים, וישמח בזה מאד.</span>\nפרק טז) <b>על</b> כן מטעם הנזכר לעיל מצינו בכמה ספרי יראים וספרי מוסר שהבעל תשובה יתן צדקה לעניים בכל ערב שבת קדש ובכל ערב ראש חדש, מפני שעל ידי הצדקה והחסד שעושה עם העני מחי' לנפשו בגשמיות, לפיכך בזה ועל ידי זה גופא זוכה הוא ג\"כ לחיים האמיתים להוציא את נפשו ממות הרוחני ויאיר בנשמתו אור וחיות אלקי, כי כמו שמצינו ברוצח נפש שהוא חייב מיתה, מחמת כאשר עשה כן יעשה לו, כמו כן בענין ההיפך במי שמחי' את הנפש זוכה הוא גם כן לחיים וכנזכר לעיל, וזהו גם כן מה שכתוב צדקה תציל ממות כו', פירוש כמו שהצדקה תחי' ותציל ממות בגשמיות דהיינו שקורע גזר דינו שנגזר עליו למות חס ושלום, כן הוא נצול גם כן על ידי הצדקה ממות ברוחניות, דהיינו שלא תכרת הנפש משרשה חס ושלום, ואדרבה שזוכה שתשוב למקורה ושרשה, בכן יתנהג את עצמו בחוק קבוע ליתן צדקה בעתים המיוחדות הנזכרות למעלה וגם יתענה בהם כי על ידי התעניתים וסגופים ממעט חלבו ודמו שיש בו מרבוי התענוגים שהי' לו על ידי התאוה הרעה ברשפי אש זרה שעל ידי זה נכלל ונדבק בשלש קליפות הטמאות לגמרי, כללא דמלתא שעל ידי התעניתים והסגופים בגשמיות על ידי זה דוקא נשבר גופו הגשמי ובזה ועל ידי זה נעשה תקון בפגמי הנפש שפגם בצלם אלקים בכל חטא בפרט על ידי התאוה רעה שהי' לו בשעת מעשה ועל ידי מעשה הצדקה שעושה אז ביום התענית דוקא שנשבר אז גופו בקרבו אזי יכול להחיות גם נשמתו בחיי האלקים ממקור החיים וכנזכר לעיל.\nקיצור. כשם שבגשמיות ע\"י הצדקה ניצל העני ממות הן ע\"י הצדקה"],[1900640389,"בכלל וביום תענית הסיגופים בפרט מתקן פגמי נפשו וזוכה לחיים רוחני'.\nפרק יז) <b>כבר</b> נתבאר (סימן ו' וסי' ז') בשרש עיקר ענין התשובה שיש בה שתי בחינות האחת היא בחינת תשובה במחשבה במוח ורצון בלב, והב' היא בחינת תשובה במעשה שזו היא עזיבת החטא, גם נתבאר לעיל (סימן ח' וסימן ט') בשרשי התשובה שגם העינים הם המה הסרסורים כו'.\n<b>ביאור</b> הענין דהנה בחינת תשובה במחשבה במוח ורצון בלב אי אפשר להיות כי אם על ידי העינים שיהי' עוצם עיניו מראות ברע כו', והיינו מה שכתוב ולא תתורו אחרי לבבכם ואחרי עיניכם כו', ופי' שהבעל תשובה מחוייב לסגור לגמרי העינים שלו ולא לפתוח אותם גם מלהביט בדרך העברה בעלמא על איזה דבר מדברים האסורים ח\"ו ומכל שכן שלא להסתכל במזיד, פי' אפי' אם אין הלב חומד לזה כלל וכלל אלא שאינו סוגר את עיניו מלהביט על זה מרחוק, מכל מקום מאחר שההבטה היא בכונה רצוי' על כל פנים גם זה נקרא מזיד ממש, ופשיטא דפשיטא שלא להתבונן במוחו בענינים כאלו בכונה שזהו הנקרא המסתכל כו', כי בזה ועל ידי זה יבוא גם לידי הרהור וחמדה בלב, ואח\"כ לידי מעשה בפועל חס ושלום, שעל זה אמרו חכמינו ז\"ל העין רואה והלב חומד (שהם תרין סרסורי דחטאין), וכלי המעשה גומרים, וכמו שאמר איוב ומה אתבונן על בתולה כו', וכידוע מארז\"ל על זה שעל ידי הרגילות להסתכל במזיד ביופי הנקיבות יפול הנופל בעבירה בפועל ממש ח\"ו, ובפרט במקומות של חבורת הנשים שיושבות שם לבדן ואין שם אנשים מחויב הוא לשמור את נפשו ביותר, ולהרחיק את עצמו משם לגמרי שלא ישב עמהן בחבורה ולא ידבר עמהן מאומה אלא אדרבה שיסתום את עיניו לגמרי ויברח מהן בכדי שלא יבוא לידי הרהור וחמדה בלב חס ושלום, ואפילו בשעת עסק בלכתו בשוק או בין החנויות יזהר את עצמו גם כן שלא לדבר עמהן אפילו דבור קל, כי אם בצרכי העסק בלבד, וכן גם הנשים היושבות בין החנויות גם הן ישמרו לנפשותיהן שלא"],[1900640392,"להרבות שיחה עם האנשים הנערים כי דבר זה מזיק לתחלואי הילדים רחמנא לצלן כנ\"ל.\n<span data-k=\"ks\"><b>קיצור.</b> התשובה במחשבה שבמוח ורצון שבלב תלוי' בשמירת הראי' בדבר האסור ואפילו הבטה מרחוק מזיק.</span>\nפרק יח) <b>ובחינת</b> תשובה במעשה שהיא עזיבת החטא זהו הנקרא עיקר התשובה באמת לאמיתו על פי התורה כמו שכתוב יעזוב רשע דרכו כו' וכנ\"ל שעל ידי זה דוקא השי\"ת מוחל וסולח לו לכל עונותיו, והחיוב בזה הוא על ענין קרי ומוציא זרע לבטלה רחמנא לצלן ומכל שכן על עבירות החמורות כו', והקבלה והחרטה בלב יקבל על עצמו בשעת הודוי בעל חטא כו', ובשעה שאומר ועל חטאים כו' ישפוך את נפשו ויאמר בכל לבו ויקבל על עצמו כל הד' מיתות בדבור שמוציא בפיו כפי חטאו שחטא וכפי שידע אינש בנפשו גם העבירות שזוכר אותם בפרט מחויב הוא גם כן לפורטם בודוי, ויבקש סליחה ומחילה מהשם יתברך על העבר ויקבל על עצמו שלא ישוב עוד לחטוא ח\"ו, וזהו עיקר התשובה האמיתית שהשם יתברך מוחל וסולח לו באמת ומקבל לתשובתו באהבה ורצון באמת.\n<span data-k=\"ks\"><b>קיצור.</b> עיקר התשובה עזיבת החטא בפועל, והחרטה בשעת הוידוי ושפיכת הנפש באמרו ועל חטאים.</span>\nפרק יט) <b>וזהו</b> מה שאמרו רבותינו ז\"ל הבא לטהר מסייעין אותו מלמעלה הבא לטמא פותחין לו כו' פירוש הבא לטהר את לבבו מכל מיני רע על ידי תשובה באמת אזי הקב\"ה מסייעו ישועות רבות וטובות דהיינו שנותנים לו מלמעלה מחשבות רבות וטובות שעי\"ז ממילא לבבו נשבר בקרבו באמת ונעשה סור מרע בתכלית תמיד מה שאין כן להיפך חס ושלום הבא לטמא את עצמו במחשבות זרות ורעות חס ושלום אזי פותחין לו מלמעלה השערי טומאה דהיינו שמפילים אותו במחשבות זרות והרהורים רבים ורעים שיפנה את כל לבבו לכל מיני רע ח\"ו, ואין נותנים לו מלמעלה שום מחשבה טובה לעולם שישים אל לבו לעשות תשובה, בכדי שיאבד את נפשו בבאר שחת ויפול בשאול ואבדון חס ושלום, וכל זה הוא למי שלא עשה תשובה מעולם וחטא ומחטיא את הרבים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> השב לטהר את לבבו מהרע מסייעין לו במחשבות תשובה ולב נשבר, והחוטא ומחטיא מפילים לו מחשבות רעות.</span>\nפרק כ) <b>אך</b> מי שעשה תשובה באמת וברצון רק שאחר כך חזר עוד על כל חטאתו אשר חטא ונפל עוד בחטא ההוא רחמנא לצלן זהו הנקרא בעל תשובה מרומה (הנקרא בלשון אשכנז א פאלשער בעל תשובה) ועליו אמרו רבותינו ז\"ל רשעים מלאים חרטות כו', פירוש אותם שעושים תשובה לשעה"],[1900640394,"וחוזרים ונופלים אח\"כ הלא המה כרשעים ממש יחשבו מחמת שאינם רוצים כלל לעשות תשובה שלמה באמת. וזהו כטובל ושרץ בידו שאין הטבילה כלום מחמת כי טומאתו בידו וכך הוא ממש בענין בעלי תשובה הללו שאינה נתקבלת ואינה נחשבת לכלום התשובה שלהם לפני השם יתברך מחמת כי טומאתם על פניהם בשעת מעשה התשובה גופא, ומכל מקום גם הבעל תשובה מרומה הנ\"ל יש לו גם כן מזור ומרפא למכתו. ויש עליו עוד תקוה יותר ויותר ממי שלא עשה תשובה מעולם וחוטא ומחטיא כו' כנזכר לעיל כי אותם שלא עשו תשובה מעולם והולכים בשרירות לבם רק רע כל היום ולכל אשר יחפוץ יטנו לכל תועבה רחמנא לצלן באין מעצור לרוחו ממש, אזי אין להם תקומה לעולם ונמשכים ממילא אחרי כל התאות רעות רחמנא לצלן עד שנדחים לגמרי ממנו יתברך ונופלים באיזה מכשול של איזו עבירה או באיזו תאוה רעה חס ושלום ואח\"כ חוזרים ושבים כו', אזי מרחמים עליהם מן השמים ומסייעים אותם מלמעלה שיוכלו לעשות תשובה שלמה באמת שלא יבושו ולא יכשלו עוד לעולם, והיינו מחמת כי באמת יש להם הרהור תשובה בלבד בתמידות רק לעת מן העתים לא יוכלו להתגבר על יצרם הרע ולשבור רוחם ותאותם הרעה רחמנא לצלן, ואזי השם יתברך שהוא דורש כל לבבות ובוחן כליות כו', מבטש אותם בבני חיי ומזוני ביסורים קשים ומרים מאד מאד עד שנשבר רוחם ולבבם בקרבם באמת לאמתו ואז יוכלו לעשות תשובה שלמה באמת שלא יהיו חוזרים עוד לסורם לפול באיזה מכשול חס ושלום עד עולם, ועי\"ז מוחל וסולח להם הקב\"ה את כל עונותיהם לכפרה גמורה על נפשותיהם כמאמר יסורים ממרקים כו'.\n<span data-k=\"ks\"><b>קיצור.</b> השב באמת לשעה וחוטא הוא בעל תשובה מרומה, כאשר מבטשים אותם בבני חיי ומזוני נשבר לבם בקרבם ושבים באמת.</span>\nפרק כא) <b>והנה</b> כל הנ\"ל בענין היסורים בבני חיי ומזונא כו' זהו מצד מדת רב טובו וחסדו הגדול רק הגדול רק לאותם האנשים שחפץ בתשובתם דהיינו לאותם שטעמו טעם מר ועשו תשובה באמת פעם אחת ואזי ע\"י רוב הבטושים והיסורים הנ\"ל אזי ירוחמו ולבבם נשבר בקרבם באמת לאמיתו, אבל אותם האנשים שמעולם לא עשו תשובה באמת אפילו פעם אחת רק שלעת מן העתים הכניסו איזה הרהור תשובה בלבבם לפי שעה מן השפה ולחוץ בדרך העברה בעלמא ותיכף ומיד חוזרים לסורם להיות הולך ושובב בשררות הלב לכל מיני תועבה רעה רחמנא לצלן אזי אין הקב\"ה חפץ בתשובתם כלל וכלל ולא די שאינו מיסר אותם ביסורים אלא אדרבה שולח להם רב שפע והצלחה יתירה בעניני עולם הזה ומלואו בכדי שלא יעשו תשובה עד עולם, והסימן לזה יוכל כל אחד ואחד לידע האמת בנפשו והיינו אם הוא עושה"],[1900640396,"תשובה באמת לאמיתו אזי עושה לב נשבר ונדכה מאד וגם שפל באמת לאמיתו בפני כל אדם אפילו מן הפחותים וגרועים ממנו כנ\"ל (סימן יב) וממילא נעשה ג\"כ סור מרע בתכלית דהיינו אפילו אם לעת מן העתים יפול בנפשו באיזו מלחמה עם היצר הרע אזי בקל יוכל לעמוד נגדו ולהתגבר עליו ולנצחו ולהפילו ארצה ממש, זאת ועוד אחרת אפילו אם הוא נכשל בעבירה מאיזו סבה דהיינו במי שהוא שרוי כמה שנים בלא אשה או במי שהי' מתחבר עם אנשים קלים ורקים שמסיתים אותו לחטוא על ידי שמפתים אותם בפיהם ובלשונם לישב עמהם במקומות המיוחדים (הנקראים בלשון אשכנז טראקטירן) בין זוללי בשר וסובאי יין שעל ידי כל זה יפול ממילא באיזו עבירה במעשה רחמנא לצלן, אך מכל מקום לא נכשל במעשה העבירה הזאת כי אם פעם אחת ותיכף ומיד אחר כך תוהא ומתחרט על העבר ונפשו עליו תאבל ורבות מכאובים בלבו על זה ובוכה במר נפשו ומרבה בתעניתים וסגופים ועושה תשובה שלמה באמת לאמיתו ומקבל על עצמו לבל ישוב עוד לכסלה ויזהר את עצמו מכל הסבות הנזכרין לעיל שלא יבוא עוד לאיזו עבירה בפועל ממש חס ושלום רחמנא לצלן והקדוש ברוך הוא בוחן לבבות ורואה האמת כי רוצה בתשובה באמת לאמיתו ואזי השם יתברך מוחל וסולח לו מלמעלה, והסימן הוא להיפך כאשר מי שנכשל בעבירה אחת נמשך לבו לעבירה אחרת וכמאמר חכמינו ז\"ל עבירה גוררת עבירה עד אשר יוכל לבא למלאות תאותו בעבירות חמורות ולעבור על כל לא תעשה שבתורה חס ושלום רחמנא לצלן עד שאחר כך לא יוכל לבא לתשובה עד עולם וכמאמר רבותינו ז\"ל בדרך שאדם רוצה לילך מוליכין אותו.\n<span data-k=\"ks\"><b>קיצור.</b> השב באמת גם אם נכשל חוזר בתשובה אבל החוטא ומחטיא אין מספיקין בידו ע\"י יסורין ומטיבין לו להאבידו, עבירה גוררת עבירה.</span>\nפרק כב) <b>בדרך</b> כלל סדר והנהגת בעלי התשובה צריך להשכים לקום ממטתו בבקר בבקר ותיכף ומיד כאשר יקום יראה להזכיר את עצמו כל החטאים שעשה מעודו עד היום זה כמו שאמר דוד המלך עליו השלום וחטאתי נגדי תמיד ויאמר קאפיטל תהלים נ\"א מקרב ולב עמוק ובפרט כשיאמר פסוק כבסני מעוני כו', ואם אפילו לא עבר על עבירות חמורות חס ושלום צריך לומר גם כן הקאפיטל נ\"א דוקא, כי אפילו מי שפגם בהרהור זנות חס ושלום או באיזה מעשה זמה חס ושלום הרי זה גם כן חמור מאד, ועל זה נאמר כי השחית כל בשר את דרכו כו' ואפילו מנעוריו כשהי' עדיין קטן קודם בר מצוה, ומכל שכן אחר שלש עשרה שנה כשהוא נעשה בר עונשין יתענה כסדר ויאמר הקאפיטל הנ\"ל בכל יום ובכל שבוע בשני ובחמשי ובכל ערב ראש חדש ובתפלת מנחה יאמר על חטא"],[1900640398,"ועל חטאים כו' ויזכור על כל החטאים שלו ויבקש סליחה ומחילה מהשם יתברך.\n<span data-k=\"ks\"><b>קיצור.</b> הנהגת הבעל תשובה לזכור חטאיו ולומר מזמור נ\"א ויכון בכבסני מעוני גם מה שחטא קודם עונת בר מצוה.</span>\nפרק כג) <b>יאמר</b> תהלים בכל יום קודם התפלה כי הרי מבואר שם היטב עניני התשובה מאד ויתפלל מתוך הסדור בהכנעה גדולה, ובשעה שעומד לפני השם יתברך להתפלל יהי' בבושה וחרפה גדולה ויאמר מתוך הסדור כל מלה במלה בהכנעה גדולה היינו בבטול אמיתי מתוך נקודת ועומק הלב, ויתן באמת שבח והודי' להשם יתברך אשר זכה להתקרב לפני השם יתברך ולא ידח ממנו נדח להיות נשאר ברע חס ושלום, ומזה יהי' אחר כך בשמחה רבה בשעה שאומר פסוקי דזמרה מברוך שאמר עד קריאת שמע ושמונה עשרה, אך קודם ברוך שאמר צריך להיות בהכנעה ושפלות גדולה על החטאים שלו, וכמאמר רבותינו ז\"ל אין עומדין להתפלל אלא מתוך כובד ראש, הכנעה ובטול מחטאות נעורים כאשר ידע אינש בנפשו היטב גם לא יהי' מוטעה בעצמו, ואל יהי' זאת בעיני עצמו לדבר קל חס ושלום.\n<span data-k=\"ks\"><b>קיצור.</b> יאמר תהלים קודם התפלה ויתפלל מלה במלה מתוך הסידור בהכנעה.</span>\nפרק כד) <b>בשמונה</b> עשרה בברכת סלח לנו צריך הבעל תשובה לזכור את עצמו על כל החטאים שלו ויבקש מחילה וסליחה עליו לבדו, ובפרט בברכת השיבנו כשמבקשים והחזירנו בתשובה שלמה לפניך יקבל על עצמו שיעשה תשובה שלמה, ובודאי יקבל השם יתברך בקשתו כמו שאנו אומרים הרוצה בתשובה, וכמו שכתוב וימינך פשוטה לקבל שבים, אך כל זה רק כי אם למי שהוא רוצה בתשובה באמת דוקא וכמו שכתוב קרוב ה' לכל קוראיו באמת ובברכת רפאנו יכוין להשם יתברך שירפא את חולי הנפש שלו אשר פגם על ידי העבירות שלו כי על ידי הפגמים שפגם בנפשו אזי נעשה מזה מות הרוחני גם בנשמתו האלקית שלא יוכל לקבל עוד חיות אלקי למטה בנפשו כנ\"ל באריכות, נמצא על ידי התשובה מחי' נשמתו בחיי האלקי לכן יבקש מהשם יתברך לרפא אותו מחולי הנפש שלא תמות נפשו ברוחני' להיות נכרתה משרשה חס ושלום כנ\"ל, ובברכת ולמלשינים יכוין על כל המקטרגים הרעים אשר נעשו להמשיך עליו מלמעלה על ידי העבירות שלו כי מכל מעשה רחמנא לצלן נעשה מלאך רע המקטרג אשר מעניש אותו בפרנסה בגשמיות וביסורי הגוף רחמנא לצלן כמו שכתוב תיסרך רעתך, על כן יבקש מהשם יתברך להעביר כל המקטרגים ממנו ומכל עמנו בני ישראל, ובברכת שומע תפלה יאמר בכונה גדולה ועצומה מקירות לבו ומעומק נקודת הלב לפני השם יתברך"],[1900640400,"שישמע את תפלתו ויעורר עליו רחמים רבים לקבל ברחמים וברצון את תפלתו ובודאי ישמע ה' את תפלתו כמו שאנו אומרים כי אתה שומע תפלת כל פה ובפרט למי שלבו נשבר בקרבו מאד מחמת חטאות נעורים ועושה תשובה ותפלה הקב\"ה עוזרו ומסיעו מלמעלה שיוכל להתקרב להשי\"ת באמת וממילא יקבל אותו השם יתברך ברצון וישגיח עליו תמיד בעינא פקיחא ברכושו ובכל הענינים שלו כמו שכתוב וישוב אל ה' וירחמהו וישמור אותו מכל הצרות שלא תבואנה עליו רחמנא לצלן רק בתפלת שמע קולנו יהי' מקירות הלב ומעומק נקודת הלב ובמרירות נפש. וכמו שמצינו בחנה בשעה שהיתה מתפללת נאמר וחנה מדברת על לבה והיא מרת וכו' ובעת נפילת אפים צריך הבעל תשובה עוד יותר להשפיל ולהכניע את עצמו ולקבל על עצמו כל הענינים והד' מיתות בית דין והאמור בתורה כמו בודוי שבקריאת שמע שעל המטה.\n<span data-k=\"ks\"><b>קיצור.</b> הכוונות בברכת השיבנו, סלח לנו, רפאינו, ולמלשינים, שמע קולנו ובנפילת אפים.</span>\nפרק כה) <b>ואחר</b> התפלה ילמוד כל מה שהוא יכול ללמוד אפילו פרשה אחת בחומש וקאפיטל א' מעשרים וארבעה מנביאים וכתובים, ופרק אחד או חצי משניות או שלחן ערוך אורח חיים ויחזיר למודו כמה פעמים ומי שהוא למדן ויוכל להבין ולהשכיל בתלמוד יראה לקבוע עתים לתורה וללמוד בית יוסף עם שלחן ערוך ואחרונים בכל יום בבקר ובכל שבוע לילה אחד ילמוד כל הלילה עד הבוקר ויתענה וילמוד דברי מוסר מזהר הקדוש וראשית חכמה בשער התשובה, והמתענה עד אחר חצות היום עד שעה א' יהי' נחשב לו לתענית ובשעת אכילה לא יאכל בתאוה כבהמה חס ושלום ויזהר שלא ימלא כרסו יותר מדי רק כדי לחזק את בריאת גופו ולא להתענג בתאות האכילה בחלב ודשן רק שיאכל מאכלים קלים כמו חלב עם לחם מעט בכדי שלא למלאות את בטנו מהאכילה שלא יבא מזה חלילה לשררות לבו הרע חס ושלום.\n<span data-k=\"ks\"><b>קיצור.</b> ילמוד חומש, נביאים וכתובים, משנה והלכה, זהר וראשית חכמה. ילמוד לילה אחת בשבוע כולה, והמתענה עד שעה א' אחר חצות נחשב לתענית.</span>\nפרק כו) <b>ועוד</b> זאת כי מחמת האכילה גסה עד שממלא כרסו, מזה יוכל להיות שיבא מזה לידי זמה ממש חלילה (וכמארז\"ל מלא כרסא זינין בישין). כי ברבוי האכילה נעשה לבו גס ועב מאד והגוף נעשה מגושם ומזוהם ומחמם הגוף ונעשה כבהמה ממש. וזה הוא ההיפוך גמור מלב טהור וענו ושפל, ומכ\"ש אותן אנשים אשר ישתדלו להתענג את עצמן במאכלים ומעדנים ערבים בכל"],[1900640402,"טוב בלי הסתפקות במועט גם אוכלים בתאוה וחמדה ותשוקה גדולה (ובלשון אשכנז נא[ך צו געבין זיך בתענוגים) אזי נעשה הגוף יותר מגושם עד שנעשה גופו דשן ושמן, וכמו שכתוב שמנת עבית כשית כו', ונעשה מזה לבו אטום ומטומטם כלב האבן וממילא לא יוכלו לבא להרהור תשובה כל ימי חייהם, ולכן כל בעל תשובה יזהר לאכול מעט גם לא בחמימות התאוה שלא יבא מזה לחום התאוה רעה חס ושלום רחמנא לצלן, גם יזהר שלא יעשה נחת רוח מתענוגים באכילתו שלא ירבה בכמה מיני מאכלים שונים זה מזה כי כל בעל תשובה צריך להרחיק את עצמו מכל זה שלא להרבות חלבו ודמו מהאכילה, אדרבה צריך למעט חלבו ודמו בסגופים לתקן את חום התאוה רעה מהחטאים שעשה רחמנא לצלן.\n<span data-k=\"ks\"><b>קיצור.</b> הזהירות באכילה שלא יגושם הן מריבוי האכילה והן מהעונג שבהם, וגם המוכרח לו יאכל במתינות וימעט דמו וחלבו.</span>\nפרק כז) <b>עוד</b> זאת יוכל להיות שיתהוה איזו סבה ע\"פ הרוב אשר הבעלי תשובה חוזרים לסורם הרע ועוד שוב יותר נכשלים המה במעשיהם הרעים ח\"ו, יותר מתענוג האכילה שנק' זולל והוא ממשקה הנק' סובא שיש לו תאוה וחמדה גדולה לשתות הרבה משקה חזק אשר כי הוא מחמם ודולק ושורף הלב וכל הגוף הוא מחמם כמו משקה היי\"ש שכאשר שותין אותו מעט יותר מכפי מדה הראוי' לו אזי נעשה כמו שלהבת נדלק בו לכל התאות רעות רח\"ל, בקיצור יי\"ש שורף הלב והנשמה כי הוא מחמם בה הדמים ומעבירו מדעתו לגמרי אפילו אותן האנשים אשר נקיים המה מחטאים יוכל להזיק אותם מאד, כי המה נעשים מחוממים מאד מזה ויורדים ונופלים ממדרגתם הנעלה ומעביר אותם מהשכל ויראת אלקים ויבאו לרוב מדות רעות ר\"ל היינו ככעס ומריבות וקטטות והגבהת הלב מאד אשר השי\"ת שנא זאת מאד וכמובא בפסוק ובספרים הרבה אשר הסובא מן המוכן לכל עבירות חמורות ח\"ו ובכן כל בעל תשובה יראה שלא לשתות שום משקה חזק אפי' שכר חזק ומכ\"ש יי\"ש לא יטעום לגמרי כי נעשה לו רגילות לשתות יין שרף קודם האכילה ב' או ג' פעמים בכן לא יטעום יי\"ש לגמרי אפילו קדוש והבדלה יעשה על שכר ולא על יין שרף בשום אופן.\n<span data-k=\"ks\"><b>קיצור.</b> יזהר משתיית משקה חריפה הגורמת חמימות הגוף והתרגשות המדות רעות בכעס ומריבה, ויקדש ויבדיל על משקה בלתי חריפה.</span>\nפרק כח) <b>כל</b> בעל תשובה יזהר את עצמו שלא לישן ביום תיכף אחר האכילה כי חום האכילה בתוך השנה הוא מרבה חום הדם ויוכל לבא מזה למחשבות רעות ומקרות רעות רחמנא לצלן כידוע בכן תיכף אחר האכילה יזהר שלא לישן בערך שעה אחת או יותר גם יראה לשבר את לבו בקרבו מזאת גופא אשר ירגיש בעצמו גסות ועביות הלב מחמת אכילה ושתי' ויראה לעשות איזה"],[1900640404,"עבודה בטרחא, ויתחזק את עצמו מאד להיות סור מרע במעשה ובמחשבה ולהזדרז במצות ובמעשים טובים בלב שלם וכמבואר בספרים שכאשר אוכלים רק לשם שמים ולא למלאות תאותו ואחר כך מברכים בכונה ברכת הזן כו' ואומר פסוק ואכלת ושבעת וברכת את ה' כו' הוא הזן ומפרנס כו' אזי נותן לו השי\"ת ברכה מרובה מן כח האכילה הזאת דוקא כדי שיהי' לו כח גדול להיות עובד את ה' בסור מרע ועשה טוב כנ\"ל, ובפרט כאשר יתן צדקה לעניים תיכף אחר ברכת המזון אפי' מעט כדי חיותם הוא תקון גדול להנשמה מכל רעות רחמנא לצלן וכמ\"ש שומר מצוה לא ידע דבר רע כו'. ומכ\"ש צדקה תציל ממות גשמי וממות הרוחני כנ\"ל והצדקה צריך ליתן בשתי עתים מיוחדות א' קודם התפלה וכמו שכתב דוד המלך ע\"ה אני בצדק אחזה פניך והב' אחר האכילה או קודם האכילה וכמו שכתוב בספרי יראים שיהדר לומר בכל יום מאה ברכות וזהו למען השם כדי להזכיר בכל רגע שהוא עבד ה' בכן יהדר למצוא בכל רגע לעשות מצוה להשי\"ת דהיינו לעמוד לפחות לפני למדן גם יראה אולי יש לו פנאי לילך מעסק הפרנסה שלו ללמוד איזה שיעור או לאמר איזה קפיטליך תהלים וכיוצא בו הכלל הוא יזהר שלא לשכוח שהוא עבד ה' ואזי הקב\"ה כביכול עוזרו ויסייעו לעבוד אותו וכמאמר רבותינו ז\"ל הבא לטהר מסייעין אותו מלמעלה כנ\"ל, גם עוד זאת כל בעל תשובה וכל ירא אלקים יזהר שלא לשכוח (שהבטלה מביאה לידי תאוה וזמה) גם יהי' בזריזות לעסוק במלאכתו או במסחרו באמונה ובלי שום רמי' נגד שום אדם ח\"ו, והנהנה מיגיע כפו אשרי לו וטוב לו בעולם הזה ובעולם הבא.\n<span data-k=\"ks\"><b>קיצור.</b> יזהר מהשינה ביום אחר האכילה, יתן צדקה קודם התפלה והאכילה, יזכור תמיד שהוא עבד ה' ויהי' זריז במלאכתו ואשרי הנהנה מיגיע כפו.</span>"],[1900640027,"להבין מ\"ש בפע\"ח דפסח ושבת ההפרש בין ו' יומין דחול לשבת שבחול הנהגות העולם ע\"י בחי' ו\"ק דעשי' ובחי' ו\"ק דיצי' מכוסה ונעלם בו\"ק דעשי', אבל בשבת מאיר ו\"ק דיצי' והוא בחי' עיקר המשפיע ובחי' ו\"ק דעשי' נכלל ובטל לו\"ק דיצי', וזהו בח[ו]\"ל אבל בא\"י גם בחול הנהגות העולם ע\"י ו\"ק דיצי' ובשבת ההארה וההשפעה מבחי' ו\"ק דבריאה בלתי התלבשות בו\"ק דיצי', וזהו לדוד בשנותו את טעמו כו' שפושט בגדי חול דיצי' ועשי' ומתלבש בבחי' אור הבריאה פוגם בחו\"ל הארת ו\"ק דבריאה בו\"ק דיצי' בלתי התעלמות בו\"ק דעשי' כמו בחול כו'). והנה לכאורה זה דבר פלא שהרי אין אנו רואים שום הפרש בין גידול דצח\"מ וכל מיני השפעת עוה\"ז בין חול לשבת, ואם הי' מקור השפעה בשבת ממקום ומדריגה עליונה יותר הי' צ\"ל נראה איזה שינוי בהשפעת וקבלת החיו' בשבת יותר מבחול כו', וגם יש להבין איך יתכן שיהי' השפעת עולם החומרי בשבת מבחי' ו\"ק דבריאה או דיצי' כו'. אך הנה יש להקדים שיש הפרש בין בחי' בחי' מעב\"ר לבחי' לבו\"ש, דהיינו שיש הפרש גדול בין כשההשפעה עוברת דרך מעבר בין כשההשפעה עוברת דרך [בחי'] לבוש, דהנה עד\"מ פעולת כל אברי הגוף ע\"י בחי' האור והחיות שבהן שאין האבר נק' לבוש אעפ\"י שמלביש ומכסה לאור וחיות שבתוכו, ולא נראה לעין רק פעולת גשם האבר ולא רוחניות, מ\"מ הכל יודעים שהעיקר הפועל הוא האור והחיות שבו ואין הפעולה נק' ע\"ש כלי הגוף כלל כ\"א ע\"ש בחי' האור והחיות שבהן דוקא, ע\"ד דוגמא כשאו' עיני רואה אין הכונה על עין הגשם אלא על כח הראי' הרוחניו' שבעין, וכן ההילוך ברגל אין הכונה על הרגל רק על בחי' האור וכח ההילוך. והטעם הוא כי כל כלי ואור שנק' חומר וצורה הנה בחי' הכלי והחומר בטל בתכלית לגבי האור והצורה הרוחניו' להיות כמו הגרזן ביד החוצב בלי יקרא שם פעולה ותנועה לגרזן מצד עצמו רק ע\"ש המניעו, וזהו הנק' השפעה הבאה בכלי בבחי' מעבר שהכלי אינו אלא כמו מעבר בעלמא אל האור דהיינו רק העברת האור דרך מעבר בכלי בלי יקרא שם פעולה מצד הכלי כלל כנ\"ל."],[1900640041,"<b>ויובן</b> זה יותר במשל כתיבת היד איזה שכל וחכמה שבמוחו, הגם שאין האצבע כלי וחומר מוכן לקבל צורת השכל שבמוח לומר בו שבטל לגבי האור כמו בשאר האברים, מ\"מ אנו רואי' שהאצבע הכותב בטל בכל חלקיו בתנועה פשוטה לכתוב כפי אופן הוראת השכל דוקא בלי נטי' ימין ושמאל, והיינו מפני שהוא רק בחי' מעבר אל הרצון והמחשבה שבגידי היד לצוק אופן הכתב והמחשבה מעבר אל השכל שבמוח, עד שאנו או' שהאצבע כותב דבר שכל אעפ\"י שרחוק ערך הבשר הגשמי לגבי רוחניו' השכל מ\"מ פעולת השכל נעשה על ידו דרך העברה במחשבה ומחשבה בגידי נערווי\"ן שביד וכמ\"כ התפשטות וקומץ היד עפ\"י הרצון והשכל וכה\"ג הילוך הרגל ושאר פעולת האברים עפ\"י הרצון והשכל [א]ו עד\"מ הרמז ביד לפי הוראת השכל וכה\"ג, כ\"ז נק' רק בחי' מעבר בלבד ולא בחי' לבוש, אע\"פ שנתעלם ונתלבש בכמה מיני העלם כמו העלם השכל שבמוח במח', ומח' בתנועה גשמי' שביד הכותבת, מ\"מ אין זה נק' לבוש כי בחי' הלבוש אינו אלא בחי' היפוך גמור מבחי' המעבר הנ\"ל כי הרי בבחי' המעבר הנ\"ל אין הכלי עולה בשם כלל (ולא כמו רוכב על הסוס שהסוס ג\"כ בטל לגבי רוכבו ואינו הולך רק עפ\"י הרצון המנהיגו והרוכב עליו, אבל מהות תנועות ההילוך הוא מצד הסוס משא\"כ תנועות הגרזן שאינו רק מצד המניעו וכן תנועות בשר האצבע רק מצד החיות שבו, אבל כתיבת האצבע אור השכל דומה לבחי' ביטול הסוס לגבי רוכבו אחר שיש לאצבע תנועה מכח החיות שבו רק שרצון השכל מנהיגו כו' וע\"י יפעל השכל פעולתו כו' וד\"ל).\n<b>אבל</b> הנה בחי' ההשפעה הבאה דרך לבוש נהפוך הוא, שהלבוש הוא בחי' נפרד לגמרי גם [מ]אברי הגוף ואין לו שייכות ויחו[ס] כלל עמם, וא\"כ ההשפעה שעוברת דרך בחי' לבוש נראה לעין הרואה שעיקר ההשפעה הוא ע[\"י] הלבוש עצמו ולא ע\"י הגוף כלל, להיות כי אין [ל]לבוש ערך לגבי אור וחיות הגוף עד שנאמר שהלבוש בטל לגבי הגוף ושהחיות שבו פועל ע\"י מלבושי הגוף כמו באברי הגוף עד שלא תקרא ההשפעה ע\"ש הלבוש כלל, שהרי אדרבה מלבד שהלבוש מכסה ומעלים לגמרי לאור וחיות הגוף, הנה הוא נפרד לגמרי מעצם האדם ונראה לעין כאלו הלבוש בלבד הוא הפועל מצד עצמו (והרי זה כמו הגרזן בלתי הגלות היד המניע כלל, וכן מרכבת סוסים כמו סוסים שחורים ואדומים דנבואת זכרי' שמדבר בע' שרים וגם נק' עננים כ[מ\"ש] רוכב על עב ק\"ל כו' [ו]גם נק' גרזן ביד כו' כי הגרזן נפרד מעצם היד וכן הסוס מן הרוכב כו'), וזהו ב' הפכים ביטול האבר לגבי האו' והחיו' שבו, עם פירוד הלבוש מעצם גוף האדם, וכנראה לעין באדם כאשר הולך בלבושי' שאז אין התנועה נכרת באברי גופו כלל וכ[לל] רק התנועה נראית במלבושי' בלבד המכסים על האברים כו' וגם הנה הלבוש הוא"],[1900640054,"מקיף לכל הגוף ואינו בא בחיתוך והתחלקות לכל אבר כמו שהאברים מתחלקים במזגם לפי חילוק האור שבהן, וגם שהלבוש נחתך ג\"כ לפי מדת האברים יד ורגל אינו רק במדה בלבד, אבל לא שנעשה הלבוש כלי וחומר מוכן לקבל האור [והחיות] ולהיות בטל בכל חלקי' כמו האבר וד\"ל.\n<b>והנמשל</b> מכל זה יובן למשכיל למעלה בבחי' ההשפעה וההשתלשלות דאבי\"ע, דהנה ידוע שג' עולמות בי\"ע הרי יש להן ערך ויחוס זע\"ז מאחר שהן בבחי' השתלשלות כמו שלשלת כו', וכידוע דע\"ס דבריאה מקור הע\"ס דיצי' כי בחי' מל' דבריאה נעשה כתר ליצי' וכ[ן] מל' דיצי' נעשה כתר לעשי', וע\"כ גם העולמו' באין בבחי' השתלשלות מעילה לעילה וכמ\"ש וקרא זה אל זה כו' ותרגומו [ו]מקבלין דין מן דין כו' שמלאכים ונשמות דבריאה הן בחי' מקורים ומשפיעים למלאכים ונשמות דיצי' כידוע דאימא מקננא בכורסייא בבריאה הוא בחי' השגת אלקות מאור אימא דמקננא ומאיר שם בצמצום גדול רק כפי הגבלת השגתם, ויורד האור ומשתלשל מהשגות הללו המוגבלים שנק' מלאכים דבריאה למלאכים דיצי' ששם הוא בחי' המדות כי ז\"א מקנן ביצי' כידוע, ועד\"ז מיצי' לעשי' וכולן יש להן ערך ושייכות זע\"ז וכל תחתון נעשה כמו חומר לצורה לגבי העליון ע\"ד נפש הגלגלי' שגם שהן צורה לחומר הגלגל הרי מקבלים רק מחומר האופנים ושמרים שלהן, ועד\"ז האופנים לגבי החיות כו', ועד\"ז יובן בכלליות בי\"ע שהן שרפים וחיות ואופנים שרפים בבריאה כו' ונמצא שירידת האור והשפע מבריאה ליצי' ומיצי' לעשי' הוא נמשך בבחי' מעב\"ר הנ\"ל שהוא כמו ביטול הכלי לגבי האור שאין הפעולה נק' ע\"ש הכלי והחומר כלל רק ע\"ש האור והחיות, כך אין השפע נק' ע\"ש בחי' היצי' שמקבל מבחי' הבריאה רק ע\"ש בחי' אור הבריאה שהוא מקור היצי' כמו שאין השפע נק' ע\"ש הכלי רק ע\"ש האור כו', וכמ\"כ בירידת השפע מיצי' לעשי' אין השפע נק' ע\"ש העשי' רק ע\"ש היצי' מקור העשי'"],[1900640066,"מאחר שיש ערך ויחוס לכל ההשתלשלות דבי\"ע [בבחי'] עילה ועלול שנק' אור וכלי חומר וצורה, להיות כי כולן בבחי' הגבול יש להן ערך א' רק שמשתלשלים בריבוי ירידת המדריגות ע\"פ ריבוי [מיני] צמצו' מעילה לעילה עד שבחי' ההשפעה הבאה למטה בעוה\"ז החומרי מבחי' מל' דמל' דעשי' בגלגלים וארץ הגשמי בחלקי התהוות דצח\"ם הגשמי' ה\"ז כמו התנועה באצבע שנק' עשי' גשמי' שבה מלובש המחשבה ובמחשבה מאיר השכל עד שאנו אומרים שהאצבע כותב את השכל אבל מפני תכלית ביטול [הכלי] לגבי האור כנ\"ל אין הפעולה נק' ע\"ש הכלי כלל כו' כך כתיב כולם בחכ' עשית עשי' ממש בהתהות דצח\"מ גשמי' שמקבלים ממל' דעשי' שבה מאיר בחי' מדות דיצי' ובמדות דיצי' מאיר בחי' השכל והמחשבה שבבריאה כו', ומפני תכלית הביטול דכלי לגבי האור אין הפעולה נק' רק ע\"ש האור ומקור הראשון והוא בחי' החכ', וזהו בחכ' עשית בחכ' דוקא וכמ\"ש רז\"ל במאמר אחד כו' והוא מאמר דבראשית כידוע.\n<b>אך</b> הנה כ\"ז דוקא בשבת שאז הוא בחי' עליות העולמו' דהיינו שבחי' העשי' עולה ונכלל ביצי' ונעשה רק כמו בחי' כלי ומעבר בעלמא לבחי' היצי', ו[מבחי' היצי'] הוא עיקר המשפיע ופועל פעולתו ע\"י העשי' כמו האור שיפעול ע\"י הכלי כנ\"ל, ועד\"ז אור הבריאה ביצי' כו' ונמצא עיקר גילוי השפע הוא בחי' אור ו\"ק דבריאה שבא בו\"ק דיצי' ועשי' בבחי' מעב\"ר בלבד, ואין השפע נק' ע\"ש היצי' ועשי' רק ע\"ש בחי' ו\"ק דבריאה מטעם הנ\"ל. אבל ביומין דחול הוא בהיפוך גמור שהשפע בא בעולמו' דרך בחי' לבוש דוקא שהוא בחי' הפירוד מן עיקר ומקור המשפיע ואינו רק ע\"ש האור המשפיע כלל, אדרבה דוקא ע\"ש בחי' הלבוש הנפרד כנ\"ל באורך, וכך הוא למעלה [ב]ו' ימי החול שבחי' ו\"ק דיצי' באין בו\"ק דעשי' בבחי' לבוש דהיינו שבחי' ו\"ק דעשי' הוא כמו בחי' לבוש נפרד לגמרי מו\"ק דיצי' בלתי יש ערך ויחוס כלל לו\"ק דיצי' עד שההשפעה נק' ע\"ש בחי' הלבוש שהוא ו\"ק דעשי' בלבד, ובחי' ו\"ק דעשי' מוסתרים בבחי' לבוש ש\"ק דעשי' שהן ע' שרי\"ם כמ\"ש וש\"ק אשים כסותם ושם הוא תכלית השוה הסתר אלקו' עד שנראה להם שהן העושין ופועלים ההמשכה כמ\"ש לי יאורי כו' כחי ועוצם ידי כו' וכמ\"ש אתה אל מסתתר [שהוא שמסתלק] ומסתתר אור האלוקי' דו\"ק דעשי' ולא מאיר"],[1900640077,"רק בחי' מל' שבמל' כו' עד שנק' לבוש נפרד כו'. ועד\"ז מסתלק ומסתתר אור האלוקי' דו\"ק דיצי' מבחי' העשי' וכמ\"כ מסתלק ו\"ק דבריאה מו\"ק דיצי' כו', ונמצא הוא היפוך גמור מבחי' ההשפעה שבבחי' מעב\"ר בשבת [שבשבת] אור ו\"ק דבריאה עיקר המאיר ויצי' ועשי' נכללים וטפלים לגביו, ובחול עיקר הנראה בהשפעה הוא בחי' העשי' ובחי' אור ו\"ק דבריאה מוסתר בתכלית וד\"ל (אך לפי זה עדיין הקושי' הנ\"ל במקומה למה אין נראה שנוי כלל בגידול דצח\"ם כו', והתירוץ מבואר במ\"א שעליית העולמות בשבת אינו אלא בפנימי' שלהם בבחי' האורות ולא בבחי' הכלים, ע\"כ בהשפעה חיצוניו' אין הפרש בין שבת וחול, וכמ\"ש במדרש מגדל צמחים ומוריד גשמי' בשבת כו' ואינו נק' מלאכה כלל, כי עיקר מ\"ש וישבו\"ת מכל מלאכת\"ו הוא בבחי' הפנימיות של האור בכלי כו' וד\"ל). וכל ענין הנ\"ל בהפרש שבין בחי' מעבר לבחי' לבוש הוא הפרש בכללות בין בחי' מל' דאצי' לבי\"ע דבחי' בי\"ע להיותן כולן בבחי' הגבול יש ערך א' להם ויכול להיות בבחי' מעבר כמו בשבת שאו' ג' מיני הב\"ו כו', אבל בחי' מל' דאצי' הוא בחי' אלקות ממש בבחי' א\"ס כי איהו וחיוהי חד כידוע, הרי בי\"ע תמיד בבחי' לבוש נפרד בערך לגבי בחי' המל' [דאצי'] ואינם בבחי' מעביר גם בשבת כי אין ערו\"ך ל\"ך כו', וזהו שמל' דאצי' תמיד בבחי' הסתר והעלם בבי\"ע, ואין הפרש ב[ין] שבת [לחול כלל] רק מה ש[ה]מל' עולה מן ההסתר בשבת ופושט בגדי חול רק מתלבש בלבושים דשבת שהוא אור הבריאה כנ\"ל בפי' לדוד בשנותו כו', אבל גם אור הבריאה נק' לבו\"ש עכ\"פ מטעם הנ\"ל והוא כידוע כמ\"ש אני הוי' לא שניתי קודם הבריאה ואח\"כ שוה אתה הוא כו' משום שנאמר ה' מלך גיאות לבש בבחי' לבוש מל' שהוא ענין בגדי שבת כמאמרז\"ל אפשיטת מלבושהא כו' וד\"ל.\n<b>והנה</b> ע\"פ כל הנ\"ל יובן למשכיל למעלה ג\"כ ענין מ\"ש בע\"ח דהתלמוד בבריאה כו', ולכאורה אין התלמוד מדבר רק בבחי' העשי' דוקא כו'. אך הנה מובן ע\"פ כל הנ\"ל דבי\"ע הוא בבחי' השתלשלות עו\"ע כו' כמו שהאור יפעול כל פעולה ע\"י הכלי כו', וא\"כ גם בענין הלכות שבתורה שלנו דעשי' הגם שהוא בבחי' לבוש"],[1900640088,"גשמי דדצח\"ם דעשי' מ\"מ שרשן ומקורן הוא בעולם היצירה ושרש היצירה הוא בבריאה [כנ\"ל], ונמצא אותו הדין וההלכה שנאמרה כאן בעולם העשי' הרי הדין הזה נאמר ג\"כ בעולם היצי' שהוא בחי' הרוחני' דעולם העשי' דרך כלל, וכמו\"כ שרש אותו הדין בעולם הבריאה שהוא הרוחני' דעולם היצי' ונמצא שרש כל ההלכות שבתלמוד בעולם הבריאה דהיינו שנתלבשה חכמה שבמל' דאצי' בחכ' שבמל' דבריאה והוא ענין לימוד הנשמות בג\"ע דיני ההלכות דתשבע\"פ ממש כמו אם קדם שער לבן לבהרת כו' דקא מפליגי במתיבתא דרקיע כו', וכה\"ג בכל הדינים כמו הלכות טריפות דין נקיבת הוושט דטריפה הנה זה הדין הוא בחי' חכ' שבתורה המתלבשת בענין גשמי דהיינו בהמה הגשמי' שאם ניקב הוושט שלה\nטריפה ולא תוכשר לעלות בסט' דקדושה האלוקי'.\n<b>והנה</b> שרש הבהמה הגשמי' נמשך מבחי' פני שור מהשמאל שבמרכבה דעשי', וא\"כ שרש זה הדין דנקיבת הוושט הוא במרכבה דעשי' בבחי' נקיבת הוושט דשור שבמרכבה כו' דטריפה בבחי' טריפו' בערך רוחניו' דמרכבה כו', ועד\"ז עד רום המעלות גם ביצי' בבחי' מרכבה דיצי' כו' עד בחי' פני שור שבבריאה בחי' [נקיבת] הוושט שלו טריפה בערך רוחניו' דעולם הבריאה, ואחר שבי\"ע כולן הן בבחי' הגבול והתכלית שהוא בא בבחי' השתל' עו\"ע מרוחני' לגשמי' שהרי באמת אין הפרש בין בחי' עשי' לבריאה שניהם רק בחי' לבוש להשראת חכ' האלקי' דאצי' ודוקא בבחי' לבוש ולא בבחי' כלי שבטל לגבי האור מפני שיש ערך ב[י]ניהם כו', אך בחי' כל[י] חכ' שבמל' דעשי' שמלובש בדברים גשמיים הוא בחי' כלי ומעבר לבחי' חכ' שבמל' דיצי', וכמ\"כ בחי' כלי חכ' שבמל' דיצי' בחי' כלי ומעבר לחכ' שבמל' דבריאה מפני שיש ערך ב[י]ניהם כו', אבל כללות חכ' דתו' שמלובש בבי\"ע הוא רק בחי' לבוש נפרד שאינו מערך כלל וכלל לגבי אור האלקי' עצמו בחי' חכ' שבמל' דאצי' כמו נקיבת הוושט שהוא כלי גם להתלבשות חכ' דמל' דבריאה, אבל בחי' כלי דנקיבת הוושט דבחי' שור דבריאה אינו בחי' כלי דחכ' שבתו' שבמל' דאצי' רק בחי' לבוש אעפ\"י שנתלבשה חכ' שבמל' דאצי' בחכ' דמל' דבריאה ונק' חכ' תתאה בחי' חכ' שבא בהתלבשות בעולמות בע\"ג מ\"מ אין לחכ' דבריאה ערך כלל אלי', יותר משאין ערך בחי' המספר לגבי למעלה מן המספר או כערך הגשמי' לגבי הרוחני' וכמו ערך היצי' לגבי הבריאה וכה\"ג, לפי שבחי' בע\"ג אין ערך כערך לגבי בחי' א\"ס גם שהוא במל' סופא דכל דרגין וכידוע, וזהו שאמר בע\"ח שהתלמוד בבריאה פי' בחי' חכ'"],[1900640099,"שבמל' דבריאה הוא שרש התלמוד שלנו והוא בחי' לבוש לגבי חכ' שבתורה שבמל' דאצי' שמשם מאיר להשגות הנשמות שבג\"ע דבריאה הנק' זיו השכינה שמאיר לנשמות בבחי' לבוש דוקא מטעם הנ\"ל וד\"ל. אך הנה גם בחי' הלבוש אע\"פ שהוא בבחי' נפרד מ\"מ [הרי] הלבוש נחתך במדה לפי חיתוך האברים [כ]נ\"ל, וא\"כ גם בחי' חכ' שבמל' דאצי' הוא [על] אותו האופן שבחכ' שבמל' דבריאה, כמו נקיבת הוושט לפי אופני פרטיו בחכ' דבריאה גם הוא בכל אופני פרטיו גם בבחי' האצי', רק שבאצי' הוא בבחי' אלקו' [ממש] דהיינו בבחי' שמות וצירופים דכלים דאורות עליונים שנק' שם בחי' וושט דשור דאצי' וכידוע, וכמ\"ש בר\"מ שמבחי' אברים [ד]ז\"א הוא מקור כל המשכות לבי\"ע כידוע [ב]ענין המאמר תלת שליטין אינון לעילא מוחא ולבא וכבדא כמ\"ש על הכסא דמות כמראה אדם, ויש [בו] ודאי ג\"כ בחי' בהמות וחיות דאצי' כמו שור וארי' וכיוצא וגם בחי' צומח ודומם כתפוח en. ואבן וכה\"ג, מאחר שנק' עולם שכולל דצח\"ם והכל בבחי' האצי' כידוע וד\"ל.\n<b>ולפ\"ז</b> יובן ג\"כ שכל ההלכות שמדברים כאן בבחי' אדם התלויות ברמ\"ח אברים ישנם ג\"כ למעלה בבחי' אברים דז\"א כמו חסד דרועא ימינא ותפילין בראש וציצית בכנפי כסותו, כמ\"ש רז\"ל הקב\"ה מניח תפלין ומתעטף בציצית כו', וכן בענין ההעדר והפגם ע\"י שס\"ה ל\"ת וכמ\"ש במ\"א. [ו]מכ\"ז יובן איך שיש [שם] ג\"כ כל הלכות נגעים גם בעולם האצי' כמו פלוגתא דשער לבן קודם כו' דקודב\"ה אומר כו', דהנה ידוע שבחי' נגע למטה הוא בחי' קליפה ונק' נגעי בנ\"א לפי שהנגע בלשון תרגום סגירו כתרגום צרעת סגירותא לכן אמר בזוהר נגע צרעת סגירותא דנהורא עילאה כו', והענין מבואר במ\"א שענין הבהרת הוא מורה בחי' הסתלקות חיות הרוחני שבדם הוא הנפש במקום ההוא ע\"כ מראהו לבן, וידוע"],[1900640110,"דאדם הוא בצלם אלקים ע\"כ במקום ההוא נסתלק אור וחיות האלקי' שבאבר ההוא בנפשו האלקי' והיינו ענין סגירותא שנסגר הכלי שהוא האבר בלי יכנס בו האור והחיות שבדם הוא הנפש כו' מפני שכבר המשיך החיות לקליפות ואין בחי' הקדושה שורה במקום ההוא במקום טומאה וע\"כ נק' הנגע סגירו דנהורא עילאה שהוא בחי' אור אבא כי בחכ' שבנפש האלקי שורה בחי' אלקי' והדם הוא הנפש הוא מבחי' גבורות דאימא שנמשך בשס\"ה גידין להחיות האברים כידוע בענין אד\"ם א' דם בחי' אל\"ף דחכמה שמלובש בבינה הוא חיות הדם כו' וכשיש קילקול בדמים שהוא חיות הנפש באברים אזי מסתלק אור החכ' במקום קילקול דם הזה, en. וזהו שנק' סגירו דנהורא עילאה כו' כמ\"ש במ\"א וד\"ל.\n<b>וכמ\"כ</b> יובן למעלה דכמו שלמטה נק' נגעי בנ\"א בחי' יניקה לקליפות למעלה בעולמו' הרוחני' ג\"כ בחי' העדר קבלת הכלי לבחי' האור וחיות כאשר י[וסגר] איזה כלי בנ[ב]רא מלקבל אור וחיות המהווה ומחי' אותם נק' סגירותא כו' ונק' נגעי בנ\"א למעלה כידוע דאנשים מט\"ט וסנד\"ל ובני אדם אנפי זוטרי וכמ\"ש ופני אדם לארבעתן כו', וכך יובן למעלה מעלה בעולם היצי' ובעולם הבריאה יש שם ג\"כ כל דיני הנגעים בבחי' הרוחני' דאדם שביצי' ובריאה אך בחי' אדם דאצי' ג\"כ יש בו בחי' נגע כמ\"ש אדם כי יהי' בעור בשרו כו', אך בבחי' האצי' הוא בחי' העדר קבלת הכלי לאורו' העליונים דבינה דאצי' שהוא בבחי' דם הוא הנפש המתפשט בבחי' אברים דז\"א שנק' אד\"ם א' דם מבחי' אבא ואימא כנ\"ל, והוא בחי' שם אהי' בריבוע כו' בגי' דם, וע\"כ נק' הבינה אלקי' חיים ואור החכ' נק' חי\"י החיים שהוא מקור החיים דדם דבינה כו', ובחי' הסתלקות אור באבר א' דז\"א נק' סגירו דנהורא עילאה באדם דאצי' דהיינו באיזה שם [ו]צירוף דכלים דז\"א כו' שנסתלק משם בחי' השפעת אור אבא נק' בחי' נגעי דאדם דלעילא והיינו אדם כי יהי' בעור בשרו כו', והוא בא מחמת סיבת יניקת החיצונים בבי\"ע מבחי' אחוריים וחצוניות הכלים דז\"א שנק' עור בשרו כו' ע\"כ [בה]סתלק אור אבא באותו האבר והכלי ואין"],[1900640121,"בחי' חכ' דאצי' מתפשט שם, והטעם הוא כמ\"ש במ\"א שבחי' החכ' הוא כ\"ח מ\"ה בחי' הביטול האמיתי והוא ראשית הכלי להשראת האור כו' דא\"ס כו', אבל כשקליפו' מקבלים שהן בחי' יש ודבר מה היפוך הביטול כו' כמ\"ש א' זלע\"ז עשה האלקי' ע\"כ ממילא מסתלק אור כח מ\"ה דחכ' משם כי הביטול והתפשטות הישות הם ב' הפכיים ממש כו', וענין ראיית הכהן ששרשו מחסדי' דאבא לנגע הוא בחי' בירור דחכ' ע\"כ תלוי במראה עיני הכהן כו' ואם צריכה הסגר ז' ימים, ו[כ]כל משפטי דיני הנגעים למטה כך הוא למעלה ג\"כ בבחי' האצי' עד\"ז ממש רק שבבי\"ע הוא מדבר בבחי' נגעי בנ\"א שהן בבחי' גבול ויניקות הקליפות מהם הוא בחי' רע גמור אבל באצי' הוא בבחי' אור וחיות אלוקי ממש שבכלים ושמות עליונים כנ\"ל, וענין העדר האור בכלי ושם העליון אינו בחי' יניקה לרע גמור רק שמזה מסתעף שרש ומקור להיות השפעה לחצונים בבי\"ע כמ\"ש בע\"ח דמעמד הקליפות הוא בבי\"ע אבל באצי' נאמר לא יגורך רע כו' וד\"ל.\n<b>ולפ\"ז</b> יובן ג\"כ שא\"א לומר שבחי' חכ' דבריאה בדין זה דבהרת הוא בחי' כלי לחכ' שבדין בהרת שבבחי' האצי' מאחר שאין ערוך ב[י]ניהם כלל כנ\"ל, ובפרט להיות כמו בחי' כלי לאור ממש כמו שדין בהרת שביצי' הוא בחי' כלי לדין בהרת שבבריאה כי מבחי' אור דחכ' דבריאה נעשה מקור לחכ' דיצי' בדרך השתלשלות עו\"ע כנ\"ל, משא\"כ מאצי' לבריאה שאין ערוך ב[י]ניהם כלל רק ההשפעה באה מאצי' לבריאה בבחי' לבוש נפרד וכמ\"ש עוט\"ה או\"ר כשלמ\"ה בחי' אור דחכ' דתורה דאצי' נמשך בבחי' לבוש כשלמה לנשמות שבג\"ע דבריאה כו', וכך בכל דיני הלכות שבתו' שנמשכים מאצי' לבריאה כו', ובכ\"ז יובן במה שמצינו כמה הלכות בגמ' שא\"א שיהי' במציאות הטבע כלל אך אמרי' דרוש וקבל שכר כידוע, וזהו פלא לכאורה אם א\"א שיבוא הדבר במציאות [הטבע] מאי דרוש איכא, הלא אין חכ' שבתו' רק בבחי' אור וכלי דוקא, אך הענין הוא דבאמת מדבר זה יש מופת וראי' חזקה לענין הנ\"ל דבחי' חכ' שבבי\"ע אינה בחי' כלי ומעבר לבחי' חכ' דתו' דאצי' אלא רק בחי' לבוש נפרד, שאם הי' בבחי' כלי גמור הרי הי'"],[1900640132,"מהראוי שיהי' הדין שכיח ויבא במציאות בבחי' כלי גמור, מאחר שיש לדין זה שרש בבחי' חכ' דאצי' בהכרח שימצא בחי' כלי לזה בבחי' השתלשלות אור וכלי כו', כמו שבהכרח להמצא בחי' כלי לה[ש]ראת אור חכ' דבריאה ביצי' ודיצי' בעשי', אלא ודאי מוכרח מזה לומר דבחי' חכ' דבי\"ע אינו רק בחי' לבוש נפרד שאינו מערך דערך לח\"ע כו', רק מפני שגם בחי' הלבוש הוא בא בחיתוך מדה לפי מדת האברים כנ\"ל, ע\"כ בהכרח שלפי אופן הדיני' וההלכות דתו' דבריאה כך הוא אופן הדינין וההלכות דתו' דאצי' כנ\"ל, וא\"כ לפי זה אין צ\"ל הכרח שימצא בחי' כלי גמור לדרוש הדין והלכות דתורה דאצי' בבי\"ע מאחר שאינו אלא בחי' לבוש [נפרד], ומפני שגם הלבוש בא במדה ע\"כ א\"צ רק שיהי' בחי' השגה בשכל לאותו הדין וההלכה דאצי' אעפ\"י שלא ימצא במציאות כלי כדי שיהי' בחי' לבוש [לבד בבחי' ח\"ע]. וזהו שא[רז\"ל] דרוש וקבל שכר פי' שא\"א שיבא הדבר במציאות דרוש אותו בבחי' השגה שכלית שלו, דהיינו אם הי' אפשר להיות במציאו' ענין כך וכך הי' הדין כך וכך אעפ\"י שלא יארע דבר זה לעולם דרוש וקבל שכר כאילו הייתה דורש בדבר שהי' בא בבחי' כלי גמור, כי קיבול השכר הוא בבחי' האצי' שאין בי\"ע בחי' כלי לגבי' כו', רק בחי' לבוש בלבד ובחי' לבוש א\"צ שיהי' בבחי' כלי גמור רק לפי אופן המדה בלבד דהיינו כדי שיוכל אור ח\"ע דאצי' להתלבש בו בלבד כו' ומטעם הנ\"ל וד\"ל.\n<b>והנה</b> מה שאמר דהתלמוד בבריאה דהיינו בחי' חכמה של בע\"ג דצח\"ם דבי\"ע בכללות כו' יש בזה ב' מדריגות עיון וגרסא, דהנה ב' מצות הן מצות עיון במחשבה כמ\"ש והגית בו כו' ומצות קריאה בדיבור [כמ\"ש] ודברת בם כו' ושניהם בתושב\"כ, וכמ\"כ בתור' שבע\"פ שנק' תלמוד יש [ג\"כ] ב' מדריגות עיון וגירסא, והענין הוא כידוע שהגירסא הוא לימוד המשניות וההלכות הפסוקות בלי פלפול כלל וכלל רק הלכה ברורה בטעמה דוקא ולא כדין המשנה שאינו אלא דין והלכה כך וכך כשר כך וכך פסול בלא נתינת טעם לדבר כלל, רק פסקן של דברים בלבד והוא רק בחי' המדות כשר ופסול חייב זכאי וכו', וזהו שאומר המשנה ביצי' פי' בבחי' המדות דיצי', אבל התלמוד בבריאה פי' בבחי' הטעם והמוחין למדות דהיינו [כל] בחי' טעמי ההלכות למה כך כשר וכך פסול וכמו שמבואר בתלמוד טעם דין המשנה מ\"ט דר' פלוני אמר קרא כו', אך אעפ\"י שהוא בבחי' טעמים ששרשו בבריאה מ\"מ אין זה רק בחי' גרסא לגרוס ההלכות פסוקות ברורות בטעמיהן וא\"צ בירור כלל כי כבר הובררו כל הצורך (וכמו הזוגו' לפני ב\"ש וב\"ה"],[1900640143,"שלא הי' אצלם פלפול ע\"ד הוי' דאביי ורבא כו'), אבל מדריגה הב' הוא בחי' העיון בפלפול שהוא עיקר התלמוד שהוא בחכ' שבמל' דבריאה ועיקר ענין הפלפול הוא להקשות קושיות וסתירות רבות בין ההלכות ולתרץ ולהעמיד כ\"א בטעמו כמו ל\"ק כו' [כמו ר\"ל דמקשי] עד דממילא רווחא שמעתתא ברוב הפלפול ויצאו דינים חדשים לגמרי עי\"ז כידוע, אך הנה יש להבין מה שאמרו דכל מה שעתיד תלמיד ותיק לחדש ניתן למשה כו' מאין יש כח בתלמיד לחדש ואם ניתן זה כבר למשה למה לא נתפרש בתורה או בקבלה כו' הלא הל\"מ שבקבלה מעט הם כו', אבל הענין הוא דעיקר הפלפול הוא רק המצאת טעם וסברא חדשה באמיתי' טעם ההלכה שהי' טעם האמיתי' נעלם מתחילה מפני קושיות רבות המסתירות ומעלימות אמיתי' טעם ההלכה, [ומפני] הערבוביא [הגדולה] בסתירות רבות בין ההלכות עד שאחר ריבוי הפלפול נת[חדש] והוציאו לאור אמיתי' הטעם, ובהמצאות סברות חדשות לתרץ כל קושי' וסתירה, ויש כאן ב' דברים הא' בירור ההלכות שהוא להבדיל בין רע לטוב להסיר כל סיג ובלבול הקושי' ולהעמיד כל א' על שרשו, וה\"ז כמו סלסול בשערות כמ\"ש במ\"א בפי' סלסל\"ה כו', והב' המצאת הטעם החדש שממנו נולדו דינין חדשים לגמרי ותחילה הי' המצאת הטעם החדש [ותולדות הדינין החדשים] בהעלם מפני הסתר הקושיא ואח\"כ יצא לאור en.כנ\"ל, והיינו ענין המאמר דבחכ' אתברירו שיש כאן ב' דברים הנ\"ל.\n<b>והנה</b> לכאורה יש להבין בענין המצאת הטעם החדש, ותולדות הדינין החדשים מה יתרון מעלתם ומדריגתם משאר הדינים וההלכות הפסוקי' בטעמיהן בלי פלפול כלל שנק' הלכה ברורה כבר כנ\"ל שנק' גרסא, הלא גם הם דינים וההלכות כמוהם ומה הפרש יש בין עיון לגירסא, אך הענין הוא משום דבחי' כח החכ' המ[ברר] בבחי' פלפול הוא יותר נעלה בשרשו מבחי' חכ' שבהלכות הברורות בטעמיהן גם שהן ג\"כ מבחי' חכ' דמל' דבריא', אבל שרש בחי' חכ' המ[ברר] בבחי' פלפול [ו]להוציא דין חדש הוא בבחי' אצי' שבבריאה להיות ידוע שאין כח לברר רק בחי' דכר ולא בחי' נוקבא כו', וכמ\"כ אין כח הבירור בפלפול"],[1900640153,"רק בבחי' חכ' דאצי' שמאיר בחכ' דבריאה כי כל מברר צריך שיהי' כחו חזק מן המתברר, ע\"כ אין בכח הנוקבא לברר אלא כח הדכר שהוא חזק מכח הנוקבא ע\"כ מ\"ד דדכורא מברר למ\"ן דנוקבא כידוע, וכמ\"כ כאן בבירור ההלכות להבדיל בין פנימי' וחיצוני' ולהוליד חדשות כו' ה\"ז כמו בחי' מ\"ד שמברר למ\"ן, כי הלכות דתו' דבריאה היא בחי' נוקבא והבירור הוא בבחי' כח מ\"ה דדכורא שהוא אור האצי' בבריאה, וע\"כ יש בכחו להסיר כל קושיא ולהעמיד כל דבר על מכונו ולהוליד סברות חדשות, ואע\"פ שאותן ההלכות הנולדים מצד כח הסברא והפלפול הן כמו שאר ההלכות מ\"מ כח החכ' שהולידם מחדש יותר נעלה מבחי' החכ' שבטעמי שאר ההלכות, כי הרי הי' טעם החדש בהעלם תחילה וע\"י כח מ\"ה דאצי' דוקא יצא לאור מתוך החושך וההעלם משום דכל קושיא מסט' דקליפו' המסתיר ומצמצם כו', וכאשר אור ה[מ]אצי' מאיר שהוא בחי' ביטול [בתכלית] ההפשט[ה] מבחי' יש כו' כידוע אז לא יחשיך ויסתיר חושך דקליפו' כלל ויצא לאור כל העלם הטעם האמיתי שהוא בתכלית האמיתי נקודת המושכל לתכלית אמיתתו כו' וכמ\"ש גם חושך לא יחשיך כו', ועיקר הטעם כנ\"ל דכח מ\"ה דאצי' דוקא הוא המברר להבדיל ולהוציא אור מתוך החושך כו' וד\"ל. ובזה יובן מה שאמר כל מה שתלמיד ותיק עתיד לחדש בפלפול דוקא שהוא מדריגה [הנ\"ל] שנק' עיון להוציא דין חדש בבחי' בירורי נוג\"ה שלא יסתירו הקושיא כלל והוא להוציא מן ההסתר והעלם הקליפות [לאור] כו' הכל ניתן למשה שהוא בחי' יסוד אבא מקור כל הבירורים דבחכ' אתברירו וכמ\"ש בזהר דאתפשטותא דמשה בכל דרא [ודרא] בכל חכמי [הדור] ועיני העדה להיות להם כח מ\"ה זה בנפשם בבחי' הבירורי' דנוג\"ה בבחי' עיון ופלפול בתורה לחדש דינים רבים עפ\"י המצא' סברות וטעמי' חדשים כו', והוא בחי' הארת חכ' דאצי' בחכ' דבריאה שרש חכמה דעיני העדה להיות להם כח זה ג\"כ לברר וע\"כ אמר דכבר הי' בשרש ומקור החכ' דבריאה כל מה שתלמיד en. ותיק ששרשו מחכ' דבריאה כו' וד\"ל.\n<b>ובזה</b> הנה יובן ג\"כ מ\"ש בזוהר על מארי תלמוד דאינון מארי קבלה, וזה פלא לכאורה דהא קבלה בבחי' האצי' והתלמוד בבריאה ומשנה ביצי' כו', וא\"כ זה סותר למ\"ש דהתלמוד בבריאה אחר שהתלמוד הוא בבחי' קבלה כו', אך הענין הוא דודאי התלמוד בבריאה והקבלה באצי', אמנם הנה יש ב' מדריגות באצי' הא'"],[1900640160,"בחי' האצי' כמו שהוא במקומה דוקא והוא בחי' סודות הקבלה שנמשכים לנשמות בג\"ע דבריאה שנק' זיו השכינה ממש כידוע, והוא ענין השגות פנימי' כל דינין והלכות דתו' כמו שהן בבחי' האצילות רק מאירים בבריאה דרך בחי' לבוש בלבד [כנ\"ל ב]ענין נקיבת הוושט וכיוצא, ונמצא לא הורד אור זה מכמו שהוא בבחי' האצי' ממש והן הנק' מארי קבלה, אבל מ\"ש דמארי תלמוד אינון מארי קבלה אין הכונה כמו מארי קבלה ממש אלא שהן עומדים לקבל ג\"כ הארת אור חכ' דאצי' אבל לא כמו שהוא באצי' ממש רק כמו שהאצילו' יורדת ונשפלת בבריאה בשינוי מקום ובמעלה שלא כמו שהיא במקום מעלתה ומדריגתה העצמי' כו', והיינו בעלי הפלפול שיש להם הארה לכח מ\"ה שבנפשם מבחי' כח מ\"ה דאצילו' לברר בירורי נוג\"ה לברר הטוב מן הרע כו' כנ\"ל, ולכך אמר דמארי תלמוד בבחי' עיון ופלפול דוקא [אינון] כמו מארי קבלה במדריגת קבלת אור האצילו' אבל לא כמוהם ממש, גם שמארי קבלה מקבלים רק ע\"י לבוש אבל הוא אור האצילו' עצמו כנ\"ל, משא\"כ מארי תלמוד שאינם מקבלים רק בחי' האצילו' המוסתר ונעלם בחכ' דבריאה כו' וד\"ל.\n<b>ובכל</b> זה יובן ענין [א]זהרת שתיית יין ושכר לאהרן ובניו כמ\"ש יין ושכר אל תשת בבואכם אל אוהל מועד כו' ומסיים הפרשה במ\"ש להבדיל בין [ה]טמא לטהור כו' ויש להבין מה שייכות יש לזה עם זה כו'. אך הענין יובן עפ\"י הנ\"ל דעיקר בחי' הבירורים דנוג\"ה להבדיל בין טמא לטהור כו' הוא בבחי' החכ' כח מ\"ה דחכ' דאצילו' בבריאה, ושרש הכהנים הוא מבחי' חסד דאור אב\"א כידוע בענין כה\"ג נוטל חלק בראש כו', ולזה הטעם הכהנים המה המורים כל הוראת איסור והיתר לישראל כמ\"ש יורו משפטיך ליעקב כו' והוא להבדיל בין [ה]טמא כו', לפי שבחכ' אתברירו דוקא וידוע דחכ' הוא בחי' שמן בחשאי כמ\"ש כשמן הטוב כו' לריח שמניך כו', והיינו שנמש[ח]ו הכהנים בשמן המשחה דוקא כידוע,"],[1900640167,"אבל יין הוא בחי' בינה דמינה דינין מתערין ולהיות כי יין הוא המשמח בשמחה ברשפי אש התלהבות בינה לבא ומסתעף מ[ז]ה בחי' גבורו' קשות דנוג\"ה פסולת הגבורו' דשמחה דבינה, ולזה הטעם א\"א שיהי' שיהי' בחי' הבירורים דנוג\"ה להבדיל בין כו' לבער סיגי' דפסול' הגבורות קשות דנוג\"ה אחר שמבחי' בינה דינין מתערין כו', וממנה נמשך שרש כח התהוותם והתפשטותם למטה, ומזה הטעם אין כח במל' לברר נוג\"ה משום דגבורו' [קשות] דנוג\"ה מקבלים מן המל' כמ\"ש מלך אלקי' על גוים כו' משום דעיקר בנין המל' מהגבורו', ולזה [הטעם] הוזהרו בני אהרן בשתיית יין ושכר דוקא שלא יסתעפו מהם יניקות גבורו' קשות דנוגה שנק' אש זרה ולא יוכלו להורות ולהבדיל כלל בין טמא לטהור וע\"כ שיכור אסור להורות כידוע וד\"ל, וזה הי' ענין [חטא] נדב ואביהוא שנכנסו שתויי יין לאה\"מ כי בחי' אש זרה דגבורו' דנוג\"ה יש לו אחיזה ויניקה בבחי' יין דבינה הגם שהוא יין המשמח שהוא בחי' עוה\"ב לאחר הבירור כידוע דעולם הבא בבינה ונק' עולם החירות ונק' יין המשומר ממגע נכרי שאין שם שליטה לחיצוני' כלל וכלל, אבל עכשיו קודם הבירור יש עדיין יניקה ואחיזה לחיצוני' מפני פסולת כוחות הדין שיש גם ביין המשמח דבינה, וכמ\"ש [בינה] מינה דינין מתערין כו' והוא ענין שחוה סחט\"ה אשכול של ענבים כו' בחי' ענבימו ענבי רוש אשכלו' מרורות כו' כמ\"ש במ\"א וד\"ל, וזהו שאמר בהקריבם אש זרה כו' ולפי שאין ביכולתם לברר אש זרה זה שמסתעף מיין ושכר ומקבל משם, וע\"כ סיים הפרשה להבדיל בין טמא לטהור כו' כי זהו עיקר טעם האזהרה לכהנים על שתיית היין והשכר כנ\"ל וד\"ל."],[1900640174,"<b>והנה</b> מעתה יש להבין בענין ב' מדריגות הנ\"ל עיון וגירסא עוד ענין א' והוא להיות שאנו רואים בעיקר מצות עיון הנ\"ל הוא במחשבה והגיון דוקא והוא ענין העמקת המחשבה מאד בתכלית ההפשטה של מחשבה מכל דבר, שהוא בחי' העלאה למעלה שהרי הוא בחי' עליות והתקשרות כל כח מחשבתו ושכלו בחכמה שבתורה, והוא בחי' העלאת מ\"ן מחכ' האנושי' שבנפשו החיוני' כמ\"ש במ\"א (מלבד ענין הבירור שיש בכח החכ' הנ\"ל), אבל הגירסא מצותו בדיבור בפה דוקא ולא יצא י\"ח במחשבה כידוע במצות קריאת התורה כמ\"ש ודברת בם דהרהור לא עביד מידי כו', לפי שבחי' הקריאה בתורה הוא בחי' המשכת מ\"ד מלמעלה למטה להיות שהקב\"ה יושב ושונה כנגדו כו' שהוא בחי' המשכת מ\"ד מאור אבא בז\"א שנק' הקדב\"ה כמ\"ש במ\"א וד\"ל. אך הנה יש להבין בענין זה למה אין בכח המחשבה להמשיך בחי' המשכת מ\"ד כמו ע\"י הדיבור (מאחר שהקדב\"ה יושב ושונה כו' שבוודאי אין דיבורו ומחשבתו כדיבורינו ומחשבתינו ע\"ד שנאמר דהקריאה אליו ית' הוא בדיבור דוקא ולא במח' שאין זה שייך לאמר רק בקריאת אדם לזולתו שלא יכול לקרותו במחשבתו רק בדיבור אבל אל אור האלקי גם במח' יוכל לקרותו כמו בדיבור שהרי אין לדיבורינו ומחשבתינו ערוך לדיבוריו ומחשבותיו ית' כמ\"ש כי לא מחשבותי מחשבותיכם וכו' (והלא גם המלאכים שנא' בהם וקרא זא\"ז קריאה זו כמו בחי' מחשבה שלנו כי דיבור שבעליון נעשה מחשבה לתחתון), ואם מפני שהקדב\"ה יושב וקורא בבחי' דיבור שהוא בחי' המשכה היא גופא קשי' למה בעיון אין הקדב\"ה יושב כו'. ועוד יש להבין ענין א' והוא במ\"ש בזהר דמ\"ש ודבר דב\"ר שעיקר חילול שבת הוא בדיבור והרהור לא עביד מידי כו', וכמ\"כ במילין דקדושה דוקא כדאפיק מפומא כו' ואז כל קדושי דמלכא עילאה מתעטרין כו' למה דוקא בדיבור ולא במחשבה ולמה כל en. קדושי דמלכא עילאה מתעטרין בדיבור. en.\n<b>אך</b> הנה יש להקדים הקדמה אחת הידוע בענין המאמר דאבא יסד ברתא שצירופי אותיו' הדיבור נמשך מכח אור החכמה דוקא כמ\"ש מצרף לחכמה"],[1900640180,"וכתיב ה' בחכ' יסד ארץ כידוע ומבואר במ\"א. ויש להבין לכאורה למה צירופי אותיו' הדיבור נמשך מכח החכ' ולא צירופי אותיו' המחשבה שהרי [ידוע ד]צירופי אותיו' המחשבה נמשך מבחי' אחוריים דבינה בלבד שנק' מל' דתבונה כו', וכן ה\"ג מנצפ\"ך דאימא כמ\"ש במ\"א. אך הענין הוא משום דשרש כח אותיו' הדיבור נמשך ממקור החכ' וכמ\"ש לנפש חי' ות\"א לרוח ממללא וחי' הוא בחי' פנימי' חכ' ומקורה דהיינו בחי' עצמיות כח ההשכלה שלמעלה מבחי' השגה דבינה [כו' וע\"כ] הארת אור זה מתפשט למטה מטה דוקא והוא בצירופי אותיות הדיבור לפי שנעוץ תחילתן בסופן וסופן בתחילתן כמ\"ש במ\"א, ובזה יש יתרון מעלה לבחי' הדיבור על המחשבה להיות שרש הדיבור בפנימיות אור אב\"א ע\"כ אור אבא דוקא יסד ברתא בצירופי' שוני' דוקא כו', וכמו התינוק שא\"י לצרף אותיות הדיבור מפני שלא נשלם בו הארת אור החכ' עדיין שנק' נפש חי' כו' וד\"ל, וזהו פי' כל המאמרים הנ\"ל דכל בחי' קדושי דמלכא עילאה מתעטרין דוקא בדיבור פי' קדושי הוא בחי' אורו' ומקיפי' שנק' קדושים מובדלים בערך גילוי אור במקבל כו', ומלכא עילאה הוא בחי' אור אב\"א כידוע, והכונה שכל בחי' המקיפי' דאבא מתעטרים בבחי' הדיבור דוקא מטעם הנ\"ל וד\"ל. וגם מזה הטעם אמר בזוהר דעיקר חילול שבת בדיבור ובהרהור לא עביד מידי, כי כל המשכת קדושה עליונה דאור אבא שהוא בחי' השבת שנק' קודש כמ\"ש כי קודש היא כו' וכמ\"ש במ\"א הכל תלוי בדיבור שממשיך מפנימי' אור אב\"א כנ\"ל, וע\"כ כשמחלל שבת בדיבור של חול מחלל לבחי' קודש העליון דאור אבא והרהור של חול לא עביד חילול בקד\"ש דחכ' מטעם הנ\"ל וד\"ל, והיינו ג\"כ ענין הנ\"ל בבחי' המשכת מ\"ד דחכ' בקריאת התורה ע\"י הדיבור דוקא ואין בכח המחשבה להמשיך כו' מטעם ששרש הדיבור בחכמה ע\"כ ע\"י הדיבור נמשך מקור המשכת מ\"ד מפנימי' החכמה ולא ע\"י העיון במחשבה שאינו רק בבחי' השגה כו' (ולפי זה הרי מצות גירסא בהלכות פסוקות"],[1900640186,"בלי פלפול גבוה [מ]מצות עיון להיות' במחשבה כו', ולמעלה מבואר דבחי' העיון למעלה מבחי' הגירסא להיות[ו] בחי' כח המברר כו' עד שהוא בבחי' הקבלה שבאצילו' כו'. הענין יובן ע\"פ הנ\"ל דמצד הבירור שמתברר ע\"י [העיון], מעלת העיון גבוה על הגירסא, אבל מצד בחי' עצם העיון שהוא ע\"י המחשבה הוא רק בחי' העלאה, וע\"י הדיבור דגירסא הוא בחי' המשכה דחכ' למעלה גם מבחי' הבירור דחכ' כי כל מעלת הבירור דחכ' הוא מצד ההארה מבחי' ח\"ע דאצילות ואינו רק הארה בעלמא לגבי המשכת אור דח\"ע בדיבור מטעם הנ\"ל וד\"ל), (ובמק\"א מבואר במעלת העיון על הגירסא באופן אחר וכמ\"ש במ\"א).\n<b>והנה</b> כתיב השמיעני את קולך כי קולך כו' מזה משמע שיש גם בבחי' הקריאה בדיבור בחי' העלאה דוקא כמ\"ש השמיעני את קולך וכל שמיעה לקול הוא עלית הקול ממטה למעלה, והענין הוא כי הבל הדיבור הגשמי מורכב מאמ\"ר גשמית שנעשה מכח הבל הלב שהוא מאכילה ושתי' גשמי' עולה למעלה [ב]בחי' העלאת מ\"ן בקול דתורה, והרי נתעלה בחי' נוג\"ה ש[ב]אכילה ושתי' בכח הקול הזה למעלה להיות בחי' כלי לשכון בו אור האלקי' בהמשכת מ\"ד דחכ' שנמשך מדיבור דוקא מטעם הנ\"ל, ונמצא יש בדיבור בחי' העלאת מצד עצם קול הדיבור ובחי' המשכה דח\"ע דתורה בצירופי אותיות הדיבור, וה\"ז עד\"מ השליח שמביא דבר מה לשולחו מלמ[ט]ה וחוזר הוא ונעשה שליח להחזיר הדבר מלמעלה למטה שאין זה רק כמו אמצעי בין העליון והתחתון להביא ולהעלות מתחתון אל העליון ולהוריד ולהמשיך מן העליון אל התחתון וכך הוא בבחי' הדיבור שהוא בחי' שליח להביא ולהעלות מלמטה למעלה בבחי' העלאת מ\"ן והוא עצמו המוריד והממשיך בחי' המשכת מ\"ד ממקור ח\"ע למטה כנ\"ל בענין הצרופי' דדיבור (ולהיות[ו] כלול מבחי' העלאה והמשכה יחד נק' רוח ממללא בחי' רוח כולל חו\"ג כמ\"ש במ\"א וד\"ל).\n<b>ובכל</b> הנ\"ל מובן מ\"ש בע\"ח דמבחי' הבל הדיבור דד\"ת שלמדו נשמות הצדיקי' בעוה\"ז דוקא נעשה בחי' היכל ומקיף גשמי לנשמות הצדיקים בג\"ע"],[1900640192,"העליון (והיינו ענין המאמר דאורייתא היכלא עילאה דקודב\"ה שהוא בחי' היכלות דאבא וכמאמרז\"ל א\"ת בניך אלא בוניך שעוסקים בבניינו ש\"ע כו'), דהנה מה שמבואר למעלה בבחי' המשכת ח\"ע בדיבור דד\"ת היינו בחי' המשכת אור חכ' דאצי' שרש כל האצילו' שבא האור בירידת השתלשלות בחכ' שבמל' דבריאה שרש התלמוד כנ\"ל, ומכריזין בג\"ע אשרי מי שבא לכאן ותלמודו בידו שלמד בעוה\"ז שבדיבורו שדבר בד\"ת [ישכון] אור ח\"ע דאצילו', ואמנם דוקא מה שלמד בעוה\"ז בקול הבא מבחי' בירורי נוג\"ה דוקא שמבחי' בירורים הללו נעשה בחי' היכל ומקיף לנשמה להיות שהבל הקול הגשמי נמשל לבחי' דומ\"ם כמ\"ש בס\"י ה' אבנים בונות ק\"ך בתים (והיינו א\"ת בניך אלא בוניך), והן אותיו' התורה שנאמרו בהבל קול גשמי שנבנה מהם בנין היכל מקיף על הנשמה בג\"ע כדמיון האדם שיושב בהיכל שההיכל מקיפו מכל צד, ובזאת יתרון מעלת ההיכל על האדם שאין ההיכל צריך לאדם והאדם צריך לו כו', להיות בחי' מקיף ושומר לפי ששרש ההיכל מבחי' אור מקיף דחכ' שהוא למעלה מבחי' החכמה שבנפש האדם כו', ובשרש ההיכל הזה בבחי' מקיף דאבא יש לו יתרון מעלה גם על בחי' המשכת ח\"ע דתורה דאצילות שנמשך בדיבור שנק' נהנין מזיו השכינה שהוא בחי' חכמה שבמל' דאצילות המאיר לנשמות בג\"ע בהשגות סודות הקבלה פנימיות התורה או בפלפול דיני הלכות שרש בחי' התלמוד דאינון במדריגת מארי קבלה בבחי' אצילו' שבבריאה, אמנם בלא דו\"ר לא פרח' לעילא ונחסר ב' דברים הנ\"ל בחי' ההעלאה שיהי' מזה ההיכל ובחי' ההמשכה דח\"ע שמלובש בתלמוד כו', וע\"כ מכריזין אשרי מי שבא לכאן לג\"ע ותלמודו שלמד בעוה\"ז בידו [דוקא כו'] וד\"ל."],[1900640028,"<b>בעזר\"ה ית' דרוש אדמו\"ר ר' דובער נבג\"מ דרוש שעשוע המלך</b>\n<b>בספר</b> עמק המלך שער שעשועי המלך כו' מבואר שם ענין ובחי' שעשועי המלך בעצמותו שהוא בבחי' רצוא ושוב דוקא, כמשל התנועה באדם שיתנענע אנה ואנה בעת השעשועי' כשמשתעשע באיזה דבר מה כו', או כמשל הבהקת אור המתנוצץ באבן הטוב שהברק מבריק לעין בבחי' תנועה דרו\"ש כו', שהוא דמיון לבחי' חו\"ג שבעצמו' השעשועי' וזהו ב\"פ ש\"ע ש\"ע כו' ע\"ש. ולהבין כ\"ז יש להקדי' תחלה בבאור ענין [בחי'] רו\"ש שבמל' דאצי' כמ\"ש והחיות רו\"ש, דקאי בכללו' מקור כל החיים כו'. דהנה ידוע שהמל' הוא מקור המהוה מאין ליש, ויש להבין תוכן ענין זה דהתהוות מאין ליש שאין זה רק מאצי' לבריא' בלבד אבל לא בהשתלשלו' [דבי\"ע] מבריאה ליצי' ומיצי' לעשי' גם בבחי' ההשתל' דע\"ס כמו ממל' דבריאה שנעשה כתר ליצירה כו' שבחי' ההשתל' דמל' דבריאה ביצי' ומיצי' לעשי' כו' הוא בבחי' ההשתלשלו' דיש מיש הנק' עלה ועלול ולא בבחי' מאין ליש כו' וד\"ל.\n<b>ולהבין</b> זה הנה תחלה י\"ל בבאור יותר ענין בחי' ההשתלשלו' דיש מיש הנק' עו\"ע, להיות ידוע שכל מקבל לגבי המשפיע כלא וכאין חשוב ממש מאחר שמקבל מבחי' האחרונה שבמשפיע, ונמצא המשפיע הוא עיקר אמיתי' היש והדבר שהוא בחי' המקור כו', והנשפע והנמשך ממנו הוא רק הארה חצוני' בעלמא דכלא וכאין חשוב, וכך הוא בכל פועל ונפעל, שהנפעל העלול מן הפועל הוא כלא לגבי כח הפועל[ו] וכן הנולד לגבי המוליד כו', וזהו הנק' עלה ועלול שהעלול כלא חשיב לגבי עילתו. וגם מלבד בחי' בטול ערך העלול לגבי עילתו בכמותו, הנה גם באיכותו ומהותו הוא כלא חשיב, דהיינו שהעלול הוא בבחי' גשמיו' לגבי העילה שלו שהוא בבחי' הדקות והרוחניו' בתכלית הדקות נבדל בערך מהגשמי' העלול, וגם שהעלול נפעל ונולד ונמשך מכחו של העילה והשפעתו מ\"מ העלול הנפעל ונולד הוא גשמי בערך דקות המשפיע. כמו ע\"ד דוגמא בענין צמיחת העשב [א]ו התפוח מכח הצומח הרוחני שאין לדמות ערך מתיקות ומרירות שבעשב ותפוח לגבי בחי' מתיקות או חמיצות זו כמו שהוא בשרשה ומקורה במשפיע שהוא כח הצומח הרוחני, שבודאי בחי' חמיצו' או"],[1900640042,"מתיקות שבתפוח ועשב גשמי הוא כלא לגבי רוחני' המתיקות וחמיצו' דתפוח ועשב זה בכח הצומח הרוחני ששם הוא מהות רוחני דק ביותר וכשנגדל מכח הצומח הרי נעשה מהות גשמי כו' (מלבד מה שכלא וכאין חשוב כח גדלות העשב לגבי עצם כח הצומח כי רב הוא כו'). אך הנה אעפ\"כ א\"א לו' על בחי' מהות המשפיע הנק' עילה שנק' בשם בחי' אין ממש, גם שהוא בתכלי' ערך הדקות והרוחניו' לגבי העלול המקבל ממנו מ\"מ נתפס גם הוא בבחי' מציאו' ודבר מה עכ\"פ אלא שהוא בחי' מהות דק ורוחני מאד לגבי גשמיו' העלול הנפעל הימנו כנ\"ל, ואדרבה הלא הוא הנק' אמיתי' הדבר והיש שנק' מקור למקבל כנ\"ל רק שאינו בבחי' יש בהגשמה אלא הוא רוחני, אבל הוא בחי' מהות דבר מה עכ\"פ בבחי' מציאות ויש. ונמצא דגם שכל בחי' משפיע נק' בחי' אין רוחני לגבי בחי' ההגשמה ויש של המקבל העלול מפני שמובדל הימנו בערך [ב]כמות ובאיכות וכנ\"ל, מ\"מ לא נק' בבחי' אי\"ן ממש אלא גם הוא בחי' יש יחשב רק שהוא יש רוחני לגבי יש של המקבל העלול שהוא יש גשמי כו', וכמו ממשו' היש של התפוח ועשב בטעם הגשמה [ד]מתיקו' וחמיצו' לגבי רוחניו' של העשב והתפוח במקורו בכח הצומח שגם שם הרי בחי' כח רוחני זה המגדל ומצמיח ליש דתפוח במתיקו' וחמיצו' רוחני עכ\"פ גם הוא בבחי' יש ודבר מה אלא שהוא מהות כח הצומח בבחי' מהות רוחני ודק אבל לא שנק' בחי' אין ממש רק שנק' אין רוחני לגבי הגשמת היש דתפוח ועשב כו' וד\"ל. ונמצא מובן מכ\"ז שבכל בחי' משפיע ומקבל שנק' עו\"ע ה\"ז בא בבחי' יש מיש דוקא ולא מבחי' אין ליש, דהיינו שאין המשפיע נק' בשם אין ממש שיקרא בשם מאין ליש, אלא גם הוא בחי' יש אלא שהוא יש רוחני ומתהוה ממנו יש גשמי שהוא העלול, וא\"כ ה\"ז בבחי' מיש ליש ולא מאין ליש כו' וד\"ל.\n<b>ועוד</b> יובן בכ\"ז שגם מה שכל עילה או משפיע נק' בבחי' אין רוחני לגבי יש דמקבל העלול הנה הוא בא בחלוקי מדרגו' הרבה, דהיינו לפ\"ע ההשתל' דעו\"ע [שב]ודאי אינו דומה עו\"ע זה לעו\"ע הגבוהים הרבה ממנו, ע\"ד דוגמא הנ\"ל בעשב ותפוח לגבי הרוחני' דכח הצומח, וכמ\"כ גם הרוחניו' דכח הצומח נק' יש גשמי לגבי מקור חוצבו במזלות עליוני', ועד\"ז גבוה מעל גבוה כו' כל א' נק' יש גשמי לגבי עילתו הרוחני [כו'], וא\"כ ה\"ז בא בבחי' ההשתלשלו' עד שאותה העילה שנק' אין רוחני לגבי העלול ממנו נק' יש גשמי לגבי עילתו שלמע' ממנו, ונמצא שלא נק' אין רוחני רק בערך גסות היש של העלול שלו בלבד, אבל לגבי העליון הימנו נק' גם הוא יש גשמי, ועד\"ז עד רום המעלות, עד שגם עילה הראשונה אינה נק' אין באמת רק בחי' אין של היש העלול המקבל ממנו בלבד להיות שגם הוא מהות דבר מה במציאו' עכ\"פ ולא בבחי' אין ממש רק שנק' אין רוחני ע\"ש בחי' הדקות והרוחני' בלבד כנ\"ל, וגם זה רק לפ\"ע היש שמקבל הימנו בלבד כו' וד\"ל."],[1900640055,"<b>וכ\"ז</b> נק' בחי' [ה]השתלשלו' דעו\"ע שזהו מיש ליש וגם בבחי' ראשית ההשתל' דחכמה הרי בחי' החכמה והשכל נתהוה מלמעלה מן השכל בבחי' מיש ליש, דגם שנא' והחכמה מאין תמצא בחי' אין, זה אינו בחי' אין באמת אלא הוא רק בחי' אין רוחני לגבי בחי' היש דחכמה בלבד, אבל גם הוא נחשב בבחי' מציאו' ודבר מה רק שהוא מהות רוחני יותר ממהות דחכמה הנמצאת ממנו כו'. וכמו שאנו רואי' בחוש שכח המשכיל ההיולי שמשכיל כל שכל וחכמ' בג[י]לוי דבר מה, גם הוא בבחי' יש ודבר מה שהרי הוא בחי' מהות כח רוחני עכ\"פ המשכיל כל שכל כו' ויש בו בחי' מיעוט וריבוי כמו כח המשכיל דתינוק קטן הוא בכמות ואיכות כו', רק שהוא מהות כח רוחני יותר מן המהות דשכל וחכמ' שבאה בגילוי ע\"כ א' מאין תמצא וכנ\"ל בכל עו\"ע וד\"ל (ובמ\"א מבואר שהחכמה מאין תמצא מאין ליש ולא יש מיש שהרי א' דאור אבא יונק ממזל ונוצר כו' וד\"ל).\n<b>והנמשל</b> מכ\"ז יובן למעלה בכל ההשתל' דכל [ה]עולמו' דבי\"ע שכ\"ז הוא בבחי' ההשתלשלו' מיש ליש ולא מאין ליש כו', כמו עולם הבריאה שבו נשמות ומלאכים שמקבלי' דין מן דין כמו וקרא זא\"ז כו' הנה קבלתם זמ\"ז הוא בבחי' עו\"ע שגם העילה נתפס בבחי' מציאו' יש ודבר עכ\"פ רק שנק' אין רוחני לגבי העלול ממנו בלבד, אבל לא שנק' בחי' אין באמת רק לגבי המקבל בלבד הוא שנק' כן כנ\"ל באריכות וד\"ל. ולא בעולמו' דבי\"ע עצמן בלבד, אלא גם בבחי' השתלשלו' הספי' דבי\"ע, כמו מבחי' מל' דבריאה שנעשה כתר ליצי' כו' הרי מבחי' האחרונה שבע\"ס דבריאה שהוא בחי' המל' דשם נעשה בחי' כתר בעולם היצי' הענין הוא שנק' בחי' אין של ערך היש דעולם היצי' בלבד, והוא מ\"ש דמבחי' מל' דבריאה נעשה כתר לעולם היצירה, אבל גם בחי' מל' דבריאה הוא בחי' מהות [ו]יש עכ\"פ רק שנק' בחי' מהות רוחני ואין יותר לגבי בחי' היש דעולם היצי' כנ\"ל בכל עו\"ע, שהעילה נק' אין רוחני של היש דעלול כו', אבל לא שבחי' מל' דבריאה נק' אין באמת כו' שהרי ידוע ענין ובחי' ע\"ס דבריאה שהוא בחי' כח אלקי הפועל ובורא את כל עולם הבריאה נשמו' ומלאכים שבו להיות במציאות יש בעלי גבול כו', ונק' כח האלקי הזה בחי' אין רוחני של היש דנשמו' ומלאכי' דבריאה אבל לא שהוא בחי' אין האמיתי אלא רק שהוא אין רוחני לפ\"ע היש של הנשמו' ומלאכי' דעולם הבריאה בלבד כנ\"ל בכל עו\"ע, וא\"כ גם ביריד' אור ושפע ממל' דבריאה להיו' בחי' כתר לעולם היצי' גם הוא בבחי' עו\"ע שהוא מיש ליש, מאחר שכל ענין ע\"ס דבריאה הוא בבחי' מהות ויש כח האלקי עכ\"פ רק לפ\"ע"],[1900640067,"התהות היש דעולם הבריאה כנ\"ל, א\"כ גם בחי' מל' דבריאה גם שנעשה בחי' אין רוחני בעולם היצי' הנק' בחי' כתר שהוא בחי' אין הראשון לכל ההשתל' דיצי' מ\"מ אין זה בחי' אין האמיתי רק בחי' אין של כל ההשתלשלות דיצי' (וכמו שבהשתלשלו' מנשמו' ומלאכי' דבריאה לנשמו' ומלאכי' דיצי' שמקבלי' דין מן דין כו' שהוא מיש ליש ולא מאין ליש כנ\"ל כך הוא בענין ההשתלשלות דספירות מבריאה ליצירה כו' וד\"ל), וכמו\"כ מיצי' לעשי' כשמל' דיצי' נעשה כתר לעשיה ג\"כ הוא בבחי' עו\"ע שזהו מיש ליש עד\"מ הנ\"ל בכל שפע עו\"ע עד התהות היש [ה]גשמי דדצ\"ח מכחות הרוחני' שלהם במזלות וכה\"ג וד\"ל.\n<b>ולהבין</b> כ\"ז בתוס' ביאור, וגם להבין האיך יתכן בענין ההשתל' הספי' ירידו' המדרגות כ\"כ כמו ממל' דבריאה כתר ליצי' וממל' דיצירה כתר לעשיה כו'. הנה יש להקדים לזה משל א' והוא כמו השפעת איזה שכל שמשפיע הרב לתלמידו המשכיל ונבון ביותר מכל תלמידיו שבודאי ישפיע אליו הדבר שכל הזה בתכלי' הדקות והפשטת ההגשמה, כמו שהשכל הזה הוא לעומק נקודת דקותו בכדי שיהי' נתפס לפ\"ע אופן תכלית דקות כלי קבלת שכל התלמיד הזה [שהוא] משכיל ונבון להבין אותו בתכלית עומק דקותו כו', אך הנה גם בחי' תכלית הדקו' של זה השכל שמשפיע לתלמידו זה לפ\"ע דקות כלי קבלתו עכ\"ז הוא נק' עדיין בשם בחי' גסו' והגשמ' גדולה לגבי עומק נקוד' אור שכל זה כמו שמשיגו הרב המשפיע לעצמו לפי דקות כלי שכלו שהוא בערך נבדל מן התלמיד עד שנק' השפעת הרב לשכל זה לתלמידו בחי' אין רוחני לגבי יש דהשג' התלמיד הזה גם שהוא משכיל ונבון ביותר, ומלבד זה הנה יש עוד מדרגה שלמעלה מזו הנק' בשם בחי' אי\"ן נעלם לגבי התלמיד כי הרי בחי' עומק השגת שכל זה כמו שמשיגו הרב לעצמו כפי כח קבלתו א\"א לו כלל להביא בדבור לתלמיד להבינו כי לא יוכל להשיגו כלל מפני היותו בערך נבדל הימנו לגמרי וע\"כ בהכרח להרב להשפיע לו באופן שלא יהי' בחי' הדקו' ועמוק כ\"כ אלא בבחי' הגשמה יותר והוא אין רוחני לגבי היש דמקבל [זה] שהוא תכלי' דקות של השגת התלמיד כו' וד\"ל, והנה כמ\"כ יובן עוד כאשר צריך הרב המשפיע להשפיע עוד הפעם לתלמיד הקטן מתלמיד הראשון אותו דבר שכל וחכמה הרי צריך להשפיל אות[ה] בענין הגשמה יותר מכמו שהשפיע אותו לתלמידו הגדול עד שבחי' דקו' ההשגה של השכל שבתלמידו הגדול נעשה בחי' אין רוחני ואין נעלם לגבי התלמיד הקטן הימנו, כמו שהשגת הרב נק' אין נעלם לגבי התלמיד הגדול הנ\"ל מאחר שאותו השג' השכל של תלמידו הגדול א\"א לו להביאו בהשפעה לתלמידו הקטן כי לא יוכל להשיגה כלל להיותו בערך נבדל הימנו עד שנק' בחי' אין נעלם לגמרי, אך כמו שבחי' הגשמה שאצל הרב נעשה בחי' אין רוחני לגבי יש של התלמיד הגדול כך בחי' ההגשמה והיש של השג' שכל התלמיד הגדול"],[1900640078,"כשישפיענה לתלמיד הקטן הוא שנעשה לו בחי' אין רוחני, אבל כמו שמשיגה תלמיד הגדול לעצמו לא ישיגנה תלמידו הקטן כלל ונק' אין נעלם כמו שהתלמיד הגדול לא יוכל להשיג השגת שכל זה כמו שמשיגה הרב לעצמו כו'. ונמצא ב' מדרגות יש בין עילה לעלול, הא' בחי' אין נעלם שנשאר בעילה המשפיע ולא יוכל לבא למטה לעלול המקבל, והב' בחי' אין רוחני שנמשך למקבל להיות בבחי' יש דמקבל אבל הוא רק בחי' הגשמ' ויש דמשפיע ולא כמו שהוא לעצמו כו' כנ\"ל וד\"ל.\n<b>והנמשל</b> מכ\"ז יובן למעלה שמבחי' מל' דבריאה נעשה כתר ליצי' כו' די\"ס דבריאה הוא בחי' אורות [דאלקו'] שהן בחי' מקוריי' משפיעים לכל עולם הבריאה, אך בחי' ט\"ס הראשונות כמו חב\"ד חג\"ת כו' אינם מתלבשים בתוך עולם הבריאה בנשמו' ומלאכי' דבריאה בתוך תוכ[ם] בבחי' כח הפועל בתוך הנפעל ממש אלא הן בבחי' אין והעלם מקור[י], רק בחי' מל' דע\"ס דבריאה הוא בחי' האחרונה שהוא בבחי' ערך יש ודבר מה המתגלה כמו בחי' אותיות וכה\"ג הוא המתלבש בתוך עולם הבריאה ונק' מל' דבריאה בבחי' כח הפועל בנפעל כו', ובחי' מל' זה הוא שיורד למטה בדילוג הערך להיו' בחי' כתר ומקור וראש לכל עולם היצי' כו'. והענין הוא עד\"מ הנ\"ל בעו\"ע דרב ותלמיד שבחי' ההגשמה והיש שבמשפיע הוא שנעשה בחי' אין רוחני להיו' מזה התהוות השגת המקבל גם שהוא תכלית דקותו כו', כך בחי' המל' שבעליון בחי' היש שבו הוא אשר [נעשה] בחי' כתר בחי' אין רוחני להיותו מקור לעולם היצירה גם שהוא נק' אין ומקור ליצי' ה\"ז נמשך מבחי' היש דבריאה שהוא בחי' המל' כו', אבל בחי' ט\"ס עליונו' דבריאה נק' בחי' אין נעלם לגמרי לגבי היצירה שלא נמשך מהם לגמרי ביצי' עד\"מ הנ\"ל בהשג' שכל שהרב משיג לעצמו שלא יוכל להשפיע כלל לתלמיד כו' וד\"ל. וכמ\"כ יובן מה שיורד ומשתלשל עוד מיצי' לעשי' שבחי' מל' דיצי' נעשה כתר לעשי', דפי' מל' דיצי' היינו ג\"כ בחי' כח הפועל האלקי שיצר כל עולם היצי' כו' שזהו בחי' התגלות היש כו', ומזה נעשה בחי' אין וכתר לעשיה עד\"מ הנ\"ל בהשפלת הרב אותה דבר חכמה עצמה לתלמיד הקטן [הימנו] שמה שנעשה [בבחי'] הגשמה ויש בתלמיד הגדול הוא שנעשה בחי' אין רוחני לגבי תלמיד הקטן כו', וכמ\"כ עד בחי' מל' דעשי' שהוא מקור להגלגלי' הגשמיי' והארץ וכל אשר בה כו' שזהו כמו שהושפל עוד השפע מן הרב לתלמיד שלישי שנמוך במדרגה גם מן התלמיד האמצעי כו', שזהו בכלל ענין אור ושפע הבא בג' צמצומים דבי\"ע ממל' דבריאה ביצי' וממל' דיצי' בעשי' וממל' דעשי' בעה\"ז [הגשמי] כו' וד\"ל (ועוד אפשר לומר דמה שבחי' מל' שבעליון נעשה כתר לתחתון היינו ב' מדרגו' הנ\"ל שבין העילה והעלול, בחי' אין נעלם מהעלול לגמרי שנשאר במשפיע הוא בחי' מל' שבעליון שנשאר למעלה בבחי' ההתנשאות כו' ובחי' אין רוחני של העלול הוא מה שנעשה בחי' כתר לתחתון כו' וד\"ל)."],[1900640089,"<b>והנה</b> כל הנ\"ל בבחי' ההשתלשלו' דעו\"ע שהוא בבחי' מיש ליש דוקא ולא בבחי' מאין ליש אין זה רק בג' עולמו' דבי\"ע כמו גם בבחי' הספי' שלהם שממל' דבריאה נעשה בחי' כתר ליצי' כו', אבל מבחי' האצי' לבריאה כמו מבחי' מל' דאצי' שנעשה בחי' כתר לבריאה הוא הבא בבחי' השתל' מאין ליש דוקא ולא מיש ליש שנק' עו\"ע דהיינו שנק' בחי' אין האמיתי בבחי' אין אלקי דבחי' האצי' דאיהו וחיוהי חד כו' ולא בחי' אין רוחני לפ\"ע היש דמקבלי' בלבד הנ\"ל בענין עו\"ע, להיות שע\"ס דאצי' מובדלים בדבר זה מבחי' ע\"ס דבי\"ע במה שהן בבחי' אור אין האמיתי ולא במהות יש ודבר מה כמו מהות ע\"ס דבי\"ע שהרי נק' ע\"ס דאצי' ע\"ס בלי מ\"ה בלי מהות כו' וכידוע וד\"ל.\n<b>ולהבין</b> באור הדברים הנה לכאורה באמת זהו כדבר פלא ביותר, שאם בחי' ע\"ס דבריאה נשתלשלו מבחי' ע\"ס דאצי' בבחי' ההשתל' שהוא בחי' ההשפעה והמשכה ככל השפעה והמשכ' מגבוה לנמוך שמבחי' מל' שבעליון נעשה כתר לתחתון כנ\"ל בענין מל' דבריאה שנעשה כתר ליצי' כו', א\"כ למה לא נק' בחי' ע\"ס דאצי' בחי' אין של היש דע\"ס דבריאה, מאחר שע\"ס דבריאה הוא בחי' היש ובחי' מקורם הוא הע\"ס דאצי' שהוא בחי' האין שלהם בלבד ולא בחי' אין האמיתי בלי מהות יש כלל, שהרי בהכרח לומר שבחי' הרוחניו' והדקו' של ע\"ס דבריאה הוא באצי' שנק' משפיע, שמאחר שבא בכלל בחי' השפעה הרי יש מהות כח השופע בהכרח ששם הוא בחי' הרוחני' והדקו' שלהם הנק' אין רוחני כנ\"ל, ואם אנו או' שהמשפיע דאצי' נק' בלי מ\"ה בלי מהות כלל א\"כ א\"א לומר שבחי' ע\"ס דבריאה נשפעו ונמשכו מאורו' דאצי' עד שנק' בשם רוחני' ואין שלהם, כי אם נשפעו הרי יש מהות שופע עכ\"פ, ואם לא נשפעו מהיכן נמצא מציאו' היש דע\"ס דבריאה להקרות בשם ע\"ס דבריאה עכ\"פ כנ\"ל. אך הנה הענין הוא דבאמת נמשך אור מציאות דע\"ס דבריאה מבחי' אור דאצי' דוקא אבל לא בבחי' השפעה והמשכה ממהות למהות כשאר השפעו' והמשכו' דעו\"ע הנק' יש מיש כו' כנ\"ל, כי המשכ' והשפע' אור האצי' אינו בבחי' מהות דבר מ\"ה כלל שהרי נק' ע\"ס בלי מ\"ה כו', אלא בחי' ההארה דאור האצי' הוא בבחי' אי\"ן ממש והיינו הנק' מאין ליש כנ\"ל.\n<b>ובאור</b> הדברים שאין זה כמו פעולת היד בתנועה ופעולה נגלית באצבע הכותבת ומציירת ציור וכה\"ג שגם שפעולה ותנועה זו הגלויה גשמי' היא לגבי רוחני' דכח המניע תנועה זו שביד עצמו מ\"מ גם כח זה המניע את התנועה הזאת נק' בשם מהות ומציאו' כח עכ\"פ אלא עיקר הדמיון בזה הוא כמו ענין קריא' שם לאדם, דהנה אנו רואי' כאשר יקראו לאדם בשמו ראובן או שמעון וכה\"ג מיד יפנה"],[1900640100,"כל עצמותו לגבי הקוראו באותיו' שמו, וזהו כמו דבר פלא לכאורה שהרי בודאי לא יש בחי' אור וחיות מעצם נפשו באותיות שמו כלל וכלל גם לא חיות מצומצם כחיות השערות וצפרני' כי בלא שם כלל יוכל לחיות ממש , וגם כשיש לו שם כשיושב לבדו ואין מי שיקראנו בשמו א\"צ לשמו כלל ויוכל לשכוח שיש לו שם לגמרי כי א\"צ לשמו רק שעי\"ז יוכל זולתו לקרוא אותו ויהי' במה להתפס אצל זולתו שאם אין לו שם אין לזולתו במה לתפוס בו מרחוק כ\"א מקרוב שיתפסנו בגופו, אך ע\"י השם כשקוראו נתפס בו והולך אליו כאלו תופסו בידו ובגופו, אבל לגבי עצם האדם אין שמו שייך אליו כלל כי א\"צ לקרוא א\"ע ולא ירגיש בעצמו שום ענין הפרש בין כשיש לו שם או אין לו שם כי השם לא מעלה ולא מוריד כלל לגבי עצמותו. אך א\"כ זהו דבר פלא מה שאנו רואי' שע\"י קריאת השם כשקוראו זולתו יוכל להמשיכו אנה ואנה ממקום למקום, שהרי נפנה כל עצמותו כשקוראו אשר לא הי' נפנה כ\"כ גם שהי' אוחזו זולתו בגופו כי יותר בקל יפנה ע\"י קריאת שמו משיאחזנו בגופו כו', וא\"כ בהכרח לומר שיש קצת בחי' חיות מאור וחיות נפשו מלובש באותיו' שמו שיקראוהו אביו ואמו עד שעי\"ז נפנה אור וחיו' נפשו בהזכרת אותיו' שמו וממילא נפנה גם גופו כו' וד\"ל. אבל אין באותיו' שמו רק בחי' חיצוני' הטפל אל נפשו שהוא אשר בהם יותפס אור נפשו להפנות בלבד אנה ואנה, אבל לא שהאותיו' שייכי' לעיקר עצם אור וחיות הנפש, וה\"ז כמו עד\"מ בית יד של הכלי שבודאי א\"א לו' שהבית יד נחשב מעיקר הכלי כי עיקר הכלי הוא ענין הבית קבול שלו שהמשקה נכנס לתוכו וזהו עיקר הכלי, אבל הבית יד של הכלי אין בו תוך לקבל משקה כלל וע\"כ לא מתיחס כלל עם עיקר הכלי, אך עכ\"ז יש בו תועלת השייך אל ענין אחר שהוא כדי שיוכלו ליקח הכלי ביד ולשתות [בו] שאם אין בו בית יד אין במה לתפוס את הכלי ולהטותו ולהמשיכו אל פיו לשתות בו, וע\"י הבית יד יתפסו בו וימשיכוהו אל הפה לשתות בו, והשתיה עיקר התועלת המכוון מן הכלי כו', דגם שיש בית קבול בכלי ומקבל משקה לתוכו אם אין לו בית יד לתפוס בו ואין יכול לשתות בו לא הגיע והשיג למחוז חפצו באותו הכלי כו', ואעפ\"כ אין הבית יד רק טפל לגבי הכלי כי אינו רק כדי שיוכל לתפוס הכלי אבל כשא\"צ לתפוס בו כלל כגון שא\"צ לשתות או שא\"צ להטותו ממקום למקום אנה ואנה א\"צ לבית יד כלל ולא יפול גרעון וחסרון כלל בגוף הכלי בהעדר ממנו הבית יד, ונמצא שהתועלת המגיע מן הב\"י אין זה שייך כלל לגוף הכלי שהוא ענין חלל בית קבולו, אלא רק לענין בחי' התפשטו' והטיי' הכלי אנה ואנה או שיוכל אדם ליקח אותה בידו לשתות וכה\"ג וד\"ל, וה\"ז דומה ממש לענין קריא' שמו של אדם שאין זה התועלת שייך לגוף ועצם הנפש כלל, ומה שעי\"ז נפנה לקוראו ה\"ז התועלת רק בבחי' ההתפשטו' והטיית הנפש אל זולתו בלבד כמו התועלת מן הבית יד לבד כו' וד\"ל."],[1900640111,"<b>והנמשל</b> מכ\"ז יובן למעלה ג\"כ בבחי' הארת אור האצי' בבריאה שהוא רק ע\"י בחי' אותיות ושמות בלבד שזהו הנק' מאין ליש כנ\"ל, דהנה מאחר שע\"ס דאצי' נק' ע\"ס בלי מ\"ה בלי מהות כלל כנ\"ל להיותו בבחי' אין האמיתי כו' א\"כ א\"א לו' שנמשך משם בחי' המשכ' והשפע' ממש בבחי' מהות ומציאו' דבר מה כו', אלא בחי' ההמשכה וההארה מאצי' לבריאה רק כמו קריאת אותיות השם בלבד כשקוראי' לאדם בשמו כנ\"ל שאיו באותיות הללו בחי' המשכה עצמי' מעצומ\"ה הנפש כלל כי לעצמו א\"צ שם כלל כנ\"ל, וכמו הכלי בלא בית יד שאין זה גירעון בעצמה כלל, רק מה שע\"י בחי' אותיות השם נפנה לקוראיו מזה יש הוראה שיש קצת אור מן הנפש מלובש בהם, אבל אין זה רק בשביל בחי' התפשטו' והטיי' אור הנפש לזולת[ה] בלבד ואין זה שייך לגבי עצמות[ה] כלל כמו הב\"י כו' כנ\"ל, וכך בחי' המשכ' אור האצי' נמשל לבחי' קריאת שם בלבד, שבקריאה זו בשם יש קצת אור האצי' מלובש בו וכמ\"ש לכל אשר יקראוהו כו', כי ע\"ס דאצי' נק' רזא דשמא קדישא כו' והוא בחי' ע\"ב ס\"ג מ\"ה ב\"ן, דחו\"ב דאצי' מלובשי' בב' שמות הללו דע\"ב ס\"ג ומדות בשם מ\"ה ובחי' המל' בשם ב\"ן כידוע, והרי כשצריך להיו' בחי' המשכ' מאצי' לבריאה מזכירים וקוראים בשם א' משמות הללו והוא שם הוי\"ה במלוי יודי\"ן או ההי\"ן כו', ובזה בחי' עצמו' המאציל דע\"ס דאצי' עצמן נפנה לקוראין בשמות הללו ונמשך על ידי בחי' שמות הללו בבריאה וכמו בש\"ע שמכווני' בשם הוי' שבכל ברכה להמשיך אור מאצי' לבי\"ע כמו בא\"י רופא חולי כו' שזהו שם הוי\"ה בניקוד סגו\"ל דוקא ואז נמשך מבחי' שם זה בבי\"ע לרפאות שהרפואה בבחי' הת\"ת, וכן השיבנו בבחי' שם הוי' בניקוד צר\"י וכה\"ג, וכמארז\"ל מפני מה ישראל צועקי' ואינם נעני' מפני כשקוראי' אין קוראי' בשם כו' ובחי' המשכ' קריא' שמו' דאצי' בבי\"ע ה\"ז כמו כשקוראי' לאדם שהוא רק בחי' התפשטות והטיי' נפשו וכן כמו התפשטות הכלי ע\"י הבית יד, ולא שהן ממהות אורות דאצי' עצמן שהן מיוחדים בעצמות המאציל ונק' ע\"ס בלי מ\"ה כנ\"ל וד\"ל.\n<b>והנה</b> יש עוד הפרש בין בחי' [ה]השתלשלות דיש מיש שנק' עו\"ע ובין בחי' [ה]השתלשלות דמאין ליש שזהו כמו קריאת שמות הנ\"ל. דהנה בבחי'"],[1900640122,"השתל' דיש מיש בהכרח שישאר העלול בבחי' יש נפרד לעצמו באופן שיש לו מציאות וקיום מהות בפ\"ע כאלו אין לו מקור השופע עליו כלל אע\"פ שבאמת מקבל כל רגע ממקורו שהוא העילה, וכמו דוגמת התפוח והעשב שגדלי' מכח הצומח הרוחני כנ\"ל שזהו מיש מיש ליש, מיש רוחני ליש גשמי כנ\"ל באריכות, הנה אנו רואים דאע\"פ שבכל רגע מתגדל וצומח התפוח והעשב מן כח הצומח הרוחני ואם יופסק כח הצמיחה זו לא יצמיחו עוד וא\"כ כל רגע שופע הכח הצומח מיש ליש כו', אעפ\"כ [הרי] התפוח והעשב נראי' לעין במהות ומציאות יש נפרד ממקורם ודבר בפ\"ע כאלו אין להם מקור המגדלן כלל וכלל, וראי' לזה שהרי אם יכרתו התפוח והעשב מכח הצומח שבארץ יש להם קיום במציאותן ומהותן רק שלא יצמחו עוד אבל מהותם נשאר בקיום עולם לא ירקבו ולא יכלו, וכך הוא גם בכל המשכ' רוחני' שהוא בבחי' עו\"ע כמו המזלות שמקבלים מהאופנים וכה\"ג בבחי' יש מיש כנ\"ל שגם שמקבלים תמיד אור שפעם מ\"מ הם בבחי' יש נפרד לעצמם עד שגם בהפסקת אור השפע מעליהם יתקיימו רק שאין להם תוספת חיות עוד כו', וכה\"ג עד רום המעלות בכל ההשתל' דעו\"ע בבחי' יש מיש לפי שהתהוות הזאת דיש מיש מאחר שהוא ממהות למהות הרי גם המוליד [ו]המשפיע הוא בחי' מהות דבר מה והמשכתו באה להיות בבחי' מהות אחר רק שהוא בא מן הרוחני אל הגשם וכה\"ג, א\"כ יהי' גם הנולד והמתהוה בחי' מהות נפרד לעצמו, וזהו הכלל גדול ואמיתי בכל התהוות מהות ממהות יהי' גם המתהוה מהות בפ\"ע מאחר שיש בחי' מהוה הרי יש בחי' מתהוה במציאות לעצמו כו', והן ב' דברים נפרדים מהוה ומתהוה כו' וד\"ל.\n<b>וזהו</b> כל עיקר טעות הפלסופים וגם המקובלים הראשונים שדימו לומר בכל ההשתל' שהוא בבחי' עו\"ע יש מיש שהוא ממהות למהות כו', אבל באמת אין זה רק בהשתלשלו' דג' עולמות דבי\"ע כנ\"ל, אבל מבחי' האצי' לבריאה אין ההמשכה ממהות למהות מיש ליש אלא מאין ליש כנ\"ל, והוא כמו קריאת אותיות השמות שהרי אם יפסיק הקורא מלקרות הרי אז אין לאותיות השם שייכות כלל לנפש האדם עד שיוכל לשכוח על שמו לגמרי וא\"כ כאשר יקראהו זולתו בשמו אין זה המשכ' עצמיו' ומהות דבר מה מן הנפש אלא רק בחי' התפשטות והטיית הנפש ע\"י אותיות השם כו', וא\"כ יובן ג\"כ למעלה שאם יופסק בחי' קריאו' אותיות דשמות דע\"ב ס\"ג כו' אין זה שייך כלל לגבי עצמות אור האצי' כמו כאשר אין קורא בשמך שאין צריך לשם כלל כו', ולפ\"ז הרי בהכרח שצ\"ל בחי' המשכו' קריא' אותיות ושמות דאצי' תמיד בבריאה שאם יופסק אפי' [רגע] אין לעולם הבריאה מציאות וקיום כלל, שאם הי' השפעת האצי' לבריאה מיש ליש שנק' בחי'"],[1900640133,"התהות דבר מדבר אז היה עולם הבריאה בבחי' יש נפרד לעצמו כמו שנשאר התפוח במהות בפ\"ע גם שמקבל מכח הצומח כנ\"ל, אבל אם יופסק בחי' קריא' והמשכ' דשמות העליוני' אין להנבראים קיום ומציאות כלל והי' כלא הי' וד\"ל (מאחר שבלא קריאת שם א\"צ לשם עד שיוכל לשכוח על שמו א\"כ ה\"ז כאלו לא היה שם לאדם או בית יד לכלי כו', משא\"כ בהמשכ' מהות שגם לאחר סילוקו מתקיים מהות דבר שהמשיך כמו כח הפועל בנפעל שנשאר קיום בנפעל גם לאחר סילוק ידיו כו' וד\"ל).\n<b>והנה</b> מעתה י\"ל ענין ובחי' רצוא ושוב שבמל' דאצי' בבריאה כנ\"ל, דהנה בחי' מל' דאצי' הוא בחי' שם ב\"ן והוא בחי' כלי לאור המל' וכן כל השמות דע\"ב ס\"ג כו' הן בחי' כלים לאורות, והטעם הוא מפני שע\"י הכלי נתפס האור במציאות דבר מה כו' כך הוא בחי' השם שעל ידו נתפס גוף הדבר לזולתו להמשיכו אליו כנ\"ל במשל הבית יד לכלי כו'. והנה מבואר למעלה שבחי' [ה]השפעה [ה]אלקי' מאצי' לבריאה הוא מאין ליש דוקא שזהו כמשל קריאת השם והוא בחי' הכלי שעל ידו יותפס לזולתו, אבל בלא קריאת השם אז השם הזה נכלל בעצם האדם וכלא הי' עד שיוכל לשכוח על שמו, וא\"כ ה\"ז בחי' ההתכללו' בעצמותו בלתי הגלות נגלות אל זולתו כלל מאחר שאין לזולתו במה להתפס בו בלי קריאת שם ואז הוא נשגב ומרומם בהפלא' והעלמה לגמרי מזולתו כי אין לזולתו בחי' תפיסא בו כלל וכלל, וכך יובן למעלה בבחי' אורות העליונים דאצי' שיש בהן ב' מדרגות, הא' בחי' המשכה שלהן למטה בבריאה והוא אשר נתפסי' שם ע\"י בחי' קריאת שמות בלבד, והיינו ענין הוא ושמו שעצמי' דאצי' נק' הוא ושמו היינו בחי' הטייתו למטה אשר זהו ע\"י תפיסא במה שקורא בשמו בלבד, ובחי' ומדרגה הב' הוא בחי' התכללות שלהן בעצמותן בלתי הגלו' נגלות למטה כלל, והיינו כשנפסק בחי' קריאת שמו' דאצי' שאז אין שום ערך ושייכות לנבראי' להיות להן אחיזה ותפיסא בעצמו' אורות דאצי' כי נשגבו מהן לגמרי לפי שאין בחי' כלי במה להאחז ולהתפס בהן מפני הפסקות המשכות קריאת שמות שנק' בחי' כלי כנ\"ל. וזהו המלך המרומם לבדו המתנשא מימות עולם לגמרי כו', וזהו בחי' רצוא ושוב, [בחי'] המשכ' וקריא' השמות נק' בחי' שוב ובחי' הפסק' ההמשכ' והקריא' נק' בחי' רצוא שנכלל האור וחיות שבאותיות השם בבחי' עצמות האור כאלו אין [לו] שם כלל כו'. וזהו והחיות רו\"ש, פי' בחי' החיות שבשם ב\"ן רצוא למעלה ליפסק מבחי' ההמשכה, ושוב [ב]בחי' ההמשכה להיות נק' בשם כמו שם אדנ\"י ושם אלקים כו' וד\"ל.\n<b>אך</b> הנה באמת הרי יש כאן ב' הפכים מן הקצה אל הקצה, א' בחי' המשכ' מאצי' לבריאה להיות בחי' יש מאין כו', והב' בחי' בטול היש הנברא למקורו בבחי'"],[1900640144,"אין דאצי' מצד בחי' ההתנשאות וההתכללות בעצמות המאציל כמו ענין הפסקת קריאת השם כנ\"ל, ולפ\"ז צ\"ל בחי' ממוצע ביניהם דוקא שהרי אם יהי' בחי' רצוא דהתנשאות והתכללות אל עצמותו יותר מכפי המדה , כמו עד\"מ מי שהוא טרוד ביותר בעצמותו שלא יפנה כלל לקוראו בשמו מפני עוצם בחי' ההתכללות בעצמותו כו' הרי אז לא יהי' בחינת המשכה כלל למטה בעולם הנברא ויהי' כלא הי' כו', ואם יהי' בחי' ההמשכה דקריאת שם בחי' שוב יותר מכפי המדה כמו ענין ההמשכה מיש ליש ממהות למהות כנ\"ל הרי ישאר עולם הנברא בבחי' נפרד לעצמו כנ\"ל בכל התהות יש מיש, וזהו ענין ב' ההפכים שבין אור לכלי שמצד האור הוא בחי' ההתנשאות וההתכללות אל עצמו ומצד בחי' הכלי שהוא ענין השם הוא בחי' ההמשכה למטה כו' וצ\"ל בחי' ממוצע ביניהם והוא בחי' קו המדה שמודד ונותן שעור לב' הפכי' הללו דאורות וכלים שיהי' בהם בחי' מדה ומשקל במזג השוה ולא יגבור הא' על זולתו כלל, וע\"כ מסיבת זה האמצעי יוכל להיות התהות עולם הבריאה בבבחי' יש ואעפ\"כ אינו בבחי' יש נפרד כתפוח לגבי כח הצומח אלא הוא בבחי' בטול מיש לאין ואמנם לא שמתבטל לגמרי כו', וא\"כ יש בנברא בחי' אמצעי מב' הפכי' דאו\"כ הנ\"ל שהוא להיות בטל מחמת בחי' רצוא והוא בחי' יש מחמת בחי' שוב, ואין הבטול בטול לגמרי ואין היש בחי' יש נפרד לגמרי, וזהו מפני בחי' האמצעי שבאו\"כ כנ\"ל. וז\"ש והחיות רו\"ש גם בנבראים וד\"ל.\n<b>וזהו</b> נעשה אדם בצלמינו כדמותינו, פי' צלם ודמות הוא בחי' או\"כ, שהדמות הוא ענין התואר בלבד שמתאר לעצם הדבר כידוע והצלם הוא צורה העצמי' כו', וכך בחי' הכלי הוא בחי' תואר לתאר ולהגביל את האור כו' וכמ\"ש במ\"א. והנה על הכסא דמות כמראה אדם ויש בו בחי' צל\"ם ודמו\"ת כמ\"ש בצלמינ\"ו כדמותינ\"ו שזהו בחי' או\"כ דז\"א דאצי' שנק' אדם דאצי' כידוע, וזהו שא' נעשה אדם זה בבחי' או\"כ שנק' צלם ודמות והיינו בחי' או\"א דכתי' מ\"ה שמו ומ\"ה שם בנו כו' וכתי' ויברא ה' אלהים את האדם בצלמו כו' ב' שמות דהוי' ואלקים"],[1900640154,"שהן בחי' או\"א תרין רעין כו' וגם זיווגייהו תדיר להמשיך מוחין לז\"א בשביל צורך שפע העולמות דבי\"ע בבחי' החיצוני' כו' כנ\"ל, והוא ע\"י ענין המדידה באו\"כ דז\"א שיהי' במדה ומשקל במזג האמצעי דוקא כדי שיהי' קיום המציאות של העולמות כנ\"ל, והיינו שא' בזהר דאו\"א נק' מתקלא כו' וכמ\"ש מי מדד בשעלו מים כו' וכמ\"ש במ\"א וד\"ל.\n<b>והנה</b> כמו\"כ בבחי' בנין הנוק' דז\"א בבחי' המל' הי' צריך ג\"כ להיות בחי' מדידה בבחי' או\"כ שבמל'. וזהו ויבן ה' אלהים את הצלע דאו\"א תקינו לה כו' וכמ\"ש באר חפרוה שרים כו', אך זה הי' דוקא אחר שנפלה תרדמ\"ה על האד\"ם דלעילא אז ויקח אחת מצלעותי\"ו כו' שהוא בנין הנוק' דז\"א כידוע, והענין הוא להיות מבואר למעלה בבחי' הרצוא שהוא בבחי' האור בלא כלי היינו בחי' ההתנשאות וההתכללות אל עצמו דוקא עד שלא יפנה לקוראו, וכמו כאשר הוא טרוד ביותר כו'.\n<b>והנה</b> משל לטרדא זו יש בזה כמה מדרגו' חלוקות זו למעלה מזו, כמו הטרוד בעמקו' השכל אז כלולים המדות באותו השכל ולא ירגישם כלל, ע\"כ אינו אז בבחי' כלי להתפס לזולתו ע\"י קריאת שמם כמו כשיקרא חסדן או רחמן וכה\"ג, ומדרגה שלמעלה מזו הוא כאשר יטרד יותר בעומק השכל כ\"כ עד שיבולבל השגת השכל הראשון ואינו מרגישו כלל אז הוא קרוב יותר אל בחי' עצמותו שלמעלה מהשגת השכל לגמרי, וכן יש עוד טרדא בעצמו' פנימי' נפשו ביותר עד שגם הרצון והתענוג כלולים שם ולא יתפסו בקריאת שם כלל לעוררו לבחי' גלוי רצון ותענוג למטה, וה\"ז דומה בכלל לענין השינה שאז הוא כמו בחי' הטרדא בכלל ובפרט דהיינו בחי' התכללות והתנשאות אל עצמות הנפש ממש כי המוחין מסתלקים למעלה בעצמו' וכן הרצון והתענוג כו' וגם המדות והדבור כו' וכל כחות פנימיי' כראי' ושמיעה וריח כו' רק בחי' קיסטא דחיותא נשאר בלב להיות התנועה וההרגש באברי הגוף בלבד כידוע, ולזה א\"א לומר שיהי' נפנה לקוראו בשמו בעת השינה בכל שם פרטי שיש לו לכל כח מכחות נפשו כמו חכם או חסדן וכה\"ג וגם לא ע\"י שמו הכללי שקוראים אותו הכל כו' וד\"ל.\n<b>וכך</b> יובן למעלה בבחי' תרדמ\"ה שנפל על בחי' אדם העליון דאצי' שנק' דורמיטא בחי' הסתלקות המוחין למעלה בבחי' העצמות וכן שאר האורות עליונים"]]});
